UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-17-7frnt","style":"normal","children":[{"_type":"span","_key":"key-1-moa5w","text":"SEURAMALLISTOT","marks":["strong"]},{"_type":"span","_key":"key-3-k7sj6","text":"Mallisto","marks":["key-2-kwaij"]},{"_type":"span","_key":"key-5-547ic","text":"Tilauslomake\n","marks":["key-4-icvpu"]},{"_type":"span","_key":"key-6-jwsn4","text":"Henrik Stürmer ","marks":["strong"]},{"_type":"span","_key":"key-7-dlyvk","text":"Team Sales\n\n"},{"_type":"span","_key":"key-8-qy1ex","text":"Stadium Oy \n","marks":["strong"]},{"_type":"span","_key":"key-9-pi7gz","text":"Stadium Itäkeskus","marks":["strong"]},{"_type":"span","_key":"key-10-2zhjv","text":"Itäkatu 1 A 7\n"},{"_type":"span","_key":"key-11-akldk","text":"00930 Helsinki\n"},{"_type":"span","_key":"key-12-d57jm","text":"Mobil: +358 (0)40 867 9825\n"},{"_type":"span","_key":"key-13-busx7","text":"Direct: +358 (0)20 7900 275\n"},{"_type":"span","_key":"key-14-ens8b","text":"Fax: +358 (0)20 7900 279\n"},{"_type":"span","_key":"key-15-a0re5","text":"henrik.sturmer@stadium.fi\n"},{"_type":"span","_key":"key-16-njyen","text":"www.stadiumteamsales.fi"}],"markDefs":[{"_type":"link","_key":"key-2-kwaij","href":"/_emdash/api/media/file/01KZ3GK5AB6YW4GDTX2FZQNB18.pdf"},{"_type":"link","_key":"key-4-icvpu","href":"/_emdash/api/media/file/01KZ3GK5MWV7JRJH4ZD6VD3VWX.xls"}]}]' WHERE id = '01KZ3G94MG2EZJDQJPBC41NZZY';
UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-2-0h929","style":"h1","children":[{"_type":"span","_key":"key-1-2watk","text":"Voima-Jyri 500 -projekti ja Iso-Esan teesit"}]},{"_type":"block","_key":"key-5-w5nei","style":"normal","children":[{"_type":"span","_key":"key-3-eikjs","text":"Moni HYV:n keskustan salilla treenannut on huomannut Voima-Jyrin muuttuneen olemuksen ja aistinut treeneissä olevan ennen näkemätöntä määrätietoisuutta. Voima-Jyri aloitti toukokuussa valmentajansa Iso-Esan kanssa projektin, jossa parannetaan voimaa ja samalla tiputetaan painoa. Haastattelussa Iso-Esa paljastaa, mistä projektissa on kyse.\n\n"}],"markDefs":[{"_type":"link","_key":"key-4-nu767","href":"/_emdash/api/media/file/01KZ3GKERSBXT79MAYXAWTVJZ1.jpg"}]},{"_type":"image","_key":"key-6-zif02","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GKERSBXT79MAYXAWTVJZ1.jpg","url":"/_emdash/api/media/file/01KZ3GKERSBXT79MAYXAWTVJZ1.jpg"},"alt":"VJ-1"},{"_type":"block","_key":"key-11-cwet9","style":"blockquote","children":[{"_type":"span","_key":"key-9-u1yse","text":"Treeni ilman progressiota on pelleilyä.","marks":["em"]},{"_type":"span","_key":"key-10-tc0yl","text":"Iso-Esa"}]},{"_type":"block","_key":"key-49-7252s","style":"normal","children":[{"_type":"span","_key":"key-12-99ke0","text":"Mikä sai sinut lähtemään valmennusyhteistyöhön Voima-Jyrin kanssa?\n","marks":["strong"]},{"_type":"span","_key":"key-13-a1dnr","text":"Valmentajana haen haasteita, mutta odotan myös palkintoa. Semmoinen tuntuma on, että tästä on iso potti tulossa. Voima-Jyri on hiomaton timantti, jolla on paljon potentiaalia. Tämä motivoi minua valmentajana.\n\n"},{"_type":"span","_key":"key-14-e23tj","text":"Kerro hieman roolistasi Voima-Jyrin valmentajana.\n","marks":["strong"]},{"_type":"span","_key":"key-15-lk7g4","text":"Haluan hieman tarkentaa valmentajan käsitettä. Olen aerobisen puolen asiantuntija, enkä keskity Voima-Jyrin painoharjoittelun yksityiskohtiin. Sen sijaan luon ryhtiä treeniohjelmaan ylätasolla. Treenien pitää olla linjassa tavoitteiden kanssa. Konkreettinen esimerkki tämän viikon malliohjelmasta: viikonloppuna sekä kolmena arkipäivänä on aamulenkki ja lisäksi neljänä päivänä on voimaharjoittelua (2 jalkapäivää, 1 selkäpäivä ja 1 rinta/ käsitreenipäivä). Jalkapäivästä saatan antaa yleisen ohjeen tyyliin kyykky, pitkät sarjat 70% teholla. Tämän perusteella Voima-Jyri tietää, mitä tekee. Rooliani voisi verrata maajoukkue-valmentajan työhön: en ole päivittäin seuraamassa jokaista treeniä, mutta huolehdin siitä, että tekeminen keskittyy siihen, mikä on oikeasti tärkeää.\n\n"},{"_type":"span","_key":"key-16-isfaf","text":"Voima-Jyrillä on kuitenkin aika monta harjoitteluvuotta taustalla. Miten oma valmennustyösi eroaa siitä, mitä Voimaa aikaisemmat ohjanneet ovat tehneet?\n","marks":["strong"]},{"_type":"span","_key":"key-17-aece0","text":"Nyt on selkeästi isompi vaihde pelissä. Voima-Jyrin harjoittelussa on ollut niin selviä puutteita, että ihmetellä täytyy. Kuten totesin, keskityn siihen, että harjoittelun päälinjat ovat kunnossa. Aikaisempi ohjaus on sortunut näpertelyyn. Minä en ole niitä valmentajia, jotka hiovat polvikulmaa kyykyssä tai sitä, millä puolella tankoa peukaloa pidetään. Raaka totuus on, että maksimivoima kehittyy vain raskailla perusliikkeillä ja kovilla sarjoilla, ei sillä, että hiotaan tekniikkaa samoilla painoilla vuodesta toiseen. Ensin kuitenkin täytyy saada kestovoima paremmalle tasolle - maitohappoa lihaksiin ja kunnolla. Tästä lähdettiin toukokuussa liikkeelle ja tehdään töitä sen eteen, että tulokset nousevat radikaalisti.\n\n"},{"_type":"span","_key":"key-18-f11sy","text":"Taustasi on yleisurheiluvalmennuksesta. Mitä annettavaa yleisurheilulla on voimalajien valmentamiseen?\n","marks":["strong"]},{"_type":"span","_key":"key-19-9lirm","text":"Paljon. Yleisurheilun voimaharjoittelusta on huomattavasti tutkimustietoa ja olympialajeissa asenne valmentamiseen on ammattimaisempaa. Lisäksi tuon mukaan aerobisia elementtejä, esimerkiksi Voima-Jyri tekee kesäkautena useita juoksu- tai pitkiä kävelylenkkejä viikossa. Tällä luodaan treenikestävyyttä.\n\n"},{"_type":"span","_key":"key-20-d3d60","text":"Mitkä ovat projektinne tavoitteet?\n","marks":["strong"]},{"_type":"span","_key":"key-21-ih2do","text":"Projekti alkoi toukokuussa 2011 ja päättyy joulukuussa 2011. Käytämme tästä työnimeä "},{"_type":"span","_key":"key-22-6eju0","text":"Voima-Jyri 500","marks":["em"]},{"_type":"span","_key":"key-23-the97","text":". Tavoitteita on kaksi: maksimivoiman parantaminen sekä elopainon alentaminen.\n\n"},{"_type":"span","_key":"key-24-lz94u","text":"Ladoitte Voima-Jyrin kanssa kovan tavoitteen pöytään: voimanoston yhteistulos 500 kg vuoden 2011 loppuun mennessä. Tavoite tuntuu hurjalta, puhutaan yli 100 kilon tuloksen noususta. Millä eväin tulokseen päästään?\n","marks":["strong"]},{"_type":"span","_key":"key-25-g5ldb","text":"En pidä 500 kilon tulosta ollenkaan kovana. Voima-Jyrin perusvoimataso ja reservit ovat sitä luokkaa, että kuka tahansa vähänkin urheilusta tietävä valmentaa hänet 500 kilon kuntoon. Sen sijaan siinä vaaditaan taitoa, että tämän tehdään samalla, kun oma paino vedetään 100 kiloon. Aerobisen ja voimaharjoittelun yhdistäminen on alue, jossa minulla on annettavaa. Voimaharjoittelun yksityiskohdissa neuvojia salilla riittää varmasti liiaksikin. Pidän linjaa siinä, että perusasiat eli kova treeni on ennen teknistä hifistelyä.\n\n"},{"_type":"span","_key":"key-26-k0ocw","text":"Yleisurheilussa olet tottunut erittäin motivoituneisiin urheilijoihin, joilla ongelma on pikemminkin liian kova harjoittelu. Olet vaativa valmentaja. Kuinka uskot Voima-Jyrin motivaation kestävän ankaraa harjoittelua?\n","marks":["strong"]},{"_type":"span","_key":"key-27-4egn8","text":"Oikotietä koviin tuloksiin ei ole. Kun tähän projektiin lähdettiin, kumpikin osapuoli sitoutui 100 prosenttisesti. Minun ei tarvitse olla valmentajana seuraamassa joka harjoitusta. Tiedän, että Voima-Jyrillä on nyt kova tekemisen tahto päällä. Treeneistä on leikki kaukana.\n\n"},{"_type":"span","_key":"key-28-hofmk","text":"Kerro vielä dieettitavoitteestanne.\n","marks":["strong"]},{"_type":"span","_key":"key-29-gu5v8","text":"Mies pitää saada kuntoon. Dieetissä korostuu aerobisen harjoittelun merkitys, mutta myös ruokavaliolla on osansa. Projektin alkuvaiheessa paino saattaa jopa nousta, kun lihasmassa kasvaa. Tämä kompensoituu kuitenkin nopeasti. Ideana dieetissä ei ole pelkästään Wilks-kertoimiin tuijottaminen, vaan uskomme, että saamme Voima-Jyrin tehollisen kehopainosuhteen paremmin optimoitua alle 100 kilon tasolla. Sivutuotteena saadaan treenitehoa parannettua.\n\n"},{"_type":"span","_key":"key-30-e7i90","text":"Vedämme paljon pitkiä kävelylenkkejä alhaisella sykkeellä sekä asteittain piteneviä juoksulenkkejä. Aerobinen treenaus on siten pitkälti samantapaista kuin bodauksessa.\n\n"},{"_type":"span","_key":"key-31-zric3","text":"Miten rytmitätte harjoittelun viikko- tai kuukausitasolla?\n","marks":["strong"]},{"_type":"span","_key":"key-32-vqy9d","text":"Aerobinen on ohjelmassa periaatteessa koko ajan, paitsi ihan parina viimeisenä viikkona ennen joulukuun voimanostokisoja. Annan Voima-Jyrille tietyt raamit, esimerkiksi pari selkäpäivää ja jalkatreeniä viikossa, ja hän valitsee tarkemmat liikkeet. Tässä tapauksessa valmentajan työ helpottuu sikäli, että kokenut urheilija tietää, mitä tekee. Keskityn päälinjoihin, en siihen, tekeekö Voima-Jyri kyykkytreenin jälkeen ensin pohkeet ja sitten takareidet vai toisinpäin.\n\n"},{"_type":"span","_key":"key-33-bnar4","text":"Puhut paljon voimanostokisoista ja aerobisesta treenistä. Lupaatko suojattisi osallistua muihin Voimaliiga 2012 -osakilpailuihin?\n","marks":["strong"]},{"_type":"span","_key":"key-34-rrti1","text":"Ilman muuta. Painonpudotusprojektin myötä moni tulee yllättymään syksyn leuanvetokisoissa. Emme hae sieltä varsinaisesti sijoitusta, mutta tulosta kylläkin. Hyvin varmasti laitan Voima-Jyrin myös uutuuskisaan, etukyykky sopii mainiosti ohjelmaan. Heikompia hirvittää, ja kohta myös vahvempia.\n\n"},{"_type":"span","_key":"key-35-4fkq7","text":"Minkälainen merkitys kesäharjoittelulla on?\n","marks":["strong"]},{"_type":"span","_key":"key-36-58lhz","text":"Kun projekti on puolivuotinen, kesätreeni muodostaa kaiken pohjan. Iso kuva on tämä: kesällä luodaan niin kova harjoittelupohja, että syksyn kuluessa voidaan vetää erittäin kovat treenit läpi rikkomatta paikkoja.\n\n"},{"_type":"span","_key":"key-37-ocep9","text":"Olet lanseerannut Voima-Jyrin aerobiseen treeniin käsitteen power walk. Kerrotko tästä hieman lisää.\n","marks":["strong"]},{"_type":"span","_key":"key-38-0p8tk","text":"Voima-Jyrin juoksu- ja kävelytreeneissä on ollut tiettyä tehon puutetta havaittavissa. Tavallinen kävely on hänelle hieman liian kevyenä treenimuotona. Lisäksi haluttiin voimaharjoittelua tukevaa, motivoivampaa treenimetodia. Power walk''issa ideana on kohdistaa kävelyyn mahdollisimman paljon voimaa. Liikeradoissa korostuu intensiteetti. Voimaa Jyrillä on riittävästi. Kun keskuspuistossa kokeilimme power walk''ia leimikossa, ranteenpaksuiset koivut katkesivat vaivatta Voima-Jyrin tieltä.\n\n"},{"_type":"span","_key":"key-39-b2um8","text":"Oletko valmis ottamaan muita HYV:n jäseniä valmennettaviksesi?\n","marks":["strong"]},{"_type":"span","_key":"key-40-mnafd","text":"Kyselyjä on jonkin verran tullut, mutta olen kieltäytynyt kohteliaasti. Kun urheilija on tosissaan ja tekee hartiavoimin töitä tavoitteen eteen, myös valmennuspuolelta vaaditaan sitoutumista. "},{"_type":"span","_key":"key-41-fw5fw","text":"Voima-Jyri 500 ","marks":["em"]},{"_type":"span","_key":"key-42-3o2yf","text":"on myös valmentajan kannalta sen verran kokonaisvaltainen projekti, että aikani ei riitä tällä hetkellä muihin valmennettaviin.\n\n"},{"_type":"span","_key":"key-43-r9voq","text":"Minkälainen on Iso-Esan valmennusfilosofia?\n","marks":["strong"]},{"_type":"span","_key":"key-44-t01ch","text":"Kaksi prinsiippiä. Yksi, valmentaminen on prosessi. Tässä ei mietitä yhtä yksittäistä kisaa, vaan edetään systemaattisen harjoittelun kautta tasaisesti ylöspäin. Toinen prinsiippi on mentaalinen. Harjoittelussa tarvitaan lahjojen lisäksi asennetta, jonka merkitystä ei voi aliarvioida. Henkisen lujuuden täytyy heijastua päivittäiseen harjoitteluun, aina jokaiseen sarjaan asti.\n\n"},{"_type":"span","_key":"key-45-jn576","text":"Mikä on valmennusmottosi?\n","marks":["strong"]},{"_type":"span","_key":"key-46-phg3r","text":"Treeni ilman progressiota on pelleilyä.\n\n"},{"_type":"span","_key":"key-47-1wsq3","text":" \n\n"},{"_type":"span","_key":"key-48-t3dtc","text":" "}]}]' WHERE id = '01KZ3G95M5VBESVE5QR815Z72Y';
UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-2-lcqrf","style":"h1","children":[{"_type":"span","_key":"key-1-ap11x","text":"Voima-Jyri 500 -projekti"}]},{"_type":"block","_key":"key-5-btxxi","style":"h2","children":[{"_type":"span","_key":"key-4-46f8o","text":""}],"markDefs":[{"_type":"link","_key":"key-3-fstul","href":"/_emdash/api/media/file/01KZ3GKFCXP8DG6T1YY89TXK8K.jpg"}]},{"_type":"block","_key":"key-7-en7i1","style":"h2","children":[{"_type":"span","_key":"key-6-74azc","text":"Mistä on kysymys?"}]},{"_type":"block","_key":"key-10-4ie6e","style":"normal","children":[{"_type":"span","_key":"key-8-pdqvr","text":"Voima-Jyri 500 -projekti viittaa 500 kilon yhteistulokseen voimanostossa (kyykky, penkki, maastanosto). Voima-Jyrin tavoitteena on 500 kilon haamurajan rikkominen. Projektiin on myös liitetty erilaisia dieettitavoitteita ja aerobisen kunnon kohottamista. Voima-Jyri 500-projekti toimii inspiraation lähteenä myös maltillisemmilla tavoitteilla treenaaville.\n\n"},{"_type":"span","_key":"key-9-ail5o","text":"Voima-Jyrillä on usean vuoden kokemus tavoitteellisesta voimaharjoittelusta ja kilpailutausta usemmasta lajista. Voima-Jyrin harjoittelee valmentajien valvonnassa. Hänen harjoitteitaan tai harjoitusperiaatteitaan ei siis kannata sellaisenaan kopioida."}]},{"_type":"block","_key":"key-12-9deik","style":"h2","children":[{"_type":"span","_key":"key-11-5cll2","text":"Tähän mennessä tapahtunut"}]},{"_type":"block","_key":"key-16-b8tyw","style":"normal","children":[{"_type":"span","_key":"key-13-uoa6e","text":"Voima-Jyri 500 -projekti alkoi kesällä 2011. Tällä sivulla seuraamme projektin etenemistä ja luomme katsauksen Voima-Jyrin aikaisempiin saavutuksiin.\n\n"},{"_type":"span","_key":"key-14-bvhhu","text":"Tästä kaikki alkoi","marks":["strong"]},{"_type":"span","_key":"key-15-qw12u","text":": Voima-Jyrin ja Iso-Esan valmennusyhteistyö käynnistyi kesällä 2011."}]},{"_type":"block","_key":"key-18-2ed9g","style":"h3","children":[{"_type":"span","_key":"key-17-bdtb5","text":"Tuotantokaudet"}]},{"_type":"block","_key":"key-22-iyr93","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-20-4nq1b","text":"yhteenveto tuotantokausista","marks":["key-19-5k8kx"]},{"_type":"span","_key":"key-21-hsssf","text":" 2010 alkaen"}],"markDefs":[{"_type":"link","_key":"key-19-5k8kx","href":"http://hyvoimailijat.com/?page_id=417"}]},{"_type":"image","_key":"key-25-nlza7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GM5V8M4B92290WFAKAE9M.png","url":"/_emdash/api/media/file/01KZ3GM5V8M4B92290WFAKAE9M.png"},"alt":"vj500logokausi5"},{"_type":"image","_key":"key-28-z1tu7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GM9B94X21PWRAEHSACD3K.png","url":"/_emdash/api/media/file/01KZ3GM9B94X21PWRAEHSACD3K.png"},"alt":"elclasico"},{"_type":"image","_key":"key-31-mvr96","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMY92BX7MHKZPYDS2KCVZ.png","url":"/_emdash/api/media/file/01KZ3GMY92BX7MHKZPYDS2KCVZ.png"},"alt":"onlinelogomaker-082614-1428082614-1458082614-1519"},{"_type":"image","_key":"key-34-4w9ez","asset":{"_type":"reference","_ref":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2015/05/image1.png","url":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2015/05/image1.png"},"alt":"image1"},{"_type":"block","_key":"key-37-d3dud","style":"h3","children":[{"_type":"span","_key":"key-36-7ldyp","text":"Videot"}]},{"_type":"block","_key":"key-39-hi789","style":"h3","children":[{"_type":"span","_key":"key-38-i6zno","text":""}]},{"_type":"block","_key":"key-44-hlx40","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-41-b9f2i","text":"Voima-Jyrin 100 kunnian päivää","marks":["key-40-rnazb"]},{"_type":"span","_key":"key-42-d1k4o","text":" (julkaistu 26.8.2015) "},{"_type":"span","_key":"key-43-hpszs","text":"UUSI","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-40-r