","_key":"key-34-8u6jj","text":"Tarkat tulokset: "},{"_type":"span","_key":"key-36-bnin3","text":"Voimanosto2013","marks":["key-35-bvdo2"]}],"markDefs":[{"_type":"link","_key":"key-35-bvdo2","href":"/_emdash/api/media/file/01KZ3GK41CM6P2AZ6WDNERGE1M.pdf"}]}]' WHERE id = '01KZ3GBB4NA3RFXP7X919ZKXQ6';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-18-oj47d","style":"normal","children":[{"_type":"span","_key":"key-1-nmzew","text":"Tulokset\n","marks":["strong"]},{"_type":"span","_key":"key-2-4mgzv","text":"Naiset\n"},{"_type":"span","_key":"key-3-it9ct","text":"1. Teräs-Tiia 5.09 (CR)\n"},{"_type":"span","_key":"key-4-nesvt","text":"2. Pia 7.04 (PB)\n"},{"_type":"span","_key":"key-5-q8cg5","text":"Miehet\n"},{"_type":"span","_key":"key-6-q4rlb","text":"1. Puntti-Petri 8.29 (CR)\n"},{"_type":"span","_key":"key-7-3brlw","text":"2. Dima 23:20 (kilpailun ulkopuolella)\n"},{"_type":"span","_key":"key-8-ajec5","text":"Donkki-Ivan DNF\n\n"},{"_type":"span","_key":"key-9-g78er","text":"Tarkemmat tulokset:\n"},{"_type":"span","_key":"key-11-1w3pu","text":"Hilkka Crossfit 25 1 2014\n","marks":["key-10-jjlzt"]},{"_type":"span","_key":"key-12-wqsw6","text":"Ennätyksiä ja dramatiikkaa tammikuun Hilkassa\n\n","marks":["strong"]},{"_type":"span","_key":"key-13-d07is","text":"Molemmissa sarjoissa tehtiin uudet kisaennätykset. Miesten sarjassa Puntti-Petri paransi viime vuoden voittoaikaansa lähes 50 sekuntia. Kiivaassa tahdissa nähtiin sellainenkin erikoisuus, että 67.5kg penkkipaino jäi kolmen toiston sarjan viimeisessä toistossa rinnalle ja nousi vasta pienen tauon jälkeen.\n\n"},{"_type":"span","_key":"key-14-zjy6v","text":"Kisassa nähtiin myös dramatiikkaa, sillä kova haastaja Donkki-Ivan kärsi vielä sisäreisivammasta, joka pakotti jättämään kilpailun kesken 9-toiston kierroksella. \"En halunnut ottaa riskiä isommasta loukkaantumisesta, nyt on katse jo seuraavassa kisassa\", Donkki-Ivan totesi. Hän esitteli kisassa myös potentiaalisen uuden jäsenen Diman. Dima ei täysin pystynyt voimalla kompensoimaan aerobista kuntoa, mutta , sinnikkäästi veti suorituksen läpi kisan ulkopuolella\n\n"},{"_type":"span","_key":"key-15-l7bfn","text":"Naisten kisassa ensimmäisenä matkaan lähti Pia, jonka aika kohahdutti yleisöä. Pia kiersi radan seitsemän minuutin pintaan, jota ratamestari Super-Sampsa ei pitänyt ennakkoon mahdollisena. Meno yltyi vielä hurjemmaksi, kun häkellyttävällä alkuvauhdilla matkaan lähtenyt Teräs-Tiia kesti samaa tahtia loppuun asti. Kahvakuula miellytti häntä niin paljon, että vetäisi matkalla muutaman ylimääräisenkin suorituksen tuomarin pyynnöstä. Loppuaika oli tyrmäävä 5:09. Vaikka yhdistys oli heittänyt kehiin kokeneimman ajanottajansa Voima-Jyrin, oli Teräs-Tiian vauhti niin kova, että osa väliajoista jäi saamatta. Naisten kisailijat lähettivät Super-Sampsalle terveisiä ja toivoivat ensi kerraksi isompia painoja. Nyt kilpailijattaret tuskin hengästyivät suorituksestaan.\n\n"},{"_type":"span","_key":"key-16-onssl","text":"Teräs-Tiia vaikutti innostuneelta debyyttikisastaan. Välittömästi kisasuorituksen jälkeen virtaa riitti harjoitella vielä julkaisematonta haastettaan, jonka Teräs-Tiia aikoo tietojemme mukaan esittää kevään kuluessa haasteistaan kuululle Hurja-Harrille.\n\n"}],"markDefs":[{"_type":"link","_key":"key-10-jjlzt","href":"/_emdash/api/media/file/01KZ3GK9SCTPW0JQ13Y8C4BAKR.pdf"},{"_type":"link","_key":"key-17-qvxa0","href":"/_emdash/api/media/file/01KZ3GK9F27DN5A78HKGSFWE8Z.jpg"}]},{"_type":"image","_key":"key-19-tiza5","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK9F27DN5A78HKGSFWE8Z.jpg","url":"/_emdash/api/media/file/01KZ3GK9F27DN5A78HKGSFWE8Z.jpg"},"alt":"WP_000711"},{"_type":"image","_key":"key-22-m2b2k","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK670MZF1BPR3DT7TMF4W.png","url":"/_emdash/api/media/file/01KZ3GK670MZF1BPR3DT7TMF4W.png"},"alt":"vlcsnap-2014-01-25-22h00m49s91"},{"_type":"image","_key":"key-25-cp4hh","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK8ANQPCZ7WV1JADS874Q.png","url":"/_emdash/api/media/file/01KZ3GK8ANQPCZ7WV1JADS874Q.png"},"alt":"vlcsnap-2014-01-26-19h58m56s106"},{"_type":"image","_key":"key-28-0dh1c","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK8PFRAWQA9S6FWRFRDYV.png","url":"/_emdash/api/media/file/01KZ3GK8PFRAWQA9S6FWRFRDYV.png"},"alt":"vlcsnap-2014-01-26-19h56m44s68"},{"_type":"image","_key":"key-31-g9r6z","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK93SJR8CM017C28A3BQP.png","url":"/_emdash/api/media/file/01KZ3GK93SJR8CM017C28A3BQP.png"},"alt":"vlcsnap-2014-01-26-19h55m40s243"},{"_type":"image","_key":"key-34-9425q","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK7YXDRVGY79DKTXDX0KA.png","url":"/_emdash/api/media/file/01KZ3GK7YXDRVGY79DKTXDX0KA.png"},"alt":"vlcsnap-2014-01-26-19h59m36s209"},{"_type":"image","_key":"key-37-we08u","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK7JNSKY28H7FANYGZ7PW.png","url":"/_emdash/api/media/file/01KZ3GK7JNSKY28H7FANYGZ7PW.png"},"alt":"vlcsnap-2014-01-26-20h01m42s207"},{"_type":"image","_key":"key-40-cxpel","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK77HRW0BDXBGC2PXTDW0.png","url":"/_emdash/api/media/file/01KZ3GK77HRW0BDXBGC2PXTDW0.png"},"alt":"vlcsnap-2014-01-26-20h02m11s15"},{"_type":"image","_key":"key-43-x1e3q","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GK6W5WZEJTE2004N6G0VT.png","url":"/_emdash/api/media/file/01KZ3GK6W5WZEJTE2004N6G0VT.png"},"alt":"vlcsnap-2014-01-26-20h03m03s31"}]' WHERE id = '01KZ3GBC8E52SC3MSR3VS0R4FG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-4-pxqrn","style":"normal","children":[{"_type":"span","_key":"key-1-byn67","text":"Styrkka-Leon aamujumppa 8.3.2014 - Crossfit-tapahtuma lajin huipulta\n","marks":["strong"]},{"_type":"span","_key":"key-2-udbps","text":"Helsingin yliopiston voimailijat järjestää lauantaina 8.3.2014 poikkeuksellisen kovatasoisen crossfit-kilpailun. Kilpailun lajina on virallinen crossfit-suoritus Linda. Lisäksi tapahtumassa tarjotaan mahdollisuus suorittaa sprinttiversio Linda Lite. Kummankin lajin kuvaukset löytyvät alta.\n\n"}],"markDefs":[{"_type":"link","_key":"key-3-bt7jy","href":"/_emdash/api/media/file/01KZ3GKABTJVZRD45KC8B109K2.jpg"}]},{"_type":"image","_key":"key-5-al5l6","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GKABTJVZRD45KC8B109K2.jpg","url":"/_emdash/api/media/file/01KZ3GKABTJVZRD45KC8B109K2.jpg"},"alt":"Styrkka-1"},{"_type":"block","_key":"key-22-uswvd","style":"normal","children":[{"_type":"span","_key":"key-6-wkfn0","text":"\n"},{"_type":"span","_key":"key-7-atuhb","text":"Kuva: "},{"_type":"span","_key":"key-8-i0q3q","text":"Dramaattinen pistelaskutilanne Voima-Jyri 500 -kilpailusta 15.12.2012. Styrkka-Leo ohitti Wilks-pisteissä itsensä Voima-Jyrin.\n","marks":["em"]},{"_type":"span","_key":"key-9-vc8qc","text":"Perinteeksi muodostuneen tavan mukaan Helsingin yliopiston voimailijat haluaa kunnioittaa osakilpailujen nimeämisellä ansioituneita jäseniään. Järjestäjät ovat panneet merkille kilpailukauden 2012-2013 tulokkaan, Styrkka-Leon esiintymisen. Styrkka-Leo on kestänyt paineet ja pystynyt lunastamaan lupauksensa menestymällä erinomaisesti voimanostokisoissa. Kovana maastanostajana tunnettu Styrkka on pelotta haastanut kovimpia mahdollisia vastustajia ja voittanut itsensä Voima-Jyrin Wilks-pisteillä kahdessa perättäisessä kilpailussa. Näiden meriittien perusteella HYV halusi nimetä crossfit-kilpailun Styrkka-Leon kunniaksi.\n\n"},{"_type":"span","_key":"key-10-1k8cg","text":"Huippukova osanottajakaarti\n","marks":["strong"]},{"_type":"span","_key":"key-11-x42z0","text":"Kilpailuun on ilmoittanut osallistuvansa Styrkka-Leo, joka kisaa Linda Lite -sarjassa. Styrkan aikatavoite on jäätävä: hän pyrkii kisassa kahdeksan minuutin aikaan. \"Jos joku muu alittaa 8 minuuttia, hän luultavasti voittaisi, mutta pidän tätä erittäin epätodennäköisenä\", Styrkka-Leo toteaa. Naisten vastaavaan sarjaan on kiinnitetty Teräs-Tiia, joka voitti debyyttikisassaan Hilkka Crossfit-tapahtuman 25.1.2014.\n\n"},{"_type":"span","_key":"key-12-md202","text":"Linda - mistä on kysymys?\n","marks":["strong"]},{"_type":"span","_key":"key-13-3csfb","text":"Lindaan kuuluu 10 kierrosta ja joka kierrokseen kolme lajia tässä järjestyksessä: maastanosto, penkki, rinnalleveto. Ensimmäisellä kierroksella tehdään 10-10-10 toistoa, sitten 9-9-9 jne. aina viimeisen kierroksen 1-1-1 toistoon. Kello käy koko ajan, nopein aika voittaa. Painot skaalataan nostajan painon mukaan seuraavilla kertoimilla: maastanosto 1.5, penkki 1.0, rinnalleveto 0.75 kertaa oma paino. Nostopaino pyöristetään ylöspäin 2.5 kilon tarkkuudella. Linda Lite -sarjassa nostopaino jaetaan kahdella (rinnallevedon kerroin on 0.3). Kertoimet ovat miehille ja naisille samat.\n\n"},{"_type":"span","_key":"key-14-06jt3","text":"Esimerkki: 77 kg painavan urheilijan painot ovat 117.5 - 77.5 - 60.0 ja Linda Lite -sarjassa 60 - 40- 25.\n\n"},{"_type":"span","_key":"key-15-6fycp","text":"Lindassa hyvä tavoiteaikataulu miehille on 30 minuuttia, Linda Litessa 12 minuuttia. Linda Lite -sarjassa kilpailija saa kaksi pistettä vähemmän kuin normaalissa osakilpailujen pisteytyskäytännössä.\n\n"},{"_type":"span","_key":"key-16-mxiul","text":"Suoritustekniikka\n","marks":["strong"]},{"_type":"span","_key":"key-17-qssfl","text":"Vyön käyttö on sallittu, vetoremmien ei. Rinnalleveto täytyy tehdä kyykyn kautta (kyykyssä kisasyvyys). Penkki on tavallinen penkki; kosketus riittää, ei vaadita pysäytystä.\n\n"},{"_type":"span","_key":"key-18-k94of","text":"Aikataulu\n","marks":["strong"]},{"_type":"span","_key":"key-19-yxio3","text":"Huomaa, että kilpailu alkaa jo klo 10.15 naisten sarjalla. Kisa vaatii suhteellisen paljon tilaa ja kolme tankoa. Samon suoritusten kestot ovat Linda Litea lukuunottamatta pitkiä. Aikaisella aloitusajalla haluamme varmistaa, ettei muille salin käyttäjille aiheudu kohtuutonta haittaa. Sali avautuu lauantaina 9.45, joten kannattaa tulla ajoissa verryttelemään.\n\n"},{"_type":"span","_key":"key-20-bn1ag","text":" \n\n"},{"_type":"span","_key":"key-21-fksh0","text":" "}]}]' WHERE id = '01KZ3GBD71P1T3QJ72FTQJ08G4';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-diw79","style":"normal","children":[{"_type":"span","_key":"key-1-sym5r","text":"Naiset, Linda Lite\n","marks":["strong"]},{"_type":"span","_key":"key-2-lcndp","text":"1. Emma L. 10:44.2 (63.3kg, käytetyt painot 47.5-32.5-20.0), 12 p\n"},{"_type":"span","_key":"key-3-kwawh","text":"2. Teräs-Tiia 16:32.5 (63.3kg, 47.5-32.5-20.0), 9p\n\n"},{"_type":"span","_key":"key-4-o55oi","text":"Miehet, Linda\n","marks":["strong"]},{"_type":"span","_key":"key-5-4k3kt","text":"1. Puntti-Petri 26:23.3 (88.8kg, 135-90-67.5) 12 p\n\n"},{"_type":"span","_key":"key-6-kbye6","text":"Miehet, Linda Lite\n","marks":["strong"]},{"_type":"span","_key":"key-7-8rnxm","text":"1. Styrkka-Leo 8:07.1 (73.2kg, 55-37.5-27.5) 10 p\n"},{"_type":"span","_key":"key-8-pft4t","text":"2. Veto-Axu 11:10.4 (82.8kg, 62.5-42.5-25) 7 p\n\n"},{"_type":"span","_key":"key-9-hkayv","text":"Tuomari: Julma-Jyrki\n\n"}],"markDefs":[{"_type":"link","_key":"key-10-2jc5l","href":"/_emdash/api/media/file/01KZ3GKBGCZKXPWZ5EFHTJ1WMR.jpg"}]},{"_type":"image","_key":"key-12-t520e","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GKBGCZKXPWZ5EFHTJ1WMR.jpg","url":"/_emdash/api/media/file/01KZ3GKBGCZKXPWZ5EFHTJ1WMR.jpg"},"alt":"IMG_2165"},{"_type":"block","_key":"key-28-l20hh","style":"normal","children":[{"_type":"span","_key":"key-13-qvsjc","text":"\n"},{"_type":"span","_key":"key-14-jl4gl","text":"Vasemmalta Veto-Axu, Teräs-Tiia, Puntti-Petri ja debyyttikisansa voittanut Emma L.\n\n"},{"_type":"span","_key":"key-15-8ebg6","text":"Väliaikoja","marks":["strong"]},{"_type":"span","_key":"key-16-76tio","text":"Taulukossa kierroksen loppuaika. Styrkan aika 8. kierroksen lopussa oli noin 5 minuuttia.\n\n"},{"_type":"span","_key":"key-17-3i30a","text":"Teräs-Tiia   Emma L.  Veto-Axu  Styrkka-Leo   Puntti-Petri\n"},{"_type":"span","_key":"key-18-o4gnp","text":"10   1.38    1.04         0.57\n"},{"_type":"span","_key":"key-19-evrlm","text":"9     3.24    2.22         2.07\n"},{"_type":"span","_key":"key-20-fge7n","text":"8     4.50    3.50         3.30\n"},{"_type":"span","_key":"key-21-rffav","text":"7     8.14    5.29         5.00           n. 5 min\n"},{"_type":"span","_key":"key-22-250be","text":"6   11.00    7.01         6.39\n"},{"_type":"span","_key":"key-23-olr61","text":"5   12.51    8.25         8.04\n"},{"_type":"span","_key":"key-24-dd1a5","text":"4   14.18    9.18         9.27\n"},{"_type":"span","_key":"key-25-6vc4s","text":"3   15.30    9.57           --                                  24.05\n"},{"_type":"span","_key":"key-26-xm949","text":"2   16.09    10.25         --\n"},{"_type":"span","_key":"key-27-gok5c","text":"1   16.32,5  10.44,2  11.10,4"}]}]' WHERE id = '01KZ3GBF7FQE7KRTS4PTX16DMG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-yxxwl","style":"normal","children":[{"_type":"span","_key":"key-1-ng5da","text":"Hallintorakennuksella pidettiin 2.4.2014 sotilaspenkkikisa joka osoittautui kauden suosituimmaksi lajiksi. \n\n"}],"markDefs":[{"_type":"link","_key":"key-2-hf9g3","href":"/_emdash/api/media/file/01KZ3GKDHP78NJ1CFR672G0FHA.jpg"}]},{"_type":"image","_key":"key-4-hrtsf","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GKDHP78NJ1CFR672G0FHA.jpg","url":"/_emdash/api/media/file/01KZ3GKDHP78NJ1CFR672G0FHA.jpg"},"alt":"IMG_2178"},{"_type":"block","_key":"key-10-q356c","style":"normal","children":[{"_type":"span","_key":"key-5-ebqmt","text":"\n"},{"_type":"span","_key":"key-6-qve0a","text":"Naisten sarjan voitti Jenna viidellätoista toistolla.\n"},{"_type":"span","_key":"key-7-3u2rn","text":"Miesten sarjassa voitto meni Esa:lle 33:lla toistolla.\n\n"},{"_type":"span","_key":"key-9-lwc18","text":"HYV sotilaspenkki tulokset 4.2014","marks":["key-8-kymn0"]}],"markDefs":[{"_type":"link","_key":"key-8-kymn0","href":"/_emdash/api/media/file/01KZ3GKE6K8C7637DX49RFWSS7.pdf"}]}]' WHERE id = '01KZ3GBHBB7PNB1S85XVB67RAB';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-s6s11","style":"h2","children":[{"_type":"span","_key":"key-1-mv4ey","text":"Ennätyksiä ja dramatiikkaa - Pepe Salosen muistokilpailun 2014 kohokohdat"}]},{"_type":"block","_key":"key-4-mtjrv","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-3-ttj00","text":"naisten kilpailussa tehtiin historiaa. Kilpailun kaikki osanottajat rikkoivat aikaisemman HYV:n kisaennätyksen (Sali-Sari, 227.5 kg). Jenna sai kultaa yhteistuloksella 255 kg."}]},{"_type":"block","_key":"key-6-n6uf0","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-5-q59sm","text":"myös lajien tulostaso oli kova: kaikki naiset rikkoivat 100 kilon rajan maastanostossa, Emma nosti parhaimmillaan 120 kg. Kyykyssä Jennan 95 kg ja Liisan 85 kg olivat kovimmat tulokset. Elina sai näyttävässä paluussaan penkistä 57.5 kg."}]},{"_type":"block","_key":"key-8-69fk5","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-7-c5ii1","text":"miesten kilpailussa Petri ja debytoija Simo tekivät yhteistulosennätyksensä. Molemmat tekivät lisäksi kyykyssä ja maastanostossa omat ennätyksensä."}]},{"_type":"block","_key":"key-13-9b99x","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-9-dg1lr","text":"kisan seuratuin urheilija "},{"_type":"span","_key":"key-11-l4y8u","text":"Voima-Jyri","marks":["key-10-zp943"]},{"_type":"span","_key":"key-12-jwuao","text":" taisteli paineita, tulostavoitteita ja Wilks-pisteissä myös naisia vastaan. Voima teki uuden ennätyksensä ja rikkoi 400 kg rajan. Valmentajaa ei ole vielä tavoitettu kommentteja varten."}],"markDefs":[{"_type":"link","_key":"key-10-zp943","href":"http://hyvoimailijat.com/?page_id=354"}]},{"_type":"block","_key":"key-15-c729r","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-14-yvsbd","text":"HYV:n Voimaliigan lopulliset sijat ratkesivat viimeisessä osakilpailussa. Miesten kisan vei Petri ja naisten kiertopalkinnon Emma."}]},{"_type":"image","_key":"key-16-azzhw","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GKT2JT8C5W86JS5WJWS2Z.jpg","url":"/_emdash/api/media/file/01KZ3GKT2JT8C5W86JS5WJWS2Z.jpg"},"alt":"DSC06717"},{"_type":"block","_key":"key-19-u6mfw","style":"normal","children":[{"_type":"span","_key":"key-18-d7mog","text":"Voimanosto2014_kevät","marks":["key-17-1yox0"]}],"markDefs":[{"_type":"link","_key":"key-17-1yox0","href":"/_emdash/api/media/file/01KZ3GKSS07K2PA8H8FX5PA9A6.pdf"}]}]' WHERE id = '01KZ3GBJB2F90BMH9WZ9FCPFZT';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-thc0w","style":"normal","children":[{"_type":"span","_key":"key-1-k9496","text":"Meilahdessa 6.9.2014 käytiin tiukka voimailukilpailu, jossa voitto heltisi Donkki-Ivanille kahden pisteen erolla Julma-Jyrkiin.\n\n"}],"markDefs":[{"_type":"link","_key":"key-2-dnk2o","href":"/_emdash/api/media/file/01KZ3GM9ZTDB0NJJW3FFQTFS1C.jpg"}]},{"_type":"image","_key":"key-4-c1wut","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GM9ZTDB0NJJW3FFQTFS1C.jpg","url":"/_emdash/api/media/file/01KZ3GM9ZTDB0NJJW3FFQTFS1C.jpg"},"alt":"DSC08824"},{"_type":"block","_key":"key-9-y3rhc","style":"normal","children":[{"_type":"span","_key":"key-5-2nwxs","text":"\n"},{"_type":"span","_key":"key-6-241hm","text":"Kaikki tulokset: "},{"_type":"span","_key":"key-8-lgnjs","text":"Voimailukilpailu_Meilahti_2014","marks":["key-7-yi1lf"]}],"markDefs":[{"_type":"link","_key":"key-7-yi1lf","href":"/_emdash/api/media/file/01KZ3GMAMXVAS58NN2B1N007Q6.pdf"}]}]' WHERE id = '01KZ3GBQKEWDBYMPV0TQTZNJDK';
