UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-4-nlhki","style":"normal","children":[{"_type":"span","_key":"key-1-ogdho","text":"Juha Kovistolle SM kultaa Voimapunnerruksen SM kisassa tuloksella 157.5 kg\n\n"},{"_type":"span","_key":"key-2-ycvpm","text":"HYV ry onnittelee Juhaa huppusuorituksesta!\n\n"}],"markDefs":[{"_type":"link","_key":"key-3-d7knk","href":"/_emdash/api/media/file/01KZ3GMM01AHRHC0STWR6F2A0W.jpg"}]},{"_type":"image","_key":"key-5-7pw6e","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMM01AHRHC0STWR6F2A0W.jpg","url":"/_emdash/api/media/file/01KZ3GMM01AHRHC0STWR6F2A0W.jpg"},"alt":"Juha Koiivisto SM 2014 Viitasaari"},{"_type":"block","_key":"key-11-fc711","style":"normal","children":[{"_type":"span","_key":"key-6-kina0","text":"\n"},{"_type":"span","_key":"key-7-h58rl","text":"TULOKSET:\n\n"},{"_type":"span","_key":"key-9-iysmt","text":"http://svry.fi/uploads/Tulokset%202014/MAKSIMIVOIMAPUNNERRUS%2029.11.2014%20TULOKSET.pdf\n","marks":["key-8-ao8in"]},{"_type":"span","_key":"key-10-7p8cb","text":" "}],"markDefs":[{"_type":"link","_key":"key-8-ao8in","href":"http://svry.fi/uploads/Tulokset%202014/MAKSIMIVOIMAPUNNERRUS%2029.11.2014%20TULOKSET.pdf"}]}]' WHERE id = '01KZ3GBX808YNGV7B1KF0QS5SF';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-nydxs","style":"h4","children":[{"_type":"span","_key":"key-2-onges","text":"Joulukuun kisassa silti kovia tuloksia, ennätyksiä ja upeita debyyttejä.","marks":["strong"]}]},{"_type":"image","_key":"key-6-q13fb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMP9CMGWYVVJX7XJ87A7V.jpg","url":"/_emdash/api/media/file/01KZ3GMP9CMGWYVVJX7XJ87A7V.jpg"},"alt":"DSC09242"},{"_type":"image","_key":"key-9-77yn0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMMTTSDDC9FZPF8SRJMSP.jpg","url":"/_emdash/api/media/file/01KZ3GMMTTSDDC9FZPF8SRJMSP.jpg"},"alt":"DSC_1051"},{"_type":"block","_key":"key-18-f4gke","style":"normal","children":[{"_type":"span","_key":"key-10-61h15","text":"\n"},{"_type":"span","_key":"key-11-vkdmz","text":"Joulukuun kisaa sävyttivät monen jäsenen kisaaminen toipilaana, mutta myös lukuisat ennätykset ja komeat debyytit.\n\n"},{"_type":"span","_key":"key-12-4j91h","text":"Jälleen kerran käytiin kovatasoinen HYVin jäsenten välinen klassinen voimanostokilpailu Unisportin hallintorakennuksen salilla. Kolmen viikon flunssa vei Voima-Jyrin kuntohuipun ja toipilaana paikalla ollut mestari tyytyi tuomaroimaan muita nostajia. Voima-Jyrin haastatteluun palaamme myöhemmin.\n\n"},{"_type":"span","_key":"key-13-wro3s","text":"Veto-Ville teki huiman comebackin voittamalla Wilksin pisteillä kisan. Naisten kilpailussa saatiin uusi voittaja Katariina P, Kisa oli Katariina P:n debyyttikisa. Naisten kisa oli äärimmäisen tiukka ja ratkesi puolen pisteen erolla.\n\n"},{"_type":"span","_key":"key-14-xlt3a","text":"Kisassa tehtiin useita henkilökohtaisia ennätyksiä. Kilpailun kovin tulos oli Katariina P:n maastanosto 155 kg, joka on HYVin naisten maastonostoennätys, Jennan teki HYV:n naisten kyykkyennätyksen, 100 kg. Katariinan tulos oli miehet mukaanlukien Wilksin pisteillä kilpailun kovin maastavetotulos ja 2014 Suomen naisten tilastossakin 6. paras raw-tulos. Myös Jenna ylitti aikaisemman HYV:n maastavetoennätyksen.\n\n"},{"_type":"span","_key":"key-15-09qsd","text":"Miehissä Axu onnistui maastonostossa 230 kg omalla ennätyksellään ja Ivan kyykkäsi huimat 200 kg. Axu testasi rautoja jopa HYV:n vetoennätyspainoilla 237.5 kg, mutta tällä kertaa rautaa oli liikaa. Puntti-Pete nosti ylimääräisellä suorituksella kisan ulkopuolella oman maastavetoennätyksensä 227.5 kg. Styrkka-Leo nosti niinikään maastavedossa ennätyksensä 180 kg.\n\n"},{"_type":"span","_key":"key-16-qu8gl","text":"Muista debytoijista mainittakoon Markku, joka oli koko syksyn valmistautunut Voima-Jyrin kohtaamiseen. Voima-Jyrin vetäytyminen kisasta oli Markulle pettymys, mutta ennakoitua parempi yhteistulos lämmitti mieltä.\n\n"}],"markDefs":[{"_type":"link","_key":"key-17-x4p9l","href":"/_emdash/api/media/file/01KZ3GMNFV49JKNNF93VSGB38Q.jpg"}]},{"_type":"image","_key":"key-19-imn5r","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMNFV49JKNNF93VSGB38Q.jpg","url":"/_emdash/api/media/file/01KZ3GMNFV49JKNNF93VSGB38Q.jpg"},"alt":"VJtuomari2"},{"_type":"block","_key":"key-30-ary4x","style":"normal","children":[{"_type":"span","_key":"key-20-byjwn","text":"\n"},{"_type":"span","_key":"key-21-pjux4","text":"Onnittelut kaikille osallistujille!\n\n"},{"_type":"span","_key":"key-22-qah2y","text":" \n\n"},{"_type":"span","_key":"key-23-pvfyc","text":"Tulokset: "},{"_type":"span","_key":"key-25-gmzgm","text":"Voimanosto2014_ joulukuu\n","marks":["key-24-jepu8"]},{"_type":"span","_key":"key-26-erbxg","text":"Videokoosteita kisasta","marks":["strong"]},{"_type":"span","_key":"key-27-ntrux","text":"http://www.youtube.com/watch?v=_aOUmHHet90&list=UUSQSxOPu0QxI8Dtb1L-Df2w\n"},{"_type":"span","_key":"key-28-924bl","text":"http://www.youtube.com/watch?v=c6H3qh0ecwk&list=UUSQSxOPu0QxI8Dtb1L-Df2w\n"},{"_type":"span","_key":"key-29-1suym","text":"http://www.youtube.com/watch?v=B2AlMxq-qg4&list=UUSQSxOPu0QxI8Dtb1L-Df2w"}],"markDefs":[{"_type":"link","_key":"key-24-jepu8","href":"/_emdash/api/media/file/01KZ3GMMDB18CE2686TZVCC8ZE.pdf"}]}]' WHERE id = '01KZ3GBYD09GRHT1CH8S7RDXHE';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-3x83l","style":"h1","children":[{"_type":"span","_key":"key-1-kn41h","text":"Kaksi Suomenmestaria tarvittiin Voima-Jyrin kaatamiseen"}]},{"_type":"block","_key":"key-4-tik0b","style":"h4","children":[{"_type":"span","_key":"key-3-8nqp9","text":"Juha Koivistolle ja Esa-Manniselle kirkkaimmat mitalit"}]},{"_type":"block","_key":"key-13-ttfdh","style":"normal","children":[{"_type":"span","_key":"key-5-lqw7l","text":"Vuoden 2015 ensimmäinen kilpailu käytiin hallintorakennuksen salilla.\n\n"},{"_type":"span","_key":"key-6-hueod","text":"Juha vei voiton vajaan 6 wilksin pisteen erolla. Toiseksi sijoittui Esa M:sta ja kolmas oli Ivan.\n\n"},{"_type":"span","_key":"key-7-qzjts","text":"Naisten sarjan voittaja oli Jenna W.\n\n"},{"_type":"span","_key":"key-8-0c849","text":"Onnittelut kaikille kisaajille hyvistä tuloksista!\n\n"},{"_type":"span","_key":"key-9-0iidj","text":"TULOKSET: "},{"_type":"span","_key":"key-11-is085","text":"HYV Max Voimapunnerrus 21 1 2015\n","marks":["key-10-3b5o0"]}],"markDefs":[{"_type":"link","_key":"key-10-3b5o0","href":"/_emdash/api/media/file/01KZ3GMRE2J6AD9BH8GP8HTGJY.pdf"},{"_type":"link","_key":"key-12-c1kgq","href":"/_emdash/api/media/file/01KZ3GMRR4ZS88JAYXCJZ6CTWF.jpg"}]},{"_type":"image","_key":"key-14-cgd76","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMRR4ZS88JAYXCJZ6CTWF.jpg","url":"/_emdash/api/media/file/01KZ3GMRR4ZS88JAYXCJZ6CTWF.jpg"},"alt":"Max Sotilaspenkki 21.1.2015"}]' WHERE id = '01KZ3GBZHGW3VZMZGNABKMTS1W';
