UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-10-295qd","style":"normal","children":[{"_type":"span","_key":"key-1-661ta","text":"Helsingin Yliopiston Voimailijoita edustettiin menestyksekkäästi lisäpainoleuanvedon Suomen Cup-kilpailussa Oulussa 28.3.2015. Kisapaikkana toimi toimintasali Voimala. Seuran jäsen, Jyrki Eriksson sijoittui alle 90kg-sarjassa toiseksi 74kg:n ennätystuloksella. Vuoden takainen vanha ennätys parani kerralla 4kg, jolla Jyrki nousi samalla sarjansa Suomen tilastossa seitsemänneksi. Tämä lupaa hyvää 23.05.tä Jyväskylässä pidettäviä SM-kisoja ajatellen.\n\n"},{"_type":"span","_key":"key-2-9x2fx","text":"Tulokset: "},{"_type":"span","_key":"key-4-dpj7j","text":"http://www.slry.fi/","marks":["key-3-lz473"]},{"_type":"span","_key":"key-5-9mgsw","text":"tulokset/?Kilpailupaiva=2015-","marks":["key-3-lz473"]},{"_type":"span","_key":"key-6-q153q","text":"03-28&Kilpailu=Suomen%20Cup&","marks":["key-3-lz473"]},{"_type":"span","_key":"key-7-6c24s","text":"Kilpailupaikka=Oulu&Paivays=","marks":["key-3-lz473"]},{"_type":"span","_key":"key-8-w51ti","text":"28.03.2015\n","marks":["key-3-lz473"]}],"markDefs":[{"_type":"link","_key":"key-3-lz473","href":"http://www.slry.fi/tulokset/?Kilpailupaiva=2015-03-28&Kilpailu=Suomen%20Cup&Kilpailupaikka=Oulu&Paivays=28.03.2015"},{"_type":"link","_key":"key-9-tgawf","href":"/_emdash/api/media/file/01KZ3GMYKH6WV69W6R94PQ1R68.jpg"}]},{"_type":"image","_key":"key-11-k9q09","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMYKH6WV69W6R94PQ1R68.jpg","url":"/_emdash/api/media/file/01KZ3GMYKH6WV69W6R94PQ1R68.jpg"},"alt":"jyrki_2_kuva_milla_vahtila"},{"_type":"image","_key":"key-14-jro2a","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMZ08WX00DQE3XGJ7J066.jpg","url":"/_emdash/api/media/file/01KZ3GMZ08WX00DQE3XGJ7J066.jpg"},"alt":"jyrki_4_kuva_milla_vahtila"},{"_type":"block","_key":"key-17-jfb97","style":"normal","children":[{"_type":"span","_key":"key-15-j383c","text":"\n"},{"_type":"span","_key":"key-16-uzgnd","text":"Kuvat Milla Vahtila"}]}]' WHERE id = '01KZ3GC446HC6HMV2CDCJHM9JV';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-2msyd","style":"normal","children":[{"_type":"span","_key":"key-1-3bkhb","text":"15.4.2015 käytiin tiukka toistopenkkipunnerruksen osakilpailu hallintorakennuksen salilla.\n\n"},{"_type":"span","_key":"key-2-k78rw","text":"Poiketen maksimikisoista, joissa tulosten laskenta tapahtuu Wilksin pisteillä. Toistokisassa eri painoiset nostajat ovat  hyvinkin erilaisessa asemassa ja kisaajienlaittaminen samalle ”viivalle\" on hyvin haastavaa."}]},{"_type":"block","_key":"key-5-nvks3","style":"normal","children":[{"_type":"span","_key":"key-4-qgqld","text":"Tästä syystä kisojen tuloslaskennassa päädyttiin laskea yhteen toistot * kilot. Kisapaino laskettiin omapaino pyöristettynä ylöspäin seuraavaan 2,5 kiloon."}]},{"_type":"block","_key":"key-12-e2h2e","style":"normal","children":[{"_type":"span","_key":"key-7-a849g","text":"HYV tulokset 4.2015 penkkipunnerrus\n","marks":["key-6-1wedz"]},{"_type":"span","_key":"key-8-7woej","text":"Voimaliigan tilanne ennen loppukilpailua:\n\n"},{"_type":"span","_key":"key-10-xq375","text":"HYV tulokset 4.2015\n","marks":["key-9-qx27e"]}],"markDefs":[{"_type":"link","_key":"key-6-1wedz","href":"/_emdash/api/media/file/01KZ3GMZFXM659VP7TF10B8C8T.pdf"},{"_type":"link","_key":"key-9-qx27e","href":"/_emdash/api/media/file/01KZ3GMZTF7WRH9XP5MCNCMNHH.pdf"},{"_type":"link","_key":"key-11-sh7gc","href":"/_emdash/api/media/file/01KZ3GN05BHAH6SZ7RGF34WTYN.jpg"}]},{"_type":"image","_key":"key-13-nbpgd","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN05BHAH6SZ7RGF34WTYN.jpg","url":"/_emdash/api/media/file/01KZ3GN05BHAH6SZ7RGF34WTYN.jpg"},"alt":"WP_002448 HYV kisat 4.2015"}]' WHERE id = '01KZ3GC53P5YGCET2YCTANG1B8';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-ngopm","style":"normal","children":[{"_type":"span","_key":"key-1-p5qj8","text":"Kauden päättäjäiskisana kisailtiin voimanostossa\n"},{"_type":"span","_key":"key-2-045de","text":"Kauden päättäjäiskisa oli huippu tiukka ja ennätyksiä rikottiin naisten- sekä miestensarjassa,\n"},{"_type":"span","_key":"key-3-uyg2x","text":"Voiton naistensarjassa vei tasaisesti kilpaillut Jenna, jonka wilksin pisteet olisivat riittäneet yleisensarjan neljänteen sijaan. Naistensarjan toiseksi sijoittunut Katariina P yritti viimeisellä yrityksellä maastavedossa hurjaa nostoa 172,5 kg, joka olisi riittänyt sarjan voittoon, mutta se jäi niukasti nostamatta tällä kertaan. Kolmanneksi sijoittui ensimmäistä kertaa kisaillut Terhi.\n"},{"_type":"span","_key":"key-4-j36po","text":"Miehissä oli vielä tasaisempaa. Ennen viimeistä kisasuoritusta ei voittajaa voitu julistaa. Axu yritti maagista 245 kg nostoa, mutta se jäi vielä tällä kertaan nostamatta ja sijoitus oli kolmas. Taktikoinnin mestari Tuomas sai ylös viimeisellään 230 kg, joka riitti kisan voittoon. Ivan jäi niukasti toiseksi 0,1 wilksin pisteen marginaalilla. Sami-Sali paransi omaa yhteistuloksen ennätystään melkein 40 kg ja rikkoi 500 kg rajan. Styrkka Leo loisti jälleen maastavedossa 200 kg tuloksella.\n"},{"_type":"span","_key":"key-5-48pq4","text":"Miestensarjassa oli uusia kisailijoita kolme Olof, Teemu ja Dima, jotka jokainen nostivat omaksi yhteistulokseksi yli 400 kg.\n"},{"_type":"span","_key":"key-6-ihky5","text":"Kiitoksia Sali-Sarille tuomarionnista ja onnittelut kaikille kilpailijoille hurjista tuloksista!\n\n"},{"_type":"span","_key":"key-7-u7546","text":" \n\n"},{"_type":"span","_key":"key-9-rencm","text":"Kisan tulokset\n","marks":["key-8-1u692"]}],"markDefs":[{"_type":"link","_key":"key-8-1u692","href":"/_emdash/api/media/file/01KZ3GN0JY0X3XJKZ1ES4REEP5.pdf"},{"_type":"link","_key":"key-10-iyxex","href":"/_emdash/api/media/file/01KZ3GN1QJAM5N8NEB5JKTQRF8.jpg"}]},{"_type":"image","_key":"key-12-t4o1x","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN1QJAM5N8NEB5JKTQRF8.jpg","url":"/_emdash/api/media/file/01KZ3GN1QJAM5N8NEB5JKTQRF8.jpg"},"alt":"Kevät2015_hyv"}]' WHERE id = '01KZ3GC68NPK21VVY5QRX3G3PA';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-mts4w","style":"h2","children":[{"_type":"span","_key":"key-1-adi6c","text":"Donkki-Ivan ja Marie voittoihin kauden avauskisassa"}]},{"_type":"block","_key":"key-5-7vau3","style":"normal","children":[{"_type":"span","_key":"key-3-mtd4s","text":"Ankarien sadekuurojen siivittämänä käyty Voimaliigan kauden 2015-2016 avauskilpailu käytiin Meilahden urheilupuistossa. Voimamieslajeina olivat kahvakuulapunnerrus, kuula, autonveto, farmarikävely ja lastaus.\n\n"},{"_type":"span","_key":"key-4-ndr1f","text":"Marie oli rohkeasti Voimailukilpailun historian ensimmäinen naisosanottaja. Ivan puolusti viime vuoden voittoaan ottamalla jo toisen peräkkäisen ykkössijan kilpailussa. Mainittakoon kuitenkin, että tänä vuonna salin vahvin mies herkisteli kisan kovan treeniohjelmansa lomassa. Käytämme hänestä tässä nimeä Laajasalon Lihaskimppu, sillä seuran sivuilla ei haluta liikaa korostaa hardcore-treenaajia."}]},{"_type":"block","_key":"key-7-kwr2d","style":"h3","children":[{"_type":"span","_key":"key-6-x8mfl","text":"Kisan kulku laji lajilta"}]},{"_type":"block","_key":"key-12-jahaj","style":"normal","children":[{"_type":"span","_key":"key-8-hk5bi","text":"Kahvakuulapunnerruksessa Ivan löi heti kisaennätyksen 30 toistollaan. Painonnostoharjoittelu näkyi selvästi sulavassa tekniikassa. Muut jäivät kauas tästä tuloksesta. Petri ja Tuomas saivat normaalitasoisensa suoritukset. Laajasalon mies teki vain nimellisen tuloksen, sillä Smolovin mesosykli oli hänellä kovimmillaan penkissä. Marien tulos oli luonnollisesti naisten kisaennätys.\n\n"},{"_type":"span","_key":"key-9-r4bpb","text":"Kahvakuula suoritettiin tällä kertaa sisätiloissa. Sen jälkeen siirryttiin ulos kuulan pariin. Sekä miesten että naisten kuula tehtiin 7.26 kg kuulalla. Heittotyyli oli vapaa. Pitkään kisaa johtanut Tuomas oli jo kiinni lajivoitossa, kunnes Ivan viimeisellä, taakse pään yli kahden käden heitollaan rikkoi ainoana 10 metrin rajan.\n\n"},{"_type":"span","_key":"key-10-u9bzu","text":"Autonvedossa välineenä oli viime vuotista raskaampi farmarimalli. Lisäksi Laajasalon voimamies vaati matkan pidentämistä noin 40 metriin eli lähes pesiskentän lyhyemmän sivun mittaiseksi. Tämä kannattikin, sillä Tuomas joutui nöyrtymään vedon kovimman startin ottaneelle voimailijalle. Lajivoitto meni kuitenkin Puntti-Petelle ja Donkki-Ivan vahvisti kakkossijalla kokonaiskilpailun asemaansa. Marien tulos oli kova ottaen huomioon selvästi miehiä pienemmän oman painon lajissa, jossa kilpailijan painosta on selkeää hyötyä.\n"}],"markDefs":[{"_type":"link","_key":"key-11-5hjrh","href":"/_emdash/api/media/file/01KZ3GN4SCMF8ZNFPWHYGWJBTF.jpg"}]},{"_type":"image","_key":"key-13-sj4k0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN4SCMF8ZNFPWHYGWJBTF.jpg","url":"/_emdash/api/media/file/01KZ3GN4SCMF8ZNFPWHYGWJBTF.jpg"},"alt":"autonveto"},{"_type":"block","_key":"key-18-eqp55","style":"normal","children":[{"_type":"span","_key":"key-14-f85co","text":"\n"},{"_type":"span","_key":"key-15-orow2","text":"Farmarikävelyssä standardoitiin matka mittaamalla tarkasti 25 m, käännös ja paluu, yhteensä siis 50 m. Reitin alkupuolisko oli alamäkeä ja loppu vastaavasti ylämäkeä. Ivan oli tässäkin lajissa konsultoinut alan asiantuntijana hierojaansa. Tämä näkyi erittäin tasapainoisena, pitkäaskelisena vetona, jossa ei ollut yhtään turhaa\n"},{"_type":"span","_key":"key-16-fzucc","text":"liikettä. Sijat 1-4 menivät lähes tasan neljän sekunnin välein. Naisilla painona oli yksi 25 kg kiekko per käsi. Tämä mahdollisti juoksemisen ja takasi kovan lajiennätyksen Marielle.\n\n"}],"markDefs":[{"_type":"link","_key":"key-17-07cse","href":"/_emdash/api/media/file/01KZ3GN56V5DW8KDTEHETFCM8Y.jpg"}]},{"_type":"image","_key":"key-19-cyah7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN56V5DW8KDTEHETFCM8Y.jpg","url":"/_emdash/api/media/file/01KZ3GN56V5DW8KDTEHETFCM8Y.jpg"},"alt":"autonveto2"},{"_type":"block","_key":"key-24-j4rg4","style":"normal","children":[{"_type":"span","_key":"key-20-v1szm","text":"\n"},{"_type":"span","_key":"key-21-ejjnc","text":"Lastaus oli hyvin aerobinen laji. Vaikka Puntti-Pete voitti lajin ja Donkki-Ivan jäi kolmanneksi, oli hän varmistanut kisan voiton jo neljän lajin jälkeen. Tämä tosin ei ollut tiedossa ennen lajin alkua ja kaikki ottivat lastauksen tosissaan. Laji suoritettiin täsmälleen samalla tavalla miesten ja naisten sarjoissa.\n\n"},{"_type":"span","_key":"key-22-95dxx","text":"Päivän suurimman pitkävetokertoimen olisi saanut veikkaamalla, että joku naisten sarjasta voittaa viimeisessä lajissa Laajasalon miehen. Marie teki tämän ihmeen. Laajasalon Lihaskimppu yllättäkin loppuhaastattelussa toteamalla, että kauden fokus on täysin uudessa lajissa, triathlonissa! \"Rikon 500 kg tuloksen ja vedän puoli- tai olympiamatkan triathlonin - siinä tavoitteeni kaudelle 2015-2016. Voimamieslajeista tai voimanostosta ei ole minulle enää riittävästi voitettavaa tai haastetta, siksi haluan rikkoa rajojani myös kestävyyslajeissa\", totesi Laajasalon ennätysmies.\n\n"},{"_type":"span","_key":"key-23-zyher","text":" "}]},{"_type":"block","_key":"key-26-31zq5","style":"h2","children":[{"_type":"span","_key":"key-25-egykv","text":"Tulokset","marks":["strong"]}]},{"_type":"block","_key":"key-28-h0qu4","style":"h2","children":[{"_type":"span","_key":"key-27-vkrgg","text":"Loppupisteet (5-4-3-2-1)"}]},{"_type":"block","_key":"key-35-0iwwm","style":"normal","children":[{"_type":"span","_key":"key-29-fedbt","text":"1. Ivan 22\n"},{"_type":"span","_key":"key-30-iqg96","text":"2. Petri 21\n"},{"_type":"span","_key":"key-31-ja763","text":"3. Tuomas 16\n"},{"_type":"span","_key":"key-32-mlply","text":"4. Jyri 11\n\n"},{"_type":"span","_key":"key-33-9ouwe","text":"1. Marie 25\n\n"}],"markDefs":[{"_type":"link","_key":"key-34-h0dz5","href":"/_emdash/api/media/file/01KZ3GN4APS3EZ2RENWVW14RAM.jpg"}]},{"_type":"image","_key":"key-36-gjft7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN4APS3EZ2RENWVW14RAM.jpg","url":"/_emdash/api/media/file/01KZ3GN4APS3EZ2RENWVW14RAM.jpg"},"alt":"IMG_1907"},{"_type":"block","_key":"key-39-hsqft","style":"h2","children":[{"_type":"span","_key":"key-38-e3c9i","text":"Lajitulokset"}]},{"_type":"block","_key":"key-72-rwbpe","style":"normal","children":[{"_type":"span","_key":"key-40-i0q1d","text":"Laji 1 Kahvakuulapunnerrus (24/12 kg)\n\n"},{"_type":"span","_key":"key-41-uajz1","text":"Ivan 30 CR\n"},{"_type":"span","_key":"key-42-29art","text":"Petri 20\n"},{"_type":"span","_key":"key-43-gdkzs","text":"Tuomas 14\n"},{"_type":"span","_key":"key-44-tfqky","text":"Jyri 5\n\n"},{"_type":"span","_key":"key-45-z5kuu","text":"Naiset\n"},{"_type":"span","_key":"key-46-kmnw7","text":"Marie 26 CR\n\n"},{"_type":"span","_key":"key-47-au33g","text":"Laji 2 Autonveto (Ford Monde, farmarimalli)\n\n"},{"_type":"span","_key":"key-48-lszf9","text":"Petri 37,4\n"},{"_type":"span","_key":"key-49-493hj","text":"Ivan 42,1\n"},{"_type":"span","_key":"key-50-fx3bf","text":"Jyri 56,5\n"},{"_type":"span","_key":"key-51-44i0c","text":"Tuomas 57,0\n\n"},{"_type":"span","_key":"key-52-bpq3d","text":"Marie 1.27,1\n\n"},{"_type":"span","_key":"key-53-mm700","text":"Laji 3 Kuulantyöntö/heitto (7.26kg)\n"},{"_type":"span","_key":"key-54-vfwr3","text":"Ivan 10.38 (8.85-8.96-10.38)\n"},{"_type":"span","_key":"key-55-jltn1","text":"Tuomas 9.40 (9.40-7.09-8.22)\n"},{"_type":"span","_key":"key-56-x3e0n","text":"Petri 8.29 (8.29-7.02-7.46)\n"},{"_type":"span","_key":"key-57-r64xo","text":"Jyri 6.68 (6.60 - x - 6.68)\n\n"},{"_type":"span","_key":"key-58-y3n0l","text":"Marie 4.73 (4.73-4.60-4.56)\n\n"},{"_type":"span","_key":"key-59-qvdny","text":"Laji 4 Farmarikävely (100/50 kg, 50 m)\n\n"},{"_type":"span","_key":"key-60-o57jl","text":"Ivan 16,4 CR\n"},{"_type":"span","_key":"key-61-ghk1l","text":"Petri 20,5\n"},{"_type":"span","_key":"key-62-hs0rl","text":"Tuomas 24,0\n"},{"_type":"span","_key":"key-63-4g94o","text":"Jyri 28,5\n\n"},{"_type":"span","_key":"key-64-16gim","text":"Marie 18,2 CR\n\n"},{"_type":"span","_key":"key-65-t9ro2","text":"Laji 5 Lastaus\n\n"},{"_type":"span","_key":"key-66-idupa","text":"Petri 1.40,5\n"},{"_type":"span","_key":"key-67-zxqg5","text":"Tuomas 1.42,6\n"},{"_type":"span","_key":"key-68-9un7f","text":"Ivan 1.49,7\n"},{"_type":"span","_key":"key-69-cwksn","text":"Jyri 2.50,0\n\n"},{"_type":"span","_key":"key-70-7tm4b","text":"Marie 2.18,0\n\n"},{"_type":"span","_key":"key-71-fjp1z","text":" "}]}]' WHERE id = '01KZ3GC7D8Z41FB9Q6RBK0JEFG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-8-4jfor","style":"normal","children":[{"_type":"span","_key":"key-1-5i09o","text":" \n\n"},{"_type":"span","_key":"key-2-3kdhc","text":"Kauden syksy 2014- kevät 2015 voimaliigan yhteispisteet. Tuloslistassa vain kolmeen kilpailuun osallistuneet henkilöt.\n\n"},{"_type":"span","_key":"key-3-lped6","text":"Voittajaksi miehissä nousi tasaisesti kilpailut Ivan toinen oli Aksu ja kolmanneksi jätettiin Puntti-Pete.\n\n"},{"_type":"span","_key":"key-4-xcylx","text":"Naisten sarjan voitti ylivoimaisesti Jenna.\n\n"},{"_type":"span","_key":"key-5-hxh7g","text":"Onnittelut voittajille ja kaikille kisoissa mukana olleille!\n\n"},{"_type":"span","_key":"key-6-9cmyc","text":" \n\n"}],"markDefs":[{"_type":"link","_key":"key-7-1t0f4","href":"/_emdash/api/media/file/01KZ3GN5HT1HAJ5FXYCQA35S7V.jpg"}]},{"_type":"image","_key":"key-9-kkbpr","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN5HT1HAJ5FXYCQA35S7V.jpg","url":"/_emdash/api/media/file/01KZ3GN5HT1HAJ5FXYCQA35S7V.jpg"},"alt":"HYV"},{"_type":"block","_key":"key-14-oqdf1","style":"normal","children":[{"_type":"span","_key":"key-10-5p9ft","text":"\n"},{"_type":"span","_key":"key-12-xy2nq","text":"Voimaliigan tulokset 2015\n","marks":["key-11-nryrg"]},{"_type":"span","_key":"key-13-lorqh","text":" "}],"markDefs":[{"_type":"link","_key":"key-11-nryrg","href":"/_emdash/api/media/file/01KZ3GN635SYPMYDE0QGXR86VT.pdf"}]}]' WHERE id = '01KZ3GC8DJ7S3DRV4G8V9DKWYS';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-5-h1ypq","style":"normal","children":[{"_type":"span","_key":"key-1-5hjk1","text":"Juha Koivisto nappasi ykkössijan 26 toistolla ja Esa Manninen kolmannen sijan uudella henkilökohtaisella ennätyksellään 46 toistoa Toistovoimapunnerruksen SM-kisoissa 3.10.2015 Lohjalla. HY-voimailijat onnittelevat!\n\n"},{"_type":"span","_key":"key-3-o5pbz","text":"Tulokset\n","marks":["key-2-8whkt"]}],"markDefs":[{"_type":"link","_key":"key-2-8whkt","href":"http://svry.fi/uploads/2015%20Tulokset/Tulokset%203.10.2015%20Toisto%20SM.pdf","blank":true},{"_type":"link","_key":"key-4-bvqy5","href":"/_emdash/api/media/file/01KZ3GN6E7CDY0M4NEB4W6CM8R.jpeg"}]},{"_type":"image","_key":"key-6-kzamb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN6E7CDY0M4NEB4W6CM8R.jpeg","url":"/_emdash/api/media/file/01KZ3GN6E7CDY0M4NEB4W6CM8R.jpeg"},"alt":"received_1694552150776111"}]' WHERE id = '01KZ3GC9HCM5BTDNG7GETKR4KE';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-27-ihmh9","style":"normal","children":[{"_type":"span","_key":"key-1-hqxn1","text":"HYV:n Juha Koivisto ja Esa "},{"_type":"span","_key":"key-2-z5svf","text":"Manninen"},{"_type":"span","_key":"key-3-yo7qe","text":"  jälleen menestyksekkäitä\n"},{"_type":"span","_key":"key-4-6ixme","text":"SVRY:n Voimapunnerruskisoihin Tampereella 19.9.2015.\n"},{"_type":"span","_key":"key-5-hcsef","text":"Molemmille kultaa maksimikisassa ja hopeaa toistokisassa.\n"},{"_type":"span","_key":"key-6-9ligx","text":"Esan tulos toistokisassa oli huikeat 45 toistoa 67.5 kg:llä\n\n"},{"_type":"span","_key":"key-7-xhjvf","text":"Tulokset MAX voimapunnerrus:\n"},{"_type":"span","_key":"key-8-57sls","text":"Esa "},{"_type":"span","_key":"key-9-z4s9y","text":"Manninen"},{"_type":"span","_key":"key-10-inzwi","text":" 127.5 kg\n"},{"_type":"span","_key":"key-11-klw6w","text":"Juha Koivisto 157.5 kg\n"},{"_type":"span","_key":"key-13-f3t53","text":"http://svry.fi/uploads/2015%","marks":["key-12-r2uee"]},{"_type":"span","_key":"key-14-m1qte","text":"20Tulokset/19.9.2015%","marks":["key-12-r2uee"]},{"_type":"span","_key":"key-15-z6itw","text":"20Maksimi%20Tampere%","marks":["key-12-r2uee"]},{"_type":"span","_key":"key-16-j8tk5","text":"20TULOKSET.pdf\n","marks":["key-12-r2uee"]},{"_type":"span","_key":"key-17-kpnu6","text":"Tulokset toistovoimapunnerrus:\n"},{"_type":"span","_key":"key-18-p9dji","text":"Esa "},{"_type":"span","_key":"key-19-gv5q6","text":"Manninen"},{"_type":"span","_key":"key-20-ippma","text":" 45 x 67.5 kg\n"},{"_type":"span","_key":"key-21-osu38","text":"Juha Koivisto 26 x 92.5 kg\n"},{"_type":"span","_key":"key-23-v3y68","text":"http://svry.fi/uploads/2015%","marks":["key-22-qo7g9"]},{"_type":"span","_key":"key-24-c31o6","text":"20Tulokset/19.9.%20toisto%","marks":["key-22-qo7g9"]},{"_type":"span","_key":"key-25-c7i65","text":"20tulokset%20tampere.pdf\n","marks":["key-22-qo7g9"]}],"markDefs":[{"_type":"link","_key":"key-12-r2uee","href":"http://svry.fi/uploads/2015%20Tulokset/19.9.2015%20Maksimi%20Tampere%20TULOKSET.pdf","blank":true},{"_type":"link","_key":"key-22-qo7g9","href":"http://svry.fi/uploads/2015%20Tulokset/19.9.%20toisto%20tulokset%20tampere.pdf","blank":true},{"_type":"link","_key":"key-26-c7zqg","href":"/_emdash/api/media/file/01KZ3GN71QVVNGDGNB9AVZQX1Z.jpg"}]},{"_type":"image","_key":"key-28-pymgp","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN71QVVNGDGNB9AVZQX1Z.jpg","url":"/_emdash/api/media/file/01KZ3GN71QVVNGDGNB9AVZQX1Z.jpg"},"alt":"HYV Koivisto Manninen Tre 19.9.2015"}]' WHERE id = '01KZ3GCAJ1S79ZKHF1P9PJD014';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-3-er2hy","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GN9CZ5M1GGMEEMEZYY416.jpg","url":"/_emdash/api/media/file/01KZ3GN9CZ5M1GGMEEMEZYY416.jpg"},"alt":"voimanosto_joulu2015"},{"_type":"block","_key":"key-13-4t4vk","style":"normal","children":[{"_type":"span","_key":"key-4-nxj67","text":"\n"},{"_type":"span","_key":"key-5-3qgwe","text":"Huikea voimanostoskaba käytiin remonttiin menevällä hallintorakennuksen kuntosalilla\n","marks":["strong"]},{"_type":"span","_key":"key-6-9vhji","text":"Naisten sarjassa Katariinat kävivät tasaisen kamppailun hallintorakennuksen kuntosalin voima-kuningattaren tittelistä. Voiton tällä kertaa vie Katariina P neljän wilksin pisteen erolla. Katariina P:n yhteistulos 297,5 kg (100/52,5/145). Voima-Katariinan osaksi jäi toinen sija yhteistuloksella 290 kg (90/75/125)\n\n"},{"_type":"span","_key":"key-7-g8x9z","text":"Miesten kilpailua hallitsi Tuomas P, joka ennakkoon uhosi rikkovansa 600 kg yhteistuloksen rajan. Tällä kertaa 600 kg oli liikaa. Tuomaksen nostama yhteistulostulos 590 kg (215/135/240) on uusi huikea saliennätys. Toiseksi sijoittui Axu yhteistuloksella 545 kg (170/135/240). Axu  ja Tuomas yrittivät maastanostosta saliennätystä, kumpikin suoritus oli vähällä onnistua. Kolmanneksi miehissä sijoittui Olaf, jonka 500 kg tavoite ei aivan rikkoutunut. Yhteistulos 472,5 kg (160/132,5/180) on kuitenkin hänen ennätys,\n\n"},{"_type":"span","_key":"key-8-kx7xe","text":"Kisassa debytoi kaksi uutta kisaajaa Jaakko O yhteistulos 477,5 kg (152,5/110/215) ja Anssi V yhteistulos 295 kg (145/0/150). Anssin kisa meni harmittavasti pilalle penkin nollatuloksella.\n\n"},{"_type":"span","_key":"key-9-1zhol","text":"Onnittelut kaikille osallistujille!\n\n"},{"_type":"span","_key":"key-10-hw8nr","text":"Tulokset: "},{"_type":"span","_key":"key-12-knvcj","text":"Joulukuun 2015 voimanoston tulokset","marks":["key-11-w7vmm"]}],"markDefs":[{"_type":"link","_key":"key-11-w7vmm","href":"/_emdash/api/media/file/01KZ3GN9Y7AT2YF5NP89TA6NMW.pdf"}]}]' WHERE id = '01KZ3GCFXK1QWJ9J3SM29FAWFZ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-nnkbq","style":"normal","children":[{"_type":"span","_key":"key-1-avvdg","text":"Helsingin Yliopiston Voimailijat Ry teki tänään historiaa, kun seuramme kilpaili ensimmäistä kertaa Unisportin Kauppakorkeakoulun salilla. Kisan tuomaroinista vastasi ammattitaitoinen kaksikko: Sari ja Marie. Vielä hetkeä ennen  ensimmäistä suoritusta Reijo antoi tarkat ohjeet kisaajille."}],"markDefs":[{"_type":"link","_key":"key-2-qnetn","href":"/_emdash/api/media/file/01KZ3GNATZ39S3TYKMSQZFP23S.jpg"}]},{"_type":"image","_key":"key-4-mncxd","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNATZ39S3TYKMSQZFP23S.jpg","url":"/_emdash/api/media/file/01KZ3GNATZ39S3TYKMSQZFP23S.jpg"},"alt":"WP_003141"},{"_type":"block","_key":"key-9-p7ymd","style":"normal","children":[{"_type":"span","_key":"key-5-1g3v5","text":"\n"},{"_type":"span","_key":"key-7-jhep7","text":"Sotilaspenkki maksi 1.2016\n","marks":["key-6-o01ss"]},{"_type":"span","_key":"key-8-1c1ue","text":"Kaikella tavalla tiukka ja kovatasoinen kisa käytiin tuttujen kilpakumppanien kesken. Lopulta kisan voitti ylivoimaisesti Esa M. kovalla 127,5 kilon tuloksella (Wilks 95,34). Heti takana tulivat seuraavat kisaajat: Tuomas P. 132,5 kiloa (Wilks 81,805), Petri 125 kiloa (Wilks 79,71), Mikko H. 130 kiloa (Wilks 74,55) ja Voima-Jyri 110 kiloa (Wilks 62,99)."}],"markDefs":[{"_type":"link","_key":"key-6-o01ss","href":"/_emdash/api/media/file/01KZ3GNBCP0XZXY7SM0QXSTN1Z.xls"}]}]' WHERE id = '01KZ3GCJHAMGQGV1D58NN3G8JQ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-paozx","style":"normal","children":[{"_type":"span","_key":"key-1-fcmsk","text":"Julma-Jyrkinä paremmin tunnettu Jyrki Eriksson kilpaili lisäpainoleuanvedon Suomen Cup-osakilpailussa Seinäjoella sarjassa alle 90 kiloa ja palasi Helsinkiin pronssinen mitali kaulassaan. Tulokseksi miehelle jäi oma henkilökohtainen ennätys 79 kiloa. Näin ollen parannusta tuli huimat viisi kiloa, joka näissä raudoissa vaatii jo systemaattista harjoittelua - varsinkin kun oma paino on lisääntynyt samalla toiset viisi kiloa!\n\n"}],"markDefs":[{"_type":"link","_key":"key-2-08g7b","href":"/_emdash/api/media/file/01KZ3GNC6W8ENRA2M0ED52ZC6N.png"}]},{"_type":"image","_key":"key-4-jl12e","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNC6W8ENRA2M0ED52ZC6N.png","url":"/_emdash/api/media/file/01KZ3GNC6W8ENRA2M0ED52ZC6N.png"},"alt":"Jyrki leuka"},{"_type":"block","_key":"key-26-aur51","style":"normal","children":[{"_type":"span","_key":"key-5-87g1w","text":"\n"},{"_type":"span","_key":"key-6-6gkdq","text":"Jyrkin treenejä vierestä seuranneena voin todeta, että erityisesti parannusta on tullut loppuvetoon. Tämä on nähtävissä myös kisanostosta, jossa on selvästi pari kiloa varaa (Alla video Julman IG-tililtä, jossa video on nähtävissä. Suosittelen myös seuraamaan jos Instagram tili löytyy!).\n\n"},{"_type":"span","_key":"key-7-pb6fs","text":"Turhaan mies ei siis ole viritellyt vastuskuminauhoja ja vaikeuttanut allekirjoittaneen kyykkäämistä ;) Mielelläänhän niitä vetoja katselee, joten suosittelen vierailemaan välillä Meilahdessa! (alla myös linkki Meilahteen)\n"},{"_type":"span","_key":"key-8-ixv15","text":"Julman suoritus:\n\n"},{"_type":"span","_key":"key-9-cp4ke","text":"https://www.instagram.com/p/BCAmnSdRPkk/\n\n"},{"_type":"span","_key":"key-10-roiil","text":" \n\n"},{"_type":"span","_key":"key-11-c484p","text":"Meilahden liikuntakeskus:\n\n"},{"_type":"span","_key":"key-13-9nbva","text":"Meilahden liikuntakeskus - Google Maps\n","marks":["key-12-5bg1q"]},{"_type":"span","_key":"key-14-o5ibd","text":"Vaikka sarjassa olikin vain neljä kilpailijaa, niin tuloksien perusteella kolmannesta sijasta sai ainakin kilpailun alkumetreillä jännittää. Kirkkaimmasta mitalista käytiin vielä kovempi taisto ja yhden kilon erolla voitto ratkesi Marko Mäkiselle tuloksella 93 kg, joka oli kisojen toiseksi raskain veto.\n\n"},{"_type":"span","_key":"key-15-d3by0","text":"Kisan kovimmasta tuloksesta vastasi Pakkotoistoltakin tuttu \"Kyrölääne\" eli Timo Lauttamus, joka on ihmetyttänyt kansainvälisestikin Youtube-videoillaan. Tulos 98 kg on uusi Suomen ennätys.\n\n"},{"_type":"span","_key":"key-16-qwe73","text":"Timo Lauttamuksen suoritus:\n\n"},{"_type":"span","_key":"key-17-mdu4k","text":"https://www.youtube.com/watch?v=dldlpSbw2vg\n\n"},{"_type":"span","_key":"key-18-k2324","text":"Toukokuussa on vielä yksi lisäpainoleuanveto (SM) ennen kesän avointa kilpailua, jonne ilmottautuneita on jopa Australiasta ja Yhdysvalloista asti. Näissä kisoissa nähtäneen myös HYV:n edustajia!\n\n"},{"_type":"span","_key":"key-19-62zu1","text":"Linkit:\n"},{"_type":"span","_key":"key-21-9s6bj","text":"Suomen Leuanveto ry","marks":["key-20-tso79"]},{"_type":"span","_key":"key-23-0kgsg","text":"Weighted Chin Up - Open\n","marks":["key-22-xzc8s"]},{"_type":"span","_key":"key-24-2dift","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-25-bd5of","text":"Kuva: Julma-Jyrki"}],"markDefs":[{"_type":"link","_key":"key-12-5bg1q","href":"https://www.google.fi/maps/place/Meilahden+Tennis+Oy/@60.1900806,24.8972334,15z/data=!4m2!3m1!1s0x0:0xa83bb16da8ecbc3","blank":true},{"_type":"link","_key":"key-20-tso79","href":"http://www.slry.fi/","blank":true},{"_type":"link","_key":"key-22-xzc8s","href":"http://www.weightedchinupopen.com/","blank":true}]}]' WHERE id = '01KZ3GCKPB6DWWWVF59TGHH84R';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-10-zocoe","style":"normal","children":[{"_type":"span","_key":"key-1-pd6lv","text":"Jaakko Onali sijoittui neljänneksi Imatralla kisatun sisäsoudun SM-kisojen 500 metrin matkalla. Huom! Vaikka tämän tekstin kirjoittajana toimii itse kisaaja, niin pyrin pitämään tarinan lyhyenä, sillä kuvat ja videot kiinnostavat lukijoita varmaankin enemmän ;)\n\n"},{"_type":"span","_key":"key-2-mytdv","text":"Huhut soutukisoista alkoivat pyörimään jo viime vuoden loppupuolella mutta lopullisesti tartuin haasteeseen vasta tammikuun puolivälissä, jolloin valmistautuminen maaliskuun kisoihin alkoi. Innokkaana salijantterina en voinut kuitenkaan kokonaan luopua rautarunnauksesta ja siksi viikottain tulikin noin 7-8 treeniä. Soutukilometrejä silti valitettavan vähän...\n"},{"_type":"span","_key":"key-3-8oxy8","text":"Kisapäivän koittaessa keuhkot kuitenkin tuntuivat olevan hyvässä kuosissa. Imatralle saavuttiin hyvissä ajoin, sillä halusin nähdä pari suoritusta myös muista sarjoista ja kuinka laite näyttää komennot: melko yksinkertaistahan se oli.. eli odottamiseksi meni vaikka mukavaa sitä kilpailua oli katsella.\n"},{"_type":"span","_key":"key-4-odddo","text":"Vaikka allekirjoittaneen paino onkin liikkunut 88 ja 90 kg välillä, niin taisin silti olla sarjani kevyin (kisasin avoimessa sarjassa - kevyt sarja alle 70 kg). Vasemmalla puolellani oli classic bodybuilding mies (ja leuanvetäjä ja voimanostaja) Tuomas Kuronen ja oikealla astetta jos kahta kovempi olympiakisoihin valmistautuva Joel Naukkarinen.\n"},{"_type":"span","_key":"key-5-cambd","text":"Itse suoritukseen: ensikertalaisen moka ja liian kovaa heti alkuun. Vauhti oli 1:13-1:15 / 500m alkupätkällä ja vielä puolivälin kohdilla taisin olla toinen. Kova alku kostautui ja kun matkaa oli 150 metriä jäljellä, niin alkoivat hapot pikkuhiljaa iskemään. Alla Finnrowingin video, jossa meikäläinen soutaa mustassa paidassa ja edessä siis Joel. Aivan kuten videosta näette niin temponi hidastuu huomattavasti Joelin painaessa loppuun asti lähes samalla tahdilla.\n\n"},{"_type":"span","_key":"key-7-c377k","text":"Finnrowing Facebook\n","marks":["key-6-prxyk"]},{"_type":"span","_key":"key-8-gx1tz","text":"Lopputuloksista päätellen kolmossijasta taisteltiin ankarasti kun kolme kisailijaa, minä keskimmäisenä, ylitti \"maaliviivan\" samalla sekunnilla.\n\n"}],"markDefs":[{"_type":"link","_key":"key-6-prxyk","href":"https://www.facebook.com/Finnrowing/videos/10153890457195568/","blank":true},{"_type":"link","_key":"key-9-wnbzj","href":"/_emdash/api/media/file/01KZ3GND74BQ4RY6KF7F9XJRH9.png"}]},{"_type":"image","_key":"key-11-jmdj2","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GND74BQ4RY6KF7F9XJRH9.png","url":"/_emdash/api/media/file/01KZ3GND74BQ4RY6KF7F9XJRH9.png"},"alt":"Kisatulos Jaakko"},{"_type":"block","_key":"key-19-v5o2e","style":"normal","children":[{"_type":"span","_key":"key-12-8bvm8","text":"\n"},{"_type":"span","_key":"key-13-i1xm4","text":" \n\n"},{"_type":"span","_key":"key-14-tuhtu","text":"Ensi vuonna uudestaan?\n\n"},{"_type":"span","_key":"key-15-qm2ig","text":"Urheilussa videot ovat paljon mielenkiintoisempia! Eli homma jatkuu kovasti kyykäten: alla olevia sarjoja (linkki) on tehty viimeisen viikon sisään reilu 20 kappaletta ja kuluvalla viikolla vielä enemmän. Ehkä sen avulla saadaan aika painumaan alle 1:20 ;)\n\n"},{"_type":"span","_key":"key-17-v59k3","text":"Kyykkäämistä 130 kg\n","marks":["key-16-9zyhr"]},{"_type":"span","_key":"key-18-rpdhp","text":"Teksti: Pro-Jaakko"}],"markDefs":[{"_type":"link","_key":"key-16-9zyhr","href":"https://www.dropbox.com/s/xbwjjg51hcxehgq/MOV_0078.mp4?dl=0","blank":true}]}]' WHERE id = '01KZ3GCNVYYRC2M9F992MQS4M9';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-gn2wl","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNE8YQFPGY9WH3R4T2T27.jpg","url":"/_emdash/api/media/file/01KZ3GNE8YQFPGY9WH3R4T2T27.jpg"},"alt":"penkki 2"},{"_type":"block","_key":"key-6-ixgbp","style":"normal","children":[{"_type":"span","_key":"key-2-qi9mt","text":"Huhtikuussa oli jälleen voimaliigan kisan vuoro sotilaspenkin muodossa. Vähäisestä osallistujamäärästä huolimatta kisasta saatiin tiukka kolmen lähes samanpainoisen kisaajan kesken: Tuomas, joka nosti 92,5 kg:lla sekä Julma-Jyrki ja Puntti-Pete, joille lastattiin tankoon tasan 90 kg.\n\n"},{"_type":"span","_key":"key-3-91fpf","text":"Itse en osannut aavistaa, kuka kisan voisi voittaa - ehkä pienimmät kertoimet olisivat olleet Tuomaksella sotilaspenkkimaksimin tuloksen perusteella. Ensimmäinen suoritus ja Tuomas tangon alle: 16 toistoa. Näin ollen Julman ja Puntti-Peten olisi saatava molemmat yksi toisto enemmän voittaakseen. Näin kävikin ja Puntti-Peten tulos 17 toistoa. Julmalle tämä kisa oli pikemminkin oheistreeni leuanvedon rinnalla mutta silti yli kymmenen toistoa, joista ensimmäinen harmittavasti vajaa.\n\n"},{"_type":"span","_key":"key-4-9v3yk","text":"Ja nyt katseet (ainakin useimmilla) kohti toukokuun voimanostokisaa, johon on vielä n. kuukausi aikaa valmistautua.\n\n"}],"markDefs":[{"_type":"link","_key":"key-5-bjfv8","href":"/_emdash/api/media/file/01KZ3GNFYGQ0228XM50AJKSY16.jpg"}]},{"_type":"image","_key":"key-7-4ho9d","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNFYGQ0228XM50AJKSY16.jpg","url":"/_emdash/api/media/file/01KZ3GNFYGQ0228XM50AJKSY16.jpg"},"alt":"Penkki"},{"_type":"block","_key":"key-10-esgzr","style":"normal","children":[{"_type":"span","_key":"key-8-iqofm","text":"\n"},{"_type":"span","_key":"key-9-3mclo","text":"-Pro-Jaakko"}]}]' WHERE id = '01KZ3GCPYPY47PCE7YPAWKB7VN';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-3-6a5rh","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNHBH70Z72JH3YDDSSVAX.jpg","url":"/_emdash/api/media/file/01KZ3GNHBH70Z72JH3YDDSSVAX.jpg"},"alt":"HYV"},{"_type":"block","_key":"key-17-c0nga","style":"normal","children":[{"_type":"span","_key":"key-4-dqlv8","text":"\n"},{"_type":"span","_key":"key-5-pnyay","text":"Otahallissa käytiin voimanoston ennätykselliset voimaliigan päätöskisat\n\n"},{"_type":"span","_key":"key-6-lp1s6","text":"Naisten sarjan ainoa osallistuja Katarina P sivusi omaa ennätystään varmoilla suorituksillaan. Tulos oli hänen kauden paras.\n\n"},{"_type":"span","_key":"key-7-rd80s","text":"Miesten sarjan voiton vei Tuomas P hurjalla HYV ry:n ja omalla ennätyksellään huimalla 620 kg yhteistuloksella. Toiseksi rutiinisuorituksellaan tuli painoa pudottanut Axu tuloksella 535 kg. Kolmas oli omalla hurjalla ennätyksellään Olaf tuloksella 515 kg. Olafin ennätys parani peräti 42,5 kg.\n\n"},{"_type":"span","_key":"key-9-n3o14","text":"Voimanosto kevät 2016 tulokset\n","marks":["key-8-nel3w"]},{"_type":"span","_key":"key-10-yryfm","text":"Kisat olivat voimaliigan kauden päätöskisat.\n\n"},{"_type":"span","_key":"key-11-m49e5","text":"Naisten sarjan vei Katarina P yhteispistein 24 ja toisen sijan jakoivat Marie ja Katarina N piseillä 21. Naisten sarjassa kellään kilpailijalla ei ollut kolmea osakilpailu osallistumista.\n\n"},{"_type":"span","_key":"key-12-oniqt","text":"Miesten kisan voiton ratkaisi viimeisen osakilpailun voitollaan Tuomas P yhteispisteet 51. Liigan toiseksi tuli vahvoilla suorituksillaan Puntti-Pete pistein 49 ja kolmanneksi sijoittui sisäsoudun erikoismies Jaakko O pistein 28.\n\n"},{"_type":"span","_key":"key-13-95bu0","text":"Voimaliigassa pisteitä sai peräti 13 mies-kisaajaa.\n\n"},{"_type":"span","_key":"key-15-l8n3g","text":"Voimaliiga 2015-2016\n","marks":["key-14-s9n1j"]},{"_type":"span","_key":"key-16-nkp5m","text":"Aurinkoista Kesää kaikille!"}],"markDefs":[{"_type":"link","_key":"key-8-nel3w","href":"/_emdash/api/media/file/01KZ3GNH1GMYE8DNN7FW8TGC2N.pdf"},{"_type":"link","_key":"key-14-s9n1j","href":"/_emdash/api/media/file/01KZ3GNGBVCR2335678RRGENWV.pdf"}]}]' WHERE id = '01KZ3GCR4XAYNDPR3F267524D4';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-6-a97h9","style":"normal","children":[{"_type":"span","_key":"key-1-yu261","text":"Oli taas mahtavat kisat Otahallissa.\n"},{"_type":"span","_key":"key-2-8cxtb","text":"Seuramme oma edustaja Katariina N sai ylös 35 kg raudat. Se riitti tällä kertaa 4. sijaan kovatasoisessa skabassa. Kiitoksia HYV ry.n porukalle ja muille järjestelyyn osallistuneille loistavista järjestelyistä! "},{"_type":"span","_key":"key-3-2h99s","text":":)\n","marks":["em"]},{"_type":"span","_key":"key-4-sb7s5","text":" \n\n"}],"markDefs":[{"_type":"link","_key":"key-5-8grx1","href":"/_emdash/api/media/file/01KZ3GNKWMMYAPY2TSP74TKYZW.jpg"}]},{"_type":"image","_key":"key-7-sh0i2","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNKWMMYAPY2TSP74TKYZW.jpg","url":"/_emdash/api/media/file/01KZ3GNKWMMYAPY2TSP74TKYZW.jpg"},"alt":"DSC_1572"},{"_type":"image","_key":"key-10-3uh6z","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNHQM7XRZSNB0NW8STM3N.jpg","url":"/_emdash/api/media/file/01KZ3GNHQM7XRZSNB0NW8STM3N.jpg"},"alt":"DSC_1564"},{"_type":"image","_key":"key-13-rdgmx","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNJGDTKERTAEWJQF7MS03.jpg","url":"/_emdash/api/media/file/01KZ3GNJGDTKERTAEWJQF7MS03.jpg"},"alt":"DSC_1565"},{"_type":"image","_key":"key-16-kkew1","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNK935GNGQDYZKYW8A7ZJ.jpg","url":"/_emdash/api/media/file/01KZ3GNK935GNGQDYZKYW8A7ZJ.jpg"},"alt":"DSC_1567"},{"_type":"image","_key":"key-19-bhana","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNMBNX74X2ET9JCE6Q3WJ.jpg","url":"/_emdash/api/media/file/01KZ3GNMBNX74X2ET9JCE6Q3WJ.jpg"},"alt":"DSC_1582"},{"_type":"image","_key":"key-22-dy9qj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNMZ5RGRZXKS7H8P43P8P.jpg","url":"/_emdash/api/media/file/01KZ3GNMZ5RGRZXKS7H8P43P8P.jpg"},"alt":"DSC_1583"},{"_type":"image","_key":"key-25-u27kx","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNNK8GJRH72G7YFCE7E6F.jpg","url":"/_emdash/api/media/file/01KZ3GNNK8GJRH72G7YFCE7E6F.jpg"},"alt":"DSC_1614"},{"_type":"image","_key":"key-28-zppy3","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNP90EC2MNWFA60C8PX73.jpg","url":"/_emdash/api/media/file/01KZ3GNP90EC2MNWFA60C8PX73.jpg"},"alt":"DSC_1615"},{"_type":"block","_key":"key-32-wqkli","style":"normal","children":[{"_type":"span","_key":"key-29-ae1xq","text":"\n"},{"_type":"span","_key":"key-31-ws998","text":"TULOKSET","marks":["key-30-zytzw"]}],"markDefs":[{"_type":"link","_key":"key-30-zytzw","href":"http://www.slry.fi/tulokset/?Kilpailupaiva=2016-06-11&Kilpailu=Weighted%20Chin-Up%20Open&Kilpailupaikka=Espoo&Paivays=11.06.2016"}]}]' WHERE id = '01KZ3GCS8ZT9X62MBA9V7RDZGG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-rr0dr","style":"normal","children":[{"_type":"span","_key":"key-1-4xhh8","text":"Kisaraportteja on tullut viime aikoina säännöllisen epäsäännöllisesti - ts. puutteellisesti. Tämän viikon aikana saatte lukea kevään leuanvetokisoista (alla) ja Tuomaksen voimanostokisoista Viron maalta (myöhemmin tällä viikolla).\n\n"},{"_type":"span","_key":"key-2-lgqs2","text":"Laukaa – lisäpainoleuanvedon SM\n","marks":["strong"]},{"_type":"span","_key":"key-3-hv4fm","text":"HYV edustus oli Laukaan kisoissa kahden vetäjän vahvuinen. Panokset näissä kisoissa oli astetta kovemmat, sillä "},{"_type":"span","_key":"key-4-aznke","text":"vähintään","marks":["strong"]},{"_type":"span","_key":"key-5-1zj1o","text":" top 5:een pääsy saattoi taata paikan kansainväliseen Chin Up Openiin Otaniemeen. Katarina onnistui tässä, vaikka naisten taso on viimeisen kahden vuoden aikana kehittynyt huimasti! Tekniikan muuttuminen ei välttämättä ollut paras mahdollinen idea lyhyellä aikataululla, sillä 41 kilon ennätysraudoista jäätiin melko kauas. Allekirjoittaneella saattoi olla osuutta asiaan… Tulos 35kg kuitenkin riitti kesäkuun kisoihin ja toiseen sijaan sarjassa alle 70 kg.\n\n"},{"_type":"span","_key":"key-6-4wyyn","text":"Naisilla oli Chin Up Openissa vain yksi sarja. Tämän vuoksi kaikki kolme sarjaa, yli ja alle 70 sekä alle 55, otetaan huomioon top 5:ssa. Tässä vertailussa Katarina oli neljäs.\n\n"},{"_type":"span","_key":"key-7-o0i6l","text":"Julma-Jyrki taas jäi kevyemmän painoisena Otaniemen kisojen ulkopuolelle. Paikkansa hän menetti soutukisoistakin tutulle Tuomas Kuroselle. Julma kertoi että päivä ei ollut paras mahdollinen ja siksi kisatulokseksi jäi aloituspaino 76 kg. Voinee kuitenkin sanoa että 70 kg on Julmalle casual paino – nousee siis ihan milloin vain, vaikka saman tien.\n\n"},{"_type":"span","_key":"key-8-cxh52","text":"Jälleen kerran voidaan mainita Timo Lauttamuksen suoritus: 100 kg yritys jäi melko kauas ilmeisesti pienen flunssan vuoksi. Toinen kova yritys oli Mario Jurosella 96 kilosta, joka ei todellakaan jäänyt kauaksi.\n\n"},{"_type":"span","_key":"key-9-0d8bu","text":"Alla hyvälaatuisia kuvakaappauksissa kisoista (selvyyden vuoksi vasemmalla Katarina ja oikealla Julma-Jyrki)\n\n"}],"markDefs":[{"_type":"link","_key":"key-10-9wcgm","href":"/_emdash/api/media/file/01KZ3GNQMQREJEBWAK7H3KZZXC.jpg"}]},{"_type":"image","_key":"key-12-c3pai","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNQMQREJEBWAK7H3KZZXC.jpg","url":"/_emdash/api/media/file/01KZ3GNQMQREJEBWAK7H3KZZXC.jpg"},"alt":"katarina leuka uusi"},{"_type":"image","_key":"key-15-cf3pi","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNR2CV6MXFAZX9WKFWKKP.jpg","url":"/_emdash/api/media/file/01KZ3GNR2CV6MXFAZX9WKFWKKP.jpg"},"alt":"Jyrki leuka uusi"},{"_type":"block","_key":"key-23-71u5q","style":"normal","children":[{"_type":"span","_key":"key-16-n89on","text":"\n"},{"_type":"span","_key":"key-17-8v1ya","text":" \n\n"},{"_type":"span","_key":"key-18-taba2","text":"Espoo - Weighted Chin-Up Open\n","marks":["strong"]},{"_type":"span","_key":"key-19-vtuof","text":"Tässä kisassa kirjoittajalla oli mahdollisuus seurata vain puolet kisoista: naisten sekä miesten alle 70 kg sarjat. Aivan kuten edellä mainitsin, oli Katarina mukana naisten kisassa mutta valitettavasti tulos jäi samaan kuin SM-kisoissa Laukaalla. Pieni videoanalyysi osoitti, että 38 kg yritys oli piirun verran parempi Otaniemessä. Kaikki naiskilpailijat olivat vetäneet yli 40 kg kisoissa, joten tiedettiin että kovaa taistelua kirkkaimmasta mitalista tultaisiin käymään. Näin olikin: Johanna Tupamäki ja Noora Kärkkäinen vetivät molemmat SE-raudan 43 kg, mutta Johanna 1,5 kg painavampana vei voiton.\n\n"},{"_type":"span","_key":"key-20-h9487","text":"Koska kyseessä oli avoin kilpailu, oli mukana myös ulkomaan edustusta: Viron maalta kaksi vetäjää, jotka tosin tuloksillaan eivät mahtaneet mitään Suomen kokeneille vetäjille. Ehkä he kuitenkin levittävät sanaa Baltiassa ja lisäpainoleuanveto pääsee leviämään noroviruksen lailla myös muualle Eurooppaan.\n\n"},{"_type":"span","_key":"key-21-2jwuh","text":"Miesten raskaammista sarjoista en pysty niinkään paljon kertomaan, mutta ainakin Mario Jurosen vetoa voidaan pitää yhtenä kovimpana (videota odotellessa!). Tulos 96 kg on uusi SE. Lauttamus kokeili jälleen 100 kiloa, mutta valitettavasti saamme vielä odotella tuon maagisen rajan rikkomista…\n\n"},{"_type":"span","_key":"key-22-2giyy","text":"Kaiken kaikkiaan kisoissa nähtiin 4 SE:tä"}]},{"_type":"block","_key":"key-25-i2dnt","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-24-vamvf","text":"Harri Kangas (alle 70 kg) 86,6 kg"}]},{"_type":"block","_key":"key-27-mncky","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-26-nxref","text":"Arto Immonen (M50) 70 kg"}]},{"_type":"block","_key":"key-29-xi4mr","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-28-srg9n","text":"Mario Juronen (alle 90 kg) 96 kg"}]},{"_type":"block","_key":"key-31-y64gs","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-30-nqgda","text":"Johanna Tupamäki (naiset alle 70 kg) 43 kg"}]},{"_type":"image","_key":"key-34-fbccl","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNJGDTKERTAEWJQF7MS03.jpg","url":"/_emdash/api/media/file/01KZ3GNJGDTKERTAEWJQF7MS03.jpg"},"alt":"DSC_1565"},{"_type":"block","_key":"key-37-blenv","style":"normal","children":[{"_type":"span","_key":"key-35-iunhu","text":"\n"},{"_type":"span","_key":"key-36-ltn4i","text":"Pro-Jaakko"}]}]' WHERE id = '01KZ3GCTBXW33FEZ8RYB4F70YG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-15-b829h","style":"normal","children":[{"_type":"span","_key":"key-1-611gj","text":"Ja tällä kertaa kirjoittaja pääsee hieman helpommalla. Kisaraportti suoraan kilpailijalta itseltään, joten vältetään ne kalajutut...\n\n"},{"_type":"span","_key":"key-2-69o04","text":"Kyseessä siis pääkaupunkiottelu, jossa Tuomas edustamassa Helsinkiä:\n\n"},{"_type":"span","_key":"key-3-fv7og","text":"\""},{"_type":"span","_key":"key-4-zvcej","text":"Kisareissu Tallinnaan alkoi jo edellisenä iltana, kun joukkue nousi Viking Linen laivaan. Laiva oli perillä jo puolelta öin mutta meillä oli joukkueen kanssa hytit, jossa nukuimme aamu kuuteen, jolloin oli jo aika nousta aamiaiselle. Laivasta oli poistuttava jo seitsemältä ja joukkue vietti pari tuntia satamassa ennen kuin kisajärjestäjät tulivat meitä bemareilla hakemaan. \n","marks":["em"]},{"_type":"span","_key":"key-5-34pz6","text":"Kisapaikalla olimme juuri sopivasti kaksi tuntia ennen punnitusta varten. Itse olin jo kerennyt tankata nestettä niin paljon, että painoin reilu 95 kiloa. Tämän jälkeen selvisi, että nostan ensimmäisessä ryhmässä. Kisa alkoi 11.30 ja alkulämmöt olivat menneet hyvin. Ensimmäisellä helppo 215, joka kuitenki tuntui vähän huonolta, kuten aloitukset yleensä. Toiseen 225 ja se tuntui jo paremmalta. Kolmanteen laitettiin enkkaraudat 232,5 ja se nousikin mutta jäin puolessavälissä vähän ihemettelemään ja tanko meni hiukan alaspäin, mikä aiheutti kyykyn hylkäyksen. Syvyys oli kunnossa, vaikka sitä alkusi itse epäilinkin. \n","marks":["em"]},{"_type":"span","_key":"key-6-uybl0","text":"Penkissä lähdettiin rohkeasti hakemaan ennätyksiä, koska olin edellisen viikon tistaina salilla jo niitä nostellut. Ensimmäiseen 137,5, mikä oli varma suoritus. Toiseen 142,5 mikä tyssäsi puoliväliin eikä myöskään tullut kolmannella, vaikka sain joukkuekaverilta lainaan rannesiteet, joissa on ehjät tarrat. \n","marks":["em"]},{"_type":"span","_key":"key-7-ehgrc","text":"Vedossa meni ensimmäinen nosto ihmettelyksi, kun oli lämmitelty aivan eri tangolla ja ensimmäistä kertaa Eleikon ohuet 25kg levyt käytössä, missä on eroa paksuihin kumilevyihin. Toisella aloitus uusiksi ja helppo nosto antoi itseluottamusta laittaa ennätysraudat viimeiseen. Viimeinen nosto, tangossa 255, ja viimeinen mahdollisuus saada ennätysnosto. Nosto oli erittäin tiukka rutistus, joka meni niukasti 2-1 läpi ja kisat olivat minun osalta ohi. \n","marks":["em"]},{"_type":"span","_key":"key-8-huqnd","text":"Pääkaupunkiottelun voitti Tukholma, joka oli ainoa täydellä joukkueella mukana ollut kaupunki. Helsingin joukkue sijoittui toiseksi ja ilman naiskilpailijoita kisannut Tallinna sijoittautui kolmanneksi. Kisoissa oli mukava tunnelma ja erityisesti Tukholman joukkueen naisnostajat ja joukkuekaverit olivat mukavia. Omalta osalta jäi vähän hampaankoloon ja parannettavaa Minskiin yliopisto MM-kisoihin.","marks":["em"]},{"_type":"span","_key":"key-9-jzgdh","text":"\"\n","marks":["em"]},{"_type":"span","_key":"key-10-q5txj","text":"-Tuomas\n\n"},{"_type":"span","_key":"key-11-drkj1","text":"Tuomaksen nostot ja tulokset alla. Videosta näkee hyvin tuon rannesiteiden irtoamisen sekä kyykyssä että penkissä..\n\n"},{"_type":"span","_key":"key-12-fgois","text":"(älkää antako pienen roskan linssissä haitata)\n\n"},{"_type":"span","_key":"key-13-vi13r","text":"https://www.youtube.com/watch?v=VnJ76hqP0Yo\n\n"}],"markDefs":[{"_type":"link","_key":"key-14-ryxq0","href":"/_emdash/api/media/file/01KZ3GNRG2CPR13H6KQS53NVJM.jpg"}]},{"_type":"image","_key":"key-16-v95yj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNRG2CPR13H6KQS53NVJM.jpg","url":"/_emdash/api/media/file/01KZ3GNRG2CPR13H6KQS53NVJM.jpg"},"alt":"Tuomas Viro"},{"_type":"block","_key":"key-19-ezfdm","style":"normal","children":[{"_type":"span","_key":"key-17-bocpd","text":"\n"},{"_type":"span","_key":"key-18-lntkc","text":"-Pro-Jaakko"}]}]' WHERE id = '01KZ3GCVBD1PS9Z0Q2628CPH4R';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-16-m20zq","style":"normal","children":[{"_type":"span","_key":"key-1-fgm4b","text":"Jälleen Admin pääsee helpolla kun kisaraportti tulee itse kisaajalta:\n\n"},{"_type":"span","_key":"key-2-d8gxb","text":"\"Kisaan valmistautuminen alkoi poikkeuksellisesti vasta kuukautta aiemmin. Syynä olivat edelliset kisat Tallinnassa, joiden jälkeen oli myös pakko levätä. Kisavalmistautuminen tapahtui pääosin Unisportin saleissa ja varsinkin Otahallista löytyy hyvä varustelu voimanostajan tarpeisiin\" (tätä myös admin suosittelee!).\n\n"},{"_type":"span","_key":"key-3-f8jd0","text":"\"Minskin kisat olivat ensimmäiset yliopisto-opiskelijoiden MM-kisat, mutta myös allekirjoittaneen ensimmäiset arvokisat. Kisamatka vaatikin ensimmäistä kertaa lentojen ja hotellin varaamista, viisumin hankkimista ja sponsorituen hakemista. Loppujen lopuksi kaikki meni erittäin hyvin ja kisamatka saati järjestettyä.\n\n"},{"_type":"span","_key":"key-4-8zprr","text":"Saavuin Minskiin edellisenä päivänä ja ensimmäisenä tuli hoitaa akkredointi kisahotellissa. Samalla kävin kisavaa''alla tarkistamassa oliko paino kuinka paljon yli sallitun 93 kilon. Paino olikin vain vajaa sata grammaa yli, joten pystyin lähtemään kaupungille syömään ennen nukkumaanmenoa. Kisa-aamuna painoin jo herättyäni alle 93 kiloa ja kisavaaka näytti kahta tuntia ennen kisaa 92,29 ja näin olinkin varustetarkastuksen jälkeen valmis aloittamaan lämmittelyt kyykkyä varten.\n\n"},{"_type":"span","_key":"key-5-sxg2w","text":"Lämmittelyt sujuivat hyvin ja aloitin suunnitellusta aloituspainoista 220 kilosta, jonka kyykkäsin varmuuden vuoksi tosi syvään ja näin sain 3-0 hyväksytyn aloituksen. Toiseen lastattiin kisaennätys 227,5 kg, joka oli jo aika raskas, mutta liikui hyvin ja hyväksyttiin myös äänin 3-0. Kolmanteen laitettiin 232,5, joka oli mennyt hylsyyn Tallinnassa. Se oli myös Minskissä liikaa. Varmistajat olivat hyvin mukana ja pääsin jatkamaan ehjänä penkkipunnerrukseen ollessani nyt kisassa neljäntenä.\n\n"},{"_type":"span","_key":"key-6-vkh5g","text":"Penkissä oli sama aloitusrauta kuin edellisessä kisassa (137,5 kg) ja se tuntuikin uskomattoman kevyeltä, joten toiseen lastattiin kisaennätys 142,5 kiloa, mutta keskittymiseni herpaantui kun aloin kuuntelemaan kuuluttuja puheita ja näin nosto epäonnistui. Kolmannella yritin samaa rautaa, mutta paukut olivat jo loppuneet. Maksoin penkissä viisi kiloa oppirahoja ja harmitti kovasti jäädä aloitukseen kun treeneissä oli nostettu ennätyksiä juuri ennen kisaa.\n\n"},{"_type":"span","_key":"key-7-yju5f","text":"Vedossa laskin suunniteltua aloitusta kymmenellä kilolla 235:een. Syynä tähän oli taktikointi jenkkinostajaa vastaan, joka yritti tulla takaa ohi. Aloituksen nappasin varmasti ylös. Toisella nosin suunnitellun aloituksen 245 kg ja jenkki vastasi 260 kilon vedolla ja samalla hän meni ohitseni viidenneksi. Katsoimme joukkueenjohtajan kanssa hänen toisen nostonsa ja päätimme, että otan kolmannella varman 252,5 ja pakotetaan hänet taistelemaan vitossijasta. Lopulta molempien kolmannet yritykset ja jenkki voitti minulta viidennen sijan ollessaan kevyempi nostaja. Yhteistuloksessa sivusin kisaennätystäni, joten penkkiä lukuunottamatta voin olla erittäin tyytyväinen suoritukseeni ensimmäisissä arvokisoissani.\n\n"},{"_type":"span","_key":"key-8-tkzuv","text":"Seuraavat kisat lienevät opiskelijoiden SM-kisoissa syyskuussa ja toivottavasti näen siellä mahdollisimman paljon tuttuja Minskin matkalta!\"\n\n"},{"_type":"span","_key":"key-9-31xnm","text":"-Tuomas\n\n"},{"_type":"span","_key":"key-10-hlzyf","text":"Ja koska videot.....\n\n"},{"_type":"span","_key":"key-11-pji39","text":"Täytyy minunkin sanoa, että streami oli huippuluokkaa myös puhelimella katsottuna ja näin maallakin aika kului kuin siivillä.\n\n"},{"_type":"span","_key":"key-12-swbos","text":"Video:\n\n"},{"_type":"span","_key":"key-13-0c6r9","text":"https://www.youtube.com/watch?v=GM1iTL1GdMA\n\n"},{"_type":"span","_key":"key-14-nb3zo","text":"-Pro-Jaakko\n\n"}],"markDefs":[{"_type":"link","_key":"key-15-3mksh","href":"/_emdash/api/media/file/01KZ3GNRX6P19V6N2BQXMMQACA.jpg"}]},{"_type":"image","_key":"key-17-5a3v7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNRX6P19V6N2BQXMMQACA.jpg","url":"/_emdash/api/media/file/01KZ3GNRX6P19V6N2BQXMMQACA.jpg"},"alt":"TUOMAS Minsk"}]' WHERE id = '01KZ3GCWA5NYRA299DCAYDHQ5T';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-8-9kmw0","style":"normal","children":[{"_type":"span","_key":"key-1-qxauq","text":"Ja jälleen on kausi saatu startattua. Kyseessä oli siis vanha tuttu voimailukilpailu Meilahden kentällä. Osanottajia oli tällä kertaa vain kolme kappaletta, mutta silti kisasta tuli mielenkiintoisen tiukka ja lopussa kenties myös hiukan yllättävä. Tällä viikolla seuraamme liittyi uusi jäsen (Pekka), joka osoitti selvästikin kilpailuhenkeä ja osissa lajeissa iski luun kurkkuun vanhoille HYV:n konkareille. Mies puhui, että on vasta aloitellut voimailun (liekö totta ;) ).\n\n"},{"_type":"span","_key":"key-2-01nbb","text":"Jokaisessa lajissa kisailtiin tiukasti sijoituksista: Esim. kuulassa Pekan ja Voima-Jyrin ero oli vain parikymmentä senttiä - Sampsa tässä omaa luokkaansa. Saappaanheitossa taas Voima rykäisi ensimmäisellään yli 23-metrisen, joka oli samalla voittotulos. Sampsa ei jäänyt tästä kauaksi: vain reilu kymmenen senttiä! Mittausvirhe kahden senttimetrin luokkaa... Saappaanheitto muistutti osittain Suomen keihäsmiesten mittelöä (hyvässä mielessä).\n\n"},{"_type":"span","_key":"key-3-wlu51","text":"Farmarikävely vaikutti olevan pikemminkin kivunsieto+pikajuoksukilpailu kuin tyypillinen voimailulaji. 50 kg (2x25 kg kiekko) per käsi ja Sampsan 200 metrin juoksijan rakenne olivat tässä suotuisat ja voitto irtosi näytöstyyliin. Pekka ja Voima kisailivat tiukasti toisesta sijasta: tässä Pekka parempi pidettyään loppusuoran nopeuden vähintään alun tasolla. Voimalla pieni hyytyminen maksoi pari sekuntia liikaa..\n\n"},{"_type":"span","_key":"key-4-g7h80","text":"Kahvakuulapunnerruksessa (20 kg per käsi) vastaavanlainen tilanne kuin lastauksessa. Voima ja Pekka taistelivat toisesta sijasta ja Sampsa meni menojaan. Tässä tekniikkaharjoittelu olisi ehkä ollut paikallaan. Aikaa oli nimittäin 3 minuuttia, mutta kahvakuulia ei saanut laskea riipuntaan. Kaikilla kuitenkin suoritus kesti maksimissaan 70 sekuntia. Myönnettäköön että kuulien lepuuttaminen olkapäillä ei ole helppoa.\n\n"},{"_type":"span","_key":"key-5-jgtpa","text":"Viimeinen ja Voima-Jyrin puheiden mukaan kovin laji oli lastaus. Pitkäkestoisin suoritus, jossa 25 kg:n kiekkoja lastataan neljä kappaletta. Pistetilanne tässä vaiheessa oli se, että sijoitukset eivät tulisi muuttumaan. Tämä ei kuitenkaan muuta tosivoimailijoiden asennetta (nyrkki!). Johtoasemassa Sampsa lähti ensin liikenteeseen ja aika oli kova: 1:27,6. Suorituksen jälkeen mies mainitsi että hiukan säästeli alkuvaiheessa, joka saattoi maksaa muutaman sekunnin. Seuraavana Voima-Jyri, joka veti koko suorituksen tasaisen tappavalla nopeudella. Aikaa meni reilu kaksi minuuttia. Viimeisenä vuorossa Pekka. Lähtö oli erittäin nopea ja ensimmäinen kierros alle kaksikymmentä sekuntia, joka tarkoittaisi Sampsan ajan päihittämistä jos vain nopeus pysyisi samana. Toinen kierros vielä n. kahdenkymmenen sekunnin aikaan. Kolmas osoitti hiukan hyytymistä, mutta ei pahasti ja jännitys tiivistyi entisestään. Viimeinen kiekko ja maaliin ajassa 1:24,9 ja lajivoitto! Näki kyllä miehestäkin että kaikkensa antoi..\n\n"},{"_type":"span","_key":"key-6-9tox1","text":"Kuten neljän pikselin pistetaulukosta näette, niin Pekka ja Jyri kävivät tiukan taiston toisesta sijasta. Ja jos lajien tuloksia katsotaan, niin mitä tahansa olisi voinut tapahtua.\n\n"}],"markDefs":[{"_type":"link","_key":"key-7-sz275","href":"/_emdash/api/media/file/01KZ3GNWG0P0RJRDR2S3KNGZJY.jpg"}]},{"_type":"image","_key":"key-9-tsqvk","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNWG0P0RJRDR2S3KNGZJY.jpg","url":"/_emdash/api/media/file/01KZ3GNWG0P0RJRDR2S3KNGZJY.jpg"},"alt":"Voimailu meilahti tulokset"},{"_type":"image","_key":"key-12-93c3p","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNVMV6FP9Y22KFYNVX80H.jpg","url":"/_emdash/api/media/file/01KZ3GNVMV6FP9Y22KFYNVX80H.jpg"},"alt":"Ryhmä voimailu meilhati"},{"_type":"image","_key":"key-15-wc22h","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNV197B67K7ECSHJCPTQF.jpg","url":"/_emdash/api/media/file/01KZ3GNV197B67K7ECSHJCPTQF.jpg"},"alt":"Pekka"},{"_type":"image","_key":"key-18-xitav","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNW3AR1VZSXFWFB2E3AX9.jpg","url":"/_emdash/api/media/file/01KZ3GNW3AR1VZSXFWFB2E3AX9.jpg"},"alt":"Sampsa meilahti"},{"_type":"image","_key":"key-21-i9016","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNTHTHT04VS523X13DE1M.jpg","url":"/_emdash/api/media/file/01KZ3GNTHTHT04VS523X13DE1M.jpg"},"alt":"Jyri"},{"_type":"block","_key":"key-25-7en9c","style":"normal","children":[{"_type":"span","_key":"key-22-0yqpd","text":"\n"},{"_type":"span","_key":"key-23-qb8iy","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-24-p4dc7","text":"Kuvat: Voima-Jyri"}]}]' WHERE id = '01KZ3GCY9AHJ9V7AFW6252BCE3';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-4-vtc1r","style":"normal","children":[{"_type":"span","_key":"key-1-d2ttb","text":"HYV:n Voimaliiga jatkui Meilahdessa lauantaina 22.10.. Ohjelmassa oli 1 000 metrin sisäsoutu. Hyviä tuloksia nähtiin. Naisissa Katarina pusersi kovan tuloksen: 03:38,8. Miesten sarjassa Jyri oli asettanut tavoitteeksi0 4:30 alituksen. Lopulta tavoite alittui hienosti ajalla 04:20,6, Jyrin sijoittuessa kolmanneksi. Voitosta käytiin tiukka sadasosien kamppailu, joka lopulta päättyi Timon voittoon ajalla 3:04,4. Jaakko sijoittui toiseksi ajalla 3:05,0. Jaakolta nähtiin huima loppukiri, sillä viimeiset 300 metriä menivät reippaasti alle 1:30/500 m keskiajalla. Asiantuntijan arvion mukaan, mikäli Jaakko olisi aloittanut kovempaa alussa, olisi todennäköisesti nähty kolmen minuutin alitus.\n\n"},{"_type":"span","_key":"key-2-2pgw8","text":"Seuraavaksi kisaillaan voimanoston merkeissä joulukuun 17. päivänä Otahallilla."}],"markDefs":[{"_type":"link","_key":"key-3-7zs39","href":"/_emdash/api/media/file/01KZ3GNX2XPK3PH9TG3HBB05XT.jpg"}]},{"_type":"image","_key":"key-5-lps2x","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNX2XPK3PH9TG3HBB05XT.jpg","url":"/_emdash/api/media/file/01KZ3GNX2XPK3PH9TG3HBB05XT.jpg"},"alt":"dsc_0029-hyv-kisa-22-10-2016-yhteiskuva"},{"_type":"image","_key":"key-8-6n328","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GNZAWZS7BVAW72V328FMX.jpg","url":"/_emdash/api/media/file/01KZ3GNZAWZS7BVAW72V328FMX.jpg"},"alt":"dsc_0025-hyv-kisa-22-10-2016-timo"},{"_type":"image","_key":"key-11-v55op","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP11WAF4R52AS16NT0VRV.jpg","url":"/_emdash/api/media/file/01KZ3GP11WAF4R52AS16NT0VRV.jpg"},"alt":"wp_003523-hyv-kisa-22-10-2016-jaakko"},{"_type":"image","_key":"key-14-6sdr6","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP1C1AMQTT3D1AQBD6W88.jpg","url":"/_emdash/api/media/file/01KZ3GP1C1AMQTT3D1AQBD6W88.jpg"},"alt":"wp_003513-hyv-kisa-22-10-2016-katarina"},{"_type":"image","_key":"key-17-405lx","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP26DW9Y1G7WF5H49F1DX.jpg","url":"/_emdash/api/media/file/01KZ3GP26DW9Y1G7WF5H49F1DX.jpg"},"alt":"wp_003504-hyv-kisa-22-10-2016-jyri"},{"_type":"block","_key":"key-28-b8u2c","style":"normal","children":[{"_type":"span","_key":"key-18-hnwdp","text":"\n"},{"_type":"span","_key":"key-19-bh3hs","text":"Voimaliigan tilanne kahden osakilpailun jälkeen.\n\n"},{"_type":"span","_key":"key-20-tbsna","text":" \n\n"},{"_type":"span","_key":"key-21-9ilbm","text":"Jyri                      17\n\n"},{"_type":"span","_key":"key-22-6ijjx","text":"Sampsa             12\n\n"},{"_type":"span","_key":"key-23-431wi","text":"Timo                   12\n\n"},{"_type":"span","_key":"key-24-fbqpl","text":"Jaakko               9\n\n"},{"_type":"span","_key":"key-25-hbtqo","text":"Pekka                 8\n\n"},{"_type":"span","_key":"key-26-d0laf","text":" \n\n"},{"_type":"span","_key":"key-27-0xxnk","text":"Katarina            12"}]}]' WHERE id = '01KZ3GCZEX6DFV04P1CWJZHT65';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-ar6y2","style":"normal","children":[{"_type":"span","_key":"key-1-9myzb","text":"Voimaliiga jatkui (an)aerobisen soutukisan jälkeen perinteisellä voimanostokisalla Otahallilla. Tällä kertaa osanottajia oli kertynyt hyvä määrä ja tasoa oli ennakoitu kovaksi, vaikka pari konkaria jättikin osallistumatta. Syitä poissaoloihin spekuloitaneen vielä tovin aikaa... "},{"_type":"span","_key":"key-2-jgh57","text":"Tästä huolimatta juurikin kilpakumppaneiden taso oli tarpeeksi kova motivoimaan nostajia!\n"},{"_type":"span","_key":"key-3-oamzk","text":"Debyyttikisaajia voimanostossa olivat uudet jäsenet Tuukka ja Ville H. (joka nosti 100 % RAW - no sleeves, no belt) sekä syksyn voimamieskisassa kilpailuhenkisyytensä osoittanut Pekka. Meikäläisellä oli ainakin jonkinlainen mutu näiden miesten nostoista, mutta ei siltikään voinut aavistaa lopputulosta vanhojen jäsenten pitäessä treenit salassa. Tuttuja kisaajia olivat minä, Strykka-Leo, Olaf, Ivan, Tuomas ja Axu. Top 2:een oli veikkailtu Ivania ja Tuomasta, mutta järjestys oli mysteeri.\n\n"},{"_type":"span","_key":"key-4-inao8","text":"Jalkakyykky\n","marks":["strong"]},{"_type":"span","_key":"key-5-bsgey","text":"Kyykkyyn lähtiessä mustalaisleiri oli ehtinyt vallata puolet yläkerran tiloista ja fillis vain parani - ainakin osanottajien osalta. Lajissa nähtiin perusvahvoja suorituksia. Perusvahvalla tässä tarkoitetaan vahvoja, sillä taso oli HYV:n historiassa ennätyskova.\n\n"},{"_type":"span","_key":"key-6-vwg5g","text":"Koska tuomarilinja oli ennakoidusti tiukka, oli kyykyn syvyydessä oli parin nostajan kanssa ongelmia. Tuomaksella aloitus 200 kg oli sarjapainotasolla, ja sen kyllä huomasi. Hän vei kyykyn ennakoidusti tuloksella 225 kg. Ivan jatkoi toisena penkkipunnerrukseen tuloksella 200 kg"},{"_type":"span","_key":"key-7-nbv7g","text":". ","marks":["strong"]},{"_type":"span","_key":"key-8-cgstm","text":"Kyykyn osalta nähtiin myös neljäs nosto Tuukan kokeillessa 200 kiloa. Tähän osasyyllisenä oli allekirjoittanut, sillä edellinen nosto 190 kg vaikutti (väh. kahden toiston) sarjapainolta. 200 oli kuitenkin liikaa - liekö henkisesti ;) Muutkin nostajat loistivat, sillä ennätyksiä taisivat rikkoa lähes kaikki.\n\n"},{"_type":"span","_key":"key-9-ev47f","text":""}],"markDefs":[{"_type":"link","_key":"key-10-ldw6w","href":"/_emdash/api/media/file/01KZ3GP3NRXYNTFCDHRZFFY78M.jpg"}]},{"_type":"image","_key":"key-12-u6rg2","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP3NRXYNTFCDHRZFFY78M.jpg","url":"/_emdash/api/media/file/01KZ3GP3NRXYNTFCDHRZFFY78M.jpg"},"alt":"dsc_2117"},{"_type":"block","_key":"key-20-2ue0u","style":"normal","children":[{"_type":"span","_key":"key-13-0md0m","text":"Uudet jäsenet Tuukka (kuvassa kyykkää) ja Ville (vasen varmistaja) edustivat kisan syväkyykkääjiä. Vaffa-Reijo tarkkailee (ja Voima-Jyri hyväksyy tuomiot)."},{"_type":"span","_key":"key-14-pqn8x","text":" \n\n"},{"_type":"span","_key":"key-15-wz07t","text":"Penkkipunnerrus\n","marks":["strong"]},{"_type":"span","_key":"key-16-cefvp","text":"Penkkipunnerrukseen mentäessä top 3 sijoituksista käytiin kovaa taistoa. 1. ja 2. sija oli Ivanilla ja Tuomaksella ja kolmannesta sijasta kamppailivat pääasiassa Tuukka, Axu ja Olof. Olof oli tästä jälkimmäisestä ryhmästä paras penkkaaja - näin oli myös viime kevään kisassa. Kovaa tulosta ennakoi selkeä lihasmassan lisäys ja lopputulos 145 kiloa oli kisan toiseksi kovin nosto.\n\n"},{"_type":"span","_key":"key-17-3asjv","text":"Penkkipunnerruksessa tuomiot aiheuttivat pientä älämölöä puutteellisen tuomarimäärän (2) vuoksi. Agitaattorin roolin otti viimein kirjurina toiminut Voima-Jyri: tasatilanteessa tuomitaan nostajan eduksi. Näin toimittiin myös kyykyssä. Penkkipunnerruksessa nähtiin Tuukalta jälleen neljäs nosto, joka tosin jäi rinnalle - tai oikeastaan puoliväliin nostomatkaa.\n\n"},{"_type":"span","_key":"key-18-ekb36","text":""}],"markDefs":[{"_type":"link","_key":"key-19-h1341","href":"/_emdash/api/media/file/01KZ3GP46PY8ZY829JNT2Y9NPT.jpg"}]},{"_type":"image","_key":"key-21-b6kbm","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP46PY8ZY829JNT2Y9NPT.jpg","url":"/_emdash/api/media/file/01KZ3GP46PY8ZY829JNT2Y9NPT.jpg"},"alt":"dsc_2134"},{"_type":"block","_key":"key-28-0fe5j","style":"normal","children":[{"_type":"span","_key":"key-22-f4uv5","text":"Kisan kovimmasta penkistä vastasi Ivan. Viimeinen nosto (kuvassa tosin ensimmäinen) 165 kiloa tuli ylös äänin 1-1."},{"_type":"span","_key":"key-23-056zd","text":" \n\n"},{"_type":"span","_key":"key-24-ymkea","text":"Maastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-25-wr7nd","text":"Kyykystä palauttavan penkin jälkeen siirryttiin maastanostolavalle. Tässä lajissa moni nostaja aloitti kolmannen satasen puolella. Tuomas ja Ivan vanhoina arvokisaajina pääsivät hiukan \"taktikoimaan\" ja nokittelemaan nostoissaan. Tuomaksen vakuuttava 257,5 kilon sumoveto oli kuitenkin viimeinen niitti, joka varmisti miehelle voiton. Villen 100 % RAW 220 kg oli allekirjoittaneen mielestä yksi kovimmista suorituksista, vaikka itsellä tulikin sama rauta ylös. Meikäläisen tyyli ei kuitenkaan ollut niin kaunis. Maastanosto oli muiden lajien tavoin täynnä ennätyksiä tai vähintään niiden sivuamisia.\n\n"},{"_type":"span","_key":"key-26-8emw9","text":""}],"markDefs":[{"_type":"link","_key":"key-27-ue1l3","href":"/_emdash/api/media/file/01KZ3GP4YBWTGSRKVXS41AY584.jpg"}]},{"_type":"image","_key":"key-29-osiih","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP4YBWTGSRKVXS41AY584.jpg","url":"/_emdash/api/media/file/01KZ3GP4YBWTGSRKVXS41AY584.jpg"},"alt":"dsc_2148"},{"_type":"block","_key":"key-37-q5akn","style":"normal","children":[{"_type":"span","_key":"key-30-n17wz","text":"Tuomaksen viimeinen vetoyritys: 270 kg. Irroitus on erittäin vahva, mutta tasapainon kanssa oli ongelmia. Lähellä oli, että takana olevaa peiliä ei olisi tarvinnut enää pestä."},{"_type":"span","_key":"key-31-c7jca","text":" \n\n"},{"_type":"span","_key":"key-32-5odrf","text":"Yhteenveto\n","marks":["strong"]},{"_type":"span","_key":"key-33-hyxf1","text":"Aivan kuten kyykky jo indikoi, menivät 1. ja 2. sija Tuomakselle ja Ivanille. Tuloksia voit tarkkailla oheisesta liitteestä jutun lopusta. Kolmas oli neljänsiä yrityksiä lukuunottamatta puhtaasti 9/9 nostoa suorittanut Tuukka. Painoonsa nähden nämä olivat erittäin kovat tulokset.\n\n"},{"_type":"span","_key":"key-34-zvyn0","text":"Vuoden viimeinen kisa oli ehdottomasti yksi HYV:n historian kovimmista ja tunnelmaltaan parhaimpia taisteluita. Nostajien kehitys on ollut viime vuosien aikana vähintääkin lineaarista erisuuruisilla (>1) kulmakertoimilla ja nopean ekstrapoloinnin tulos tietää hurjaa ensi vuotta,\n\n"},{"_type":"span","_key":"key-35-ec1qp","text":"Ja ei tietenkään unohdeta kisan jälkeistä tankkausta kattavassa sushibuffassa. Näin launtaisena ruuhka-aikanakin pöytä löytyy vaivatta, kunhan oikeat tyypit sen varaavat ;)\n\n"}],"markDefs":[{"_type":"link","_key":"key-36-1hky0","href":"/_emdash/api/media/file/01KZ3GP5B3003J3KSPRXA4VN08.jpg"}]},{"_type":"image","_key":"key-38-cfuob","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP5B3003J3KSPRXA4VN08.jpg","url":"/_emdash/api/media/file/01KZ3GP5B3003J3KSPRXA4VN08.jpg"},"alt":"dsc_2150"},{"_type":"image","_key":"key-43-kjxa9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP5TJJTEG7N9PG4GYF4NN.jpg","url":"/_emdash/api/media/file/01KZ3GP5TJJTEG7N9PG4GYF4NN.jpg"},"alt":"tulokset"},{"_type":"block","_key":"key-48-rwsde","style":"normal","children":[{"_type":"span","_key":"key-44-88bkt","text":"Klikkaa kuvaa nähdäksesi tulokset suurempana."},{"_type":"span","_key":"key-45-6io4k","text":" \n\n"},{"_type":"span","_key":"key-46-wny5k","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-47-g8946","text":"Kuvat: Voima-Jyri"}]}]' WHERE id = '01KZ3GD1FJATQQZRV3TW0PVRYE';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-10-9r8oz","style":"normal","children":[{"_type":"span","_key":"key-1-hcqlo","text":"Syksyn edustus ei siis ainoastaan jäänyt Tuomaksen käsiin, vaan myös Katariina (P.) ja Ivan kilpailivat molemmat sekä Helsingin aluemestaruudesta lokakuun loppupuolella että avoimen ikäluokan SM-kisoissa Sotkamossa marraskuussa.\n\n"},{"_type":"span","_key":"key-2-ceqd2","text":"Näiden mittelöiden raportoinnista vastaa pääosin Tuomas, sillä hän on ollut yhteydessä kisaajiin ja oli mukana myös Sotkamon Vuokatissa.\n\n"},{"_type":"span","_key":"key-3-5m0ib","text":"Helsingin aluemestaruus (Tuomas raportoi)\n","marks":["strong"]},{"_type":"span","_key":"key-4-e0pbm","text":"Allekirjoittanut ei valitettavasti tänä vuonna kisaamaan, mutta HYV:tä menestyksekkäästi edustivat seuran kaksi muuta lisenssivoimanostajaa Ivan ja Katariina. Molemmat ovat jonkin verran taistelleet loukkaantumisien kanssa ja lisäksi viime SVNL:n alaisista kisoista oli jo tovi jos toinenkin. Silti Kontulan kuntokellarissa ennätykset paukkuivat ja Katariina nappasi jopa aluemestaruuden nimiinsä, joka jäi viime vuonna harmittavasti vain yhden maastavedon päähän. Katariina penkkasi ja kyykkäsi myös uudet kisaennätykset 110 ja 60 kiloa. Maastanostossa Katariina tiesi, että toiseen suoritukseen oli otettava jo kovempi veto 165 kiloa. Näin saatiin kaikki mahdolliset paukut käyttöön. Se kannatti ja tanko tuli ylös. Näin kolmas yritys jätettiin ottamatta ja voitto varmistettiin.\n\n"},{"_type":"span","_key":"key-5-wg6xt","text":"Ivanilla kyykky sujui hyvin. Katariinan tavoin 3/3 hyväksyttyä nostoa ja viimeinen 215 oli kisaennätys. Alla Ivanin mietteitä kisasta:\n\n"},{"_type":"span","_key":"key-6-we19r","text":"\""},{"_type":"span","_key":"key-7-nrcvt","text":"Kisa oli todella onnistunut. Tavoitteena oli 105-kilon sarjan tulosraja 9 rennolla nostolla ja niinhän siinä kävi, että se tuli aika kevyesti! Omaa kehonpainoa ei optimoitu, koska oltiin tavallista ylemmässä painoluokassa. Silti olin sarjan kevyin kilpailija 96 kiloisena. Osa ihmettelikin sarjavalintaani... Jatkoa ajatellen voin rauhassa miettiä sarjaani tulevissa SM-kisoissa. Lopputulema siis erinomainen: käteen jäi 4. sija yhteistuloksella 600 (215-155-230) sekä varapaikka klassisen voimanoston Pääkaupunkiotteluun Helsinki-Tukholma-Tallinna, joka pidetään Tukholmassa kesäkuussa 2017.\"\n","marks":["em"]},{"_type":"span","_key":"key-8-gilkz","text":""}],"markDefs":[{"_type":"link","_key":"key-9-5cuan","href":"/_emdash/api/media/file/01KZ3GP6J2PMVS05E8V9TQ5X6X.jpg"}]},{"_type":"image","_key":"key-11-7vdxi","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP6J2PMVS05E8V9TQ5X6X.jpg","url":"/_emdash/api/media/file/01KZ3GP6J2PMVS05E8V9TQ5X6X.jpg"},"alt":"aluemestaruus-katariina-palkinto"},{"_type":"block","_key":"key-16-d5sq0","style":"normal","children":[{"_type":"span","_key":"key-12-1q699","text":"Katariina pääsi nostelemaan kisan jälkeen hiukan erilaista rautaa. (Kuva: Juha Martikainen)"},{"_type":"span","_key":"key-13-7whh0","text":" \n\n"},{"_type":"span","_key":"key-14-bfo5n","text":""}],"markDefs":[{"_type":"link","_key":"key-15-6buwk","href":"/_emdash/api/media/file/01KZ3GP6435NRA3P0ZXNHT9HW8.jpg"}]},{"_type":"image","_key":"key-17-vpfzx","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP6435NRA3P0ZXNHT9HW8.jpg","url":"/_emdash/api/media/file/01KZ3GP6435NRA3P0ZXNHT9HW8.jpg"},"alt":"aluemestaruus-ivan-kyykky"},{"_type":"block","_key":"key-45-hq8lg","style":"normal","children":[{"_type":"span","_key":"key-18-sm08l","text":"Paineet ja kimmoisuus olivat kunnossa Kontulassa! (Kuva: Juha Martikainen)"},{"_type":"span","_key":"key-19-4d5m1","text":"Tästä linkistä pääset vielä katsomaan tarkemmin tuloksia:\n\n"},{"_type":"span","_key":"key-21-rinra","text":"http://www.tikkurilankajastus.fi/PSS/tiedostot/20161029Klassisen_voimanoston_26_HelsinginAluemestaruus_Poytakirja.pdf\n","marks":["key-20-hgd66"]},{"_type":"span","_key":"key-22-qi2gj","text":" \n\n"},{"_type":"span","_key":"key-23-d0a39","text":"Avoimen ikäluokan SM (Tuomas raportoi)\n","marks":["strong"]},{"_type":"span","_key":"key-24-eqvp1","text":"Olin mukana lähes alusta asti Ivanin kaartaessa Itä-Suomen ylilopiston pihaan perjantaina alkuillasta. Huomasin heti, että tunnelma oli varsin rento, koska sekä Ivanilla että Katariinalla oli molemmilla ennätykset taskuissaan. Katariinan oma painokin oli niin hyvällä mallilla, että pystyimme käymään Kuopion Sataman Kotipizzassa ennen Sotkamoon suuntaamista. Ivanilla taas oli painovetoon soveltuvat eväät mukana ja näin tarkan suunnitelman saattelemana puntarista päästiin läpi. Samaan aikaan alkoikin jo Katariinan nostaminen. Sama kyykkysarja kuin aluemestaruuskisoissa varmasti kovemmissa olosuhteissa oli erinomainen suoritus. Penkissä otettiin varman päälle ja aloitus oli 2,5 kg kevyempi kuin Kontulassa. Katariina sivusi kuitenkin kisaennätystään astetta vaativimmissa olosuhteissa.\n"},{"_type":"span","_key":"key-25-wtu5b","text":"Vaikka olinkin virallisemmin Ivanin huoltaja, niin annoin Katariinalle vinkkiä, että välillä kisoissa on ok skipata toinen veto ja säästää paukut viimeiseen suoritukseen. Näinpä kellosta odotettiin toinen minuutti loppuun ja lepoa saatiin hiukan enemmän. Nyt Katariina halusi iskeä 160 kg tankoon, vaikkakin 155 olisi riittänyt sijan kohentamiseen. Valitettavasti paukut olivat lopussa ja 160 jäi lattiaan. Silti hyvä suoritus ensimmäisissä SM-kisoissa - sijoitus 10.\n\n"},{"_type":"span","_key":"key-26-qi24f","text":"Katariinan kyykky 110 kg: "},{"_type":"span","_key":"key-28-y6db7","text":"https://youtu.be/99xq3qd34xY?t=16025\n","marks":["key-27-xnp92"]},{"_type":"span","_key":"key-29-inyc5","text":"Katariinan penkki 60 kg: "},{"_type":"span","_key":"key-31-5jd3e","text":"https://youtu.be/99xq3qd34xY?t=20001\n","marks":["key-30-x7dq4"]},{"_type":"span","_key":"key-32-90a0k","text":"Katariinan maastanosto 145 kg: "},{"_type":"span","_key":"key-34-oika1","text":"https://youtu.be/99xq3qd34xY?t=24350\n","marks":["key-33-7onif"]},{"_type":"span","_key":"key-35-pgngc","text":"Katariinan nostojen jälkeen oli Ivanin vuoro. Huoltajana vastasin alkulämmittelyjen tahdista Ivanin omasta pyynnöstä, sillä painon vedättäminen oli päässyt vaikuttamaan myös pääkoppaan. Viimeisenä lämmittelynä otettiin 190 kg, jonka syvyys oli aika lailla millimetripeliä...\n\n"},{"_type":"span","_key":"key-36-5qank","text":"Tässä Ivanin omia mietteitä:\n\n"},{"_type":"span","_key":"key-37-t23mz","text":"\""},{"_type":"span","_key":"key-38-yfvsv","text":"Vähän vaikea sanoa, mikä meni meni tarkalleen ottaen pieleen, mutta arvelen, että tankkaus ei ihan riittänyt/toiminut. Tyhjennys onnistui siinä mielessä, että painoin punnituksessa 92,75 kg, mutta viimeiseen asti joutui odottamaan tankkausta, sillä edellisenä päivänä oli 0,9 kg liikaa. Kisapäivänä erittäin kevyt aamupala ja lounas. Punnituksen jälkeen vielä hyvä fiilis, mutta lämmittelyissä tuli jo tosi nihkeä olo, eikä meinannut saada kunnolla happea. Lähestymissarjat olivat kaikin puolin hyviä ja syviä, mutta hengästytti epätavallisen paljon ja tuntui siltä, kuin aivot eivät toimisi kunnolla. Lavalla sitten syvyystuntuma katosi ilmeisesti kokonaan, kun kaikki (hylätyt) nostot tuntuivat syviltä. Itse rauta ei painanut paljon mitään, eikä oma tasokaan voinut hermotusjakson jälkeen ainakaan hirveästi laskea, kun reilu kuukausi sitten kyykättiin 215 kg todella helposti. Eniten jäi harmittamaan se, ettei päässyt penkkaamaan, kun kunto on tällä hetkellä 165 kg:n luokkaa. Ja vedostakin olisi tullut ainakin se 230 kg vaikka väkisin, joten aika hyvää jälkeä olisi saatu aikaiseksi, jos leikki ei olisi jäänyt noin nopeasti kesken...\"\n","marks":["em"]},{"_type":"span","_key":"key-39-rakhq","text":"HYV:n väki voi antaa arvionsa Ivanin kyykyistä (video ensimmäisestä nostosta alkaen):\n\n"},{"_type":"span","_key":"key-41-x8xu0","text":"https://youtu.be/99xq3qd34xY?t=29272\n","marks":["key-40-biktu"]},{"_type":"span","_key":"key-42-s0cbr","text":"Näin ollen ensimmäisistä SM-kisoista tuli Ivanille hiukan enemmän opettavaisempi kokemus kuin alunperin oli suunniteltu. Paluumatka sujui kuitenkin mukvasti tulevaisuuden tavoitteista keskustellen: Katariina kertoi vaihtavansa painonnostoon, mutta Ivanilla oli tulevaisuus vielä avoin. Lajinvaihdosta tuskin on kyse.. Keväällä minut (Tuomas) ja Ivanin voi nähdä Sell Games-kisoissa Latviassa.\n\n"},{"_type":"span","_key":"key-43-8983u","text":" \n\n"},{"_type":"span","_key":"key-44-ws3i2","text":"Tekstit: Tuomas ja Pro-Jaakko"}],"markDefs":[{"_type":"link","_key":"key-20-hgd66","href":"http://www.tikkurilankajastus.fi/PSS/tiedostot/20161029Klassisen_voimanoston_26_HelsinginAluemestaruus_Poytakirja.pdf"},{"_type":"link","_key":"key-27-xnp92","href":"https://youtu.be/99xq3qd34xY?t=16025"},{"_type":"link","_key":"key-30-x7dq4","href":"https://youtu.be/99xq3qd34xY?t=20001"},{"_type":"link","_key":"key-33-7onif","href":"https://youtu.be/99xq3qd34xY?t=24350"},{"_type":"link","_key":"key-40-biktu","href":"https://youtu.be/99xq3qd34xY?t=29272"}]}]' WHERE id = '01KZ3GD2EQX2A0411TXFFX20ZS';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-14-9eozn","style":"normal","children":[{"_type":"span","_key":"key-1-3cnyy","text":"Uusi vuosi on startannut, mutta Voimaliiga jatkui 4. osakilpailulla. Vuorossa oli sotilaspenkki, joka koostui kahdesta lajista: ykkös- ja toistomaksimista. Osanottajia oli harmittavan vähän, mutta se ei todellakaan estänyt kovien tulosten saamista. Ehkä nämä uudet jäsenet ovat saaneet vanhat konkarit varpailleen, eikä siten puolikuntoisena haluta tulla paikalle ;) Toivotaan toukokuun kisasta sitten vielä kovempaa, sillä sinne kuntoon pääseminen on vielä mahdollista.\n\n"},{"_type":"span","_key":"key-2-a07g4","text":"Ykkösmaksimit\n\n","marks":["strong"]},{"_type":"span","_key":"key-3-2wj1i","text":"Ykkösmaksimiin jokaisella oli käytössään kolme suoritusta. Taktikointi oli mahdollista, sillä voimien säästäminen saattoi voittaa kilpailijalle tarvittavat pisteet. Yusif tuoreimpana HYV:n jäsenenä edusti kisan keveintä kilpailijaa. Painoa oli vain 75,3 kiloa ja ennen kisaa hän sanoi olevansa tyytyväinen yli 120 kilon tulokseen! Tuukka ja Ville olivat kaksi muuta kisaajaa. Molemmat heistä olivat yli 120 kilon penkkaajia joulukuun kisassa, joten tiukka kamppailu oli tiedossa.\n\n"},{"_type":"span","_key":"key-4-sh7d0","text":"Sääntöjen kertaaminen oli jälleen tarpeen ja komentoja ei voi tarpeeksi painottaa: Yusif kiirehti ensimmäisen, tosin suht kevyen, nostonsa telineisiin. 10 kilon korotusta 125:een \"epäonnistunut\" nosto ei kuitenkaan estänyt. Tuukka ja Ville olivat harjaantuneita joulukuun kisasta ja ongelmia komentojen kanssa ei ollut.\n\n"},{"_type":"span","_key":"key-5-a7w54","text":"Ensimmäiset nostot olivat kaikilta suhteellisen varmoja. Toisissa suorituksissa Yusif asetti riman korkealle: 125 kiloa, joka tarkoitti Villen ja Tuukan osalta sitä, että kolmanteen nostoon olisi ladottava jo noin 140 kiloa! Tätä ei nähty ja lopullisiksi tuloksiksi jäivät:\n"},{"_type":"span","_key":"key-6-ueqhp","text":"1. Yusif 127,5 kg (WILKS 90,60)\n"},{"_type":"span","_key":"key-7-n0sra","text":"2. Tuukka 125 kg (WILKS 80,74)\n"},{"_type":"span","_key":"key-8-03yak","text":"3. Ville 120 kg (WILKS 78,28)\n\n"},{"_type":"span","_key":"key-9-8yjoq","text":"Toistokisa\n","marks":["strong"]},{"_type":"span","_key":"key-10-8kgh6","text":"Ennen sen enempiä puheita, on mainittava että penkkimaksimi ei aina korreloi toistojen kanssa. Varsinkaan silloin, kun toistopainot ovat alle 70 % maksimeista. Pienen tauon jälkeen Yusif siirtyi johtoasemissa toistokisaan. Mies osoitti myös omaavansa kestävyyttä ja voitto irtosi tässäkin 21 toiston tuloksella. Näin Tuukalle ja Villelle jäi ratkaistavaksi toinen ja kolmas sija.\n\n"},{"_type":"span","_key":"key-11-690tr","text":"Tuukan suorituksessa nähtävät toistot olivat erittäin hallittuja ja \"puoli\"stopilla tehtyjä. Tämä kenties söi voimia ja tulokseksi jäi 11 toistoa. Mut hei, luultavasti hyvä pumppi ja lihas kasvoi... ;) Villen osittain tuntien, tiesin että toistokisassa hän olisi kova. Näin olikin ja mies taisteli 14 toistoa, joka tarkoitti Villelle ja Tuukalle jaettua toista sijaa koko osakilpailusta.\n\n"},{"_type":"span","_key":"key-12-ffgr6","text":"Alla vielä tuloksia\n\n"}],"markDefs":[{"_type":"link","_key":"key-13-xik4j","href":"/_emdash/api/media/file/01KZ3GP7HY7VS79W7RWX9C2JMS.jpg"}]},{"_type":"image","_key":"key-15-vsh22","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP7HY7VS79W7RWX9C2JMS.jpg","url":"/_emdash/api/media/file/01KZ3GP7HY7VS79W7RWX9C2JMS.jpg"},"alt":"Tulokset"},{"_type":"image","_key":"key-18-xj4lb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP70JMMXC6B1CV0HGHJ6T.jpg","url":"/_emdash/api/media/file/01KZ3GP70JMMXC6B1CV0HGHJ6T.jpg"},"alt":"Yhteiskuva"},{"_type":"block","_key":"key-22-4jcb3","style":"normal","children":[{"_type":"span","_key":"key-19-8ctyb","text":"\n"},{"_type":"span","_key":"key-20-glika","text":"Tällä hetkellä Voimaliigan pistetilanne on seuraava (Voima-Jyri jaetulla ensimmäisellä sijalla yhdessä Tuukan kanssa).\n\n"}],"markDefs":[{"_type":"link","_key":"key-21-7qh9u","href":"/_emdash/api/media/file/01KZ3GP85HB8SFFKMT5F2E7H4S.jpg"}]},{"_type":"image","_key":"key-23-y7pap","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP85HB8SFFKMT5F2E7H4S.jpg","url":"/_emdash/api/media/file/01KZ3GP85HB8SFFKMT5F2E7H4S.jpg"},"alt":"Pistetilanne penkkikisan jälkeen"},{"_type":"block","_key":"key-28-jjbsb","style":"normal","children":[{"_type":"span","_key":"key-24-atod5","text":"\n"},{"_type":"span","_key":"key-25-tdrgn","text":" \n\n"},{"_type":"span","_key":"key-26-euk00","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-27-202ng","text":"Kuva: HST-Esa"}]}]' WHERE id = '01KZ3GD3EHPMKTJGR2SEQG9JW4';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-4wdw4","style":"normal","children":[{"_type":"span","_key":"key-1-y8jjt","text":"Jo muutaman viikon ajan on ollut puhetta tehdä jonkinlainen hiilaritankkaus-artikkeli. Idea aiheelle on tullut vanhempien HYV-konkareiden kanssa käydyistä lounaista, joissa kyseinen teema tulee selkeästi esille.\n\n"},{"_type":"span","_key":"key-2-70ouq","text":"Perusteet\n","marks":["strong"]},{"_type":"span","_key":"key-3-fmfpv","text":"Kaikille on varmastikin selvää, että lihasmassaa saavuttaakseen on makrojakauman oltava aika paljon hiilihydraattipainotteinen. Proteiinit ja rasvat ovat toki tärkeitä, mutta niiden määrä ei ole merkittävä lihaksikkaan ja kovaa treenavan henkilön ruokavaliossa. Jos mietimme, että rasvagrammasta saadaan 9 kcal ja proteiinigrammasta 4 kcal ja tarpeet ovat:\n"},{"_type":"span","_key":"key-4-2tc3h","text":"- Proteiini (karkeasti) 2 g/rasvaton massa. Naisilla hiukan vähemmän.\n"},{"_type":"span","_key":"key-5-1g1f7","text":"- Rasva (karkeasti) 1 g /rasvaton massa,\n"},{"_type":"span","_key":"key-6-9ay65","text":"niin on näiden (kilo)kalorimäärä yhteensä 90 kiloisella urheilijalla noin 1650. Jos sama henkilö treenaa kovalla volyymilla, jää hiilihydraateille noin 2000 kcal osuus, joka vastaa noin puolta kiloa hiilihydraattia. Jos treenaaminen on jatkuvaa (ts. miltein jokapäiväistä), voivat määrät nousta 700 grammaan.\n\n"},{"_type":"span","_key":"key-7-kqngd","text":"Itse asiassa kovemmalla bulkilla on suotavaa nostaa kalorit reilusti yli ylläpidon. Ideana on saada nämä ekstrakalorit juurikin hiilareista, vaikka jotkut massiivisimmat promiehet kuuluttavat prosenttiosuuksien perään. Itse en tähän ryhmää kuulu, mutta en olekaan \"massiivinen\". Lue lopusta löytyvä artkikkeli!\n\n"},{"_type":"span","_key":"key-8-yuiue","text":"Lyhyesti omasta ruokavaliosta: säätelyä tehdään ainoastaan hiilihydraattien avulla: normaalitreenit, jotka koostuvat 1-5 toistoista (ilman aerobisia), on hiilarimäärä noin 400 grammaa päivässä. Kun treeneihin tulevat mukaan aerobiset ja toistoalueet ovat 6+, liikkuvat hiilihydraatit 600-800 gramman välillä. Proteiinit (150-200 g) ja rasvat (60-80 g) pysyvät vakioina. Hiilihydraatit saadaan joko yhdestä tai kahdesta päivän ruuasta.\n\n"},{"_type":"span","_key":"key-9-jxb2e","text":""}],"markDefs":[{"_type":"link","_key":"key-10-8ovty","href":"/_emdash/api/media/file/01KZ3GP8NT3JWVYZDHHZHN4ZKV.jpeg"}]},{"_type":"image","_key":"key-12-w0zvy","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP8NT3JWVYZDHHZHN4ZKV.jpeg","url":"/_emdash/api/media/file/01KZ3GP8NT3JWVYZDHHZHN4ZKV.jpeg"},"alt":"hiilari"},{"_type":"block","_key":"key-21-v1if7","style":"normal","children":[{"_type":"span","_key":"key-13-7dkmh","text":"Illan lämmin ruoka: 300 g hh, 50 g pro ja 20 g fat"},{"_type":"span","_key":"key-14-adnl4","text":"Kuinka toteuttaa?\n","marks":["strong"]},{"_type":"span","_key":"key-15-kgr0w","text":"HYV:n väki on voimailun lisäksi erikoistuneet hiilaritankkauksiin. Lounasseminaarit erinäisissä Helsingin keskustan buffet-ravintoloissa ovat olleet opettavaisia meille kaikille. Vanhimmat jäsenet kannattavat usein sushiravintoiloita tankkauspaikkoina (kalasta hyvät rasvat ja sushista löytyy riisi), joka tarkoittaa usein vähintään 40 sushin annosta per osanottaja. Joillekin tuo 40 kappaletta tekee tiukkaa, mutta provinkit löytyvät: vähennä tai älä ota lainkaan soijaa. Nesteytyksestä on myös huolehdittava näin suurien hiilihydraattimäärien yhteydessä.\n\n"},{"_type":"span","_key":"key-16-iroe8","text":"Muita tapoja on pelkän puhtaan riisin/pastan/perunan syöminen muutamine liha- ja kasvislisukkeineen. Leivän syöminen on myös mahdollista, mutta suolan määrä saattaa olla näissä korkeat.  Tämä tarkoittaa, että suuret annokset eivät välttämättä ole kovinkaan fiksua.\n\n"},{"_type":"span","_key":"key-17-3nh56","text":"Yleensä massiivisiin lounaisiin on syytä varata noin tunti ja seuraavan treenin alkamiseen vähintään 5 tuntia. Kylmiltään nämä suoritukset eivät monelta onnistu, joten seminaareihin osallistuminen \"takki auki\" -meiningillä ei kannata!\n\n"},{"_type":"span","_key":"key-18-xf610","text":"Artikkelin lyhyyden syy on selkeä: kaikkea tietämystä ei paljasteta! Mahdolliset yhteistyökumppanit esteenä? ;)\n\n"},{"_type":"span","_key":"key-19-uhkmi","text":""}],"markDefs":[{"_type":"link","_key":"key-20-g1di5","href":"/_emdash/api/media/file/01KZ3GP97AY5TAW2EAJVGWB4EQ.jpg"}]},{"_type":"image","_key":"key-22-gijz1","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GP97AY5TAW2EAJVGWB4EQ.jpg","url":"/_emdash/api/media/file/01KZ3GP97AY5TAW2EAJVGWB4EQ.jpg"},"alt":"Lounas"},{"_type":"block","_key":"key-38-svxtm","style":"normal","children":[{"_type":"span","_key":"key-23-24i0r","text":"Lounasseminaari: aktiivista keskustelua sekä HYV:n toiminnasta että treenaamisesta. Suojaisa paikka ravintolassa antaa rauhan."},{"_type":"span","_key":"key-24-u0b1j","text":"Suosituimmat paikat\n","marks":["strong"]},{"_type":"span","_key":"key-25-p5bqs","text":"Keskusta-alueelta löytyy ainakin pari: Caverna, jossa myös laaja kattava lämmintä ruokaa sekä suurista susheista tunnettu Kita. Yleensä näistä paikoista löytyy varattu 4 hengen pöytä ja paikat menevät suhteellisen nopeasti... Siksi olikin syytä tehdä artikkeli käydyistä keskusteluista.\n\n"},{"_type":"span","_key":"key-26-haxyq","text":" \n\n"},{"_type":"span","_key":"key-27-h0d47","text":"Lähteet:\n\n"},{"_type":"span","_key":"key-29-5wyxo","text":"http://suppversity.blogspot.fi/2015/07/get-your-macros-straight-in-two-minutes.html\n","marks":["key-28-5ejf1"]},{"_type":"span","_key":"key-31-jit28","text":"http://suppversity.blogspot.fi/2012/03/if-you-go-high-carb-you-better-go.html\n","marks":["key-30-k2lwu"]},{"_type":"span","_key":"key-33-587u1","text":"http://suppversity.blogspot.fi/2013/06/bulking-done-right-what-can-latest-100.html\n","marks":["key-32-6dnvi"]},{"_type":"span","_key":"key-34-f3oqm","text":"https://lihastohtori.wordpress.com/2014/02/14/kalori-on-kalori/\n\n"},{"_type":"span","_key":"key-35-rehy8","text":" \n\n"},{"_type":"span","_key":"key-36-tug9p","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-37-tyqj1","text":"Kuvat; Pro-Jaakko, HST-Esa"}],"markDefs":[{"_type":"link","_key":"key-28-5ejf1","href":"http://suppversity.blogspot.fi/2015/07/get-your-macros-straight-in-two-minutes.html"},{"_type":"link","_key":"key-30-k2lwu","href":"http://suppversity.blogspot.fi/2012/03/if-you-go-high-carb-you-better-go.html"},{"_type":"link","_key":"key-32-6dnvi","href":"http://suppversity.blogspot.fi/2013/06/bulking-done-right-what-can-latest-100.html"}]}]' WHERE id = '01KZ3GD4QEPCHKNW7JNJNJ7KWF';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-4-mr2uv","style":"normal","children":[{"_type":"span","_key":"key-1-l1xww","text":"Voimaliigan toiseksi viimeinen kisa käytiin leuanvedon merkeissä. Vuorossa siis toistokisa omalla painolla.\n\n"},{"_type":"span","_key":"key-2-fefb5","text":""}],"markDefs":[{"_type":"link","_key":"key-3-qokk9","href":"/_emdash/api/media/file/01KZ3GPA5BGHV0SWT38AHPE932.jpg"}]},{"_type":"image","_key":"key-5-ivr98","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPA5BGHV0SWT38AHPE932.jpg","url":"/_emdash/api/media/file/01KZ3GPA5BGHV0SWT38AHPE932.jpg"},"alt":"Kisaajat vasemmalta ylhäältä alkaen: Pasi, Tuukka, Jaakko. Alhaalla Leo ja Yusif"},{"_type":"block","_key":"key-20-nw1s2","style":"normal","children":[{"_type":"span","_key":"key-6-z51ug","text":"Kisaajat vasemmalta ylhäältä alkaen: Pasi, Tuukka, Jaakko. Alhaalla Leo ja Yusif"},{"_type":"span","_key":"key-7-cc6zl","text":"Sosialistisessa mediassa oli ollut paljon puhetta vaaleista, mutta sosiaalisessa mediassa keskustelu taas oli painottunut kahden osallistujan leuanvetokuntoon. Molemmissa tapauksissa oli myös havaittavissa jonkinasteista uhoamista aina huhtikuun alkuun asti, jolloin voitiin todistaa kuka todella on tämän Voimaliigakauden kovin (kippi)leuanvetäjä ja kuka suurin takinkääntäjä.\n\n"},{"_type":"span","_key":"key-8-vt73l","text":"Allekirjoittanut piti itseään varmana voittaja, kunnes Strykka-Leo aloitti kehuskelun kunnollaan. Tämä johti siihen, että oli alettava oikeasti treenaamaan! Lähes kaikki osallistuja treenasivat pääosin Otahallilla, jonka johdosti sain sisäpiiritietoa ja pystyin olemaan suht luottavaisin mielin. Tosin, ei heitä voinut pitää täysin itsestäänselvyyksinä vaa''an lähennellessä kolminumeroista lukua...\n\n"},{"_type":"span","_key":"key-9-6lwq8","text":"Kisasuoritukset alkoivat käänteisessä ilmoittautumisjärjestyksessä, joten ensimmäisenä vetäjänä oli HYV:n tuore jäsen Pasi. Styrkan komeiden komentojen kaikuessa ympäri länsi-Helsinkiä, Pasi suoritui kisasta isokokoiseksi vetäjäksi erinomaisesti. Mies valitteli hiukan harjoitusjakson lyhyyttä ja voi ollakin, että ensi vuonna nähdään paljon kovempi suoritus! Seuraavaksi vuorossa oli Strykka, joka taisteli itselleen 24"},{"_type":"span","_key":"key-10-dz8bs","text":" ","marks":["strong"]},{"_type":"span","_key":"key-11-lmyne","text":"toistoa. Tämä ehkä aiheutti hetkellisen nousun leposykkeessä, mutta koska oma tavoite oli 30+, niin ajattelin, että huolia ei ole...\n\n"},{"_type":"span","_key":"key-12-5tc1c","text":"Yusif, joka oli osoittanut matalan kehonpainonsa (ja toki voimansa) hyödyt aiemmin sotilaspenkkikisassa, oli myös erittäin kova leuoissa. Sen näkeekin oheisesta videosta: räjähtävät lähdöt saivat tuomarin tarttumaan häkistä kiinni, jotta suuremmilta henkilövahingoilta tultaisiin välttymään. Yusif hävisi niukasti yhdellä toistolla Strykalle.\n\n"},{"_type":"span","_key":"key-13-cwi75","text":"Toiseksi viimeinen vetäjä oli Tuukka. Tuukan fokus oli selvästikin ollut voimanostossa, joka oli varmaankin aivan oikea valinta. Tekstiä kirjoittaessa miehen YT oli kasvanut huomattavasti (enemmän kuin oma paino). Näin ollen mies ei sen kummemmin stressannut tuloksista, vaan haki pari voimaliigan pistettä taskuunsa.\n\n"},{"_type":"span","_key":"key-14-cuztf","text":"Viimeisenä vuorossa olin minä. Lämmittelyvedot tuntuivat raskaalta ja vaikka en ollut syönyt aamulla mitään, oli painoa yli 96 kiloa. Näillä siis lienee olleen jotain yhteyttä. Tulos jäikin tavoitteista: 28 toistoa, mutta silti voitto ja samalla Voimaliigan kärkeen! ;)\n\n"},{"_type":"span","_key":"key-15-vtfst","text":"Voimaliiga jatkuu n. kuukauden päästä viimeisellä osakilpailulla, joka tulee olemaan ruuhkainen voimanosto Otahallilla.\n\n"},{"_type":"span","_key":"key-16-y0jw6","text":"TULOKSIA JA VIDEOPÄTKÄÄ ALLA!!\n","marks":["strong"]},{"_type":"span","_key":"key-17-4p78r","text":"https://www.youtube.com/watch?v=YnrwoBodbpc\n\n"},{"_type":"span","_key":"key-18-e1yze","text":"Tulokset:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-19-0yolf","href":"/_emdash/api/media/file/01KZ3GPBRZ1TKVRHZFJDE6S87F.jpg"}]},{"_type":"image","_key":"key-21-sl8kb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPBRZ1TKVRHZFJDE6S87F.jpg","url":"/_emdash/api/media/file/01KZ3GPBRZ1TKVRHZFJDE6S87F.jpg"},"alt":"Leukatulos"},{"_type":"block","_key":"key-26-v5wyj","style":"normal","children":[{"_type":"span","_key":"key-22-oaatt","text":"\n"},{"_type":"span","_key":"key-23-3o8qp","text":" \n\n"},{"_type":"span","_key":"key-24-iv5fj","text":"Voimaliigan pistetilanne:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-25-icna4","href":"/_emdash/api/media/file/01KZ3GPC8GZDN61MT0SX93J6F0.jpg"}]},{"_type":"image","_key":"key-27-fr45r","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPC8GZDN61MT0SX93J6F0.jpg","url":"/_emdash/api/media/file/01KZ3GPC8GZDN61MT0SX93J6F0.jpg"},"alt":"Voimaliigan pistetilanne"},{"_type":"block","_key":"key-33-j6sf3","style":"normal","children":[{"_type":"span","_key":"key-28-kasrd","text":"\n"},{"_type":"span","_key":"key-29-100pm","text":" \n\n"},{"_type":"span","_key":"key-30-6mfd8","text":"Teksti: Pro-Jaakko\n\n"},{"_type":"span","_key":"key-31-r1mbp","text":"Video: Yusif\n\n"},{"_type":"span","_key":"key-32-0wcgx","text":" "}]}]' WHERE id = '01KZ3GD5R5CRVY6E9DC7HWKTJP';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-9-0vb7g","style":"normal","children":[{"_type":"span","_key":"key-1-sm2e6","text":"Toukokuun viimeisen viikonlopun aikana Otahallin perustukset laitettiin erittäin koville 12 kisaajan astuessa voimanostolavoille. Märkätiloja lukuunottamatta kiinteistö ei vielä onneksi tuonut ilmi peruskorjaustarpeita, joten treenaamista voitaneen jatkaa vielä kesän yli kohti seuraavaa kautta.\n\n"},{"_type":"span","_key":"key-2-64lm8","text":"Joulukuussa kirjoitin kisan olleen ennätyskova ja samaa voisin sanoa myös nyt. Rekrytointi Otahallilta oli onnistunut hyvin ja lisäksi (pelotteena) voidaan mainita se, että ainakin kolme kovaa nostajaa jätti tulematta loukkaantumisen tai sairastumisen vuoksi. Ensi joulukuun kisaan on siis suotavaa aloittaa valmistautuminen per heti!\n\n"},{"_type":"span","_key":"key-3-wsths","text":"Viime kisasta oli opittu se, että tuomareita on oltava kolme. Paikalle siis saatiin HYV:n jäsenten Jyrin ja Sampsan lisäksi kansainvälisissä voimanostokisoissakin edustanut Hanna Seppä.\n\n"},{"_type":"span","_key":"key-4-s0p8e","text":"Tekstin voinen jättää melko lyhyeksi, sillä Yusif urhasi puhelimensa koko kisan ajaksi ja kaikki nostot saatiin talteen. Joten ota mukava asento ja tee omat analyysisi nostoista!\n\n"},{"_type":"span","_key":"key-5-19atg","text":"Jalkakyykky\n","marks":["strong"]},{"_type":"span","_key":"key-6-bu29g","text":"Punnitus alkoi tuntia ennen ensimmäistä kyykkysuoritusta. Tason ollessa kova, oli useampi kilpailija vedättänyt painoaan alas. Paineiden saaminen takaisin riisin, pullan ja makeisten voimin oli kovan tuskan takana ja osalla hiilari tuli samaa tietä ylös kisan edetessä.\n\n"},{"_type":"span","_key":"key-7-lex2d","text":""}],"markDefs":[{"_type":"link","_key":"key-8-49g6m","href":"/_emdash/api/media/file/01KZ3GPDWGYFZ9ZJJSBNBNMS5G.jpg"}]},{"_type":"image","_key":"key-10-auckr","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPDWGYFZ9ZJJSBNBNMS5G.jpg","url":"/_emdash/api/media/file/01KZ3GPDWGYFZ9ZJJSBNBNMS5G.jpg"},"alt":"Menetetyt lihaspaineet pyrittiin saamaan takaisin mm. pullan avulla."},{"_type":"block","_key":"key-16-ttl1s","style":"normal","children":[{"_type":"span","_key":"key-11-r7ve6","text":"Menetetyt lihaspaineet pyrittiin saamaan takaisin mm. pullan avulla."},{"_type":"span","_key":"key-12-39h5a","text":"Uusi kilpailijoita (HYV:n voimanostossa) oli mukana nippukaupalla: Veera, Eero, Simo, Pasi ja Max, joista lähes kaikki tekivät PR:n. Tuomas kisasi kisan ulkopuolella testaten vetopukuaan. Tulokset olisivat miehellä olleet varmasti samaa luokkaa myös ilman trikoitakin ;)\n\n"},{"_type":"span","_key":"key-13-nub7l","text":"Yli 200 kyykkyjä nähtiin tällä kertaa 3 kappaletta Tuomaksen, Tuukan ja Ivanin pyrkiessä jättää pysyvän mutkan Otahallin tankoon.\n\n"},{"_type":"span","_key":"key-14-e0uhl","text":""}],"markDefs":[{"_type":"link","_key":"key-15-kb65m","href":"/_emdash/api/media/file/01KZ3GPGB63WWWQ8ZHD1YWH0YZ.jpg"}]},{"_type":"image","_key":"key-17-1z1af","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPGB63WWWQ8ZHD1YWH0YZ.jpg","url":"/_emdash/api/media/file/01KZ3GPGB63WWWQ8ZHD1YWH0YZ.jpg"},"alt":"Yusif vastasi ehkä kisan kovimmasta taistelusta kyykyssä (jos failureita ei lasketa)."},{"_type":"block","_key":"key-28-o6l7z","style":"normal","children":[{"_type":"span","_key":"key-18-rnnvt","text":"Yusif vastasi ehkä kisan kovimmasta taistelusta kyykyssä (jos failureita ei lasketa). Taustalla uudet jäsenet Veera ja Simo."},{"_type":"span","_key":"key-19-me20b","text":"Penkkipunnerrus\n","marks":["strong"]},{"_type":"span","_key":"key-20-eahz7","text":"Ennen ensimmäistä punnerrussuoritusta keskustelua aiheutti kisapenkin valinta. Suurin osa kisaajista oli treenannut hiukan leveämmällä (mutta ilmeisesti liian matalla) penkillä koko kauden. Tuomareiden painostaminen ei kuitenkaan onnistunut ja kisapenkiksi valittiin viime vuoden tapaan \"huonompi\" vaihtoehto. Tämä oli iso pettymys ja ehkä syy siihen, että moni epäonnistui viimeisen kierroksen suorituksessaan. ;)\n\n"},{"_type":"span","_key":"key-21-fhu04","text":"Viime vuoden tapaan Ivan vastasi kisan kovimmasta penkistä: 152,5 kg. Tuukka ja Tuomas eivät tosin jääneet kauaksi. Toisaalta, Ivan penkannee hyvänä päivänä 160 kg...\n\n"},{"_type":"span","_key":"key-22-adloi","text":"Maastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-23-46jyx","text":"Penkin aikana sulatetut ruuat olivat kenties päätyneet jo takareisiin, kun vuorossa oli maastanosto. Jälleen vaativa kirjurimme laittoi lämmittelyyn vauhtia ja monen oli noustava 200 kiloon vain muutamassa minuutissa. Kisassa taidettiin nähdä ennätysmäärä 200+ vetoja: kahdeksalla aloituspaino oli vähintään 200 kiloa ja yhdeksän päätti kisan yli 200 vetoon. Jälleen on mainittava Ville H:n 230 kilon 100 % RAW veto! Milloin tuo kehitys loppuukaan...?\n\n"},{"_type":"span","_key":"key-24-ttoiv","text":"Kovimmasta Wilks-vedosta (Wilks-tulos tarkoittaa siis tuloksen suhteuttamista omaan painoon) vastasi Yusif, joka veti hiukan yli 3 kertaa oman painonsa. 74,7 kilon painoisella Yusifilla oli toisessa vedossa rautaa 225, joka nousi suht kevyesti. 230 oli kuitenkin liikaa.\n\n"},{"_type":"span","_key":"key-25-6zris","text":"Kisassa on jo lähes perinteeksi muodostunut Axun yltiömäiset vetoyritykset: tällä kertaa vuorossa oli neljännestonni, joka molemmilla yrityksillä nousi maasta muutaman sentin.\n\n"},{"_type":"span","_key":"key-26-ghpfu","text":""}],"markDefs":[{"_type":"link","_key":"key-27-4e12e","href":"/_emdash/api/media/file/01KZ3GPEQY0M3YC7E8T0S0MFCJ.png"}]},{"_type":"image","_key":"key-29-jcwrf","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPEQY0M3YC7E8T0S0MFCJ.png","url":"/_emdash/api/media/file/01KZ3GPEQY0M3YC7E8T0S0MFCJ.png"},"alt":"Tunteita pelissä. Kuvassa uusi HYV:n kisaaja Eero ja rautaa miltein 3x oma paino (232,5 kg)"},{"_type":"block","_key":"key-44-ccn0q","style":"normal","children":[{"_type":"span","_key":"key-30-ie2zm","text":"Tunteita pelissä. Kuvassa uusi HYV:n kisaaja Eero ja rautaa miltein 3x oma paino (232,5 kg)"},{"_type":"span","_key":"key-31-arzlp","text":"Yhteenveto\n","marks":["strong"]},{"_type":"span","_key":"key-32-1tuep","text":"Naisten kisan vei odotetusti Veera. Hänellä yhteistulos oli 255 kiloa (Wilks 239,3). Todennäköisesti näemme häntä myös ensi kauden kisoissa. Veeralla taisi olla myös rekrytointi käynnissä, joka tietää tulevaisuudessa hyvää kilpailua naisten sarjassa.\n\n"},{"_type":"span","_key":"key-33-w9mjs","text":"Miesten sarjan vei Yusif yhteistuloksella 535 kg (Wilks 382,3). "},{"_type":"span","_key":"key-34-rbxym","text":"Toiseksi tuli Tuukka tuloksella 582,5 ("},{"_type":"span","_key":"key-35-qi59j","text":"Wilks "},{"_type":"span","_key":"key-36-kn63h","text":"375,1). Pronssi meni Ivanille, jolle tämä kisa oli toinen perättäinen, sillä mies oli viime viikonlopun kisannut SELL-Gamesissa. Lisäksi viikon päästä hänellä oli vielä kolmas kisa. Tällä kertaa YT oli 572,5 ("},{"_type":"span","_key":"key-37-3k921","text":"Wilks"},{"_type":"span","_key":"key-38-h49vj","text":" 357,5). Mainittakoon vielä, että Tuomaksen semi-RAW YT oli 642,5 kg.\n"},{"_type":"span","_key":"key-39-jaisf","text":"Lopuksi vielä tuloksia koko kaudesta. Voiton vei Tuukka. Toinen ja kolmas sija menivät Yusifille ja Jaakolle.\n\n"},{"_type":"span","_key":"key-40-eziuc","text":"Ensi kauden kisoista tulemme tekemään kyselyä jäsenille, mutta siihen palaamme myöhemmin kesällä.\n\n"},{"_type":"span","_key":"key-41-1pmzp","text":" \n\n"},{"_type":"span","_key":"key-42-4pb81","text":"Voimanostokisan tulokset:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-43-2ojvl","href":"/_emdash/api/media/file/01KZ3GPF6BSHKRP2C5D8WD64PK.jpg"}]},{"_type":"image","_key":"key-45-l0ae8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPF6BSHKRP2C5D8WD64PK.jpg","url":"/_emdash/api/media/file/01KZ3GPF6BSHKRP2C5D8WD64PK.jpg"},"alt":"Voimanostokisan tulokset"},{"_type":"block","_key":"key-50-14f1k","style":"normal","children":[{"_type":"span","_key":"key-46-7i87t","text":"\n"},{"_type":"span","_key":"key-47-c2kpe","text":" \n\n"},{"_type":"span","_key":"key-48-86e6k","text":"Voimaliigan tulokset (huom, sijoittuakseen Voimaliigassa, on kilpailijalla oltava kaudelta vähintään 3 kisasuoritusta. Näin ollen 5 ensimmäistä kisaajaa ovat \"virallisesti\" taulukossa):\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-49-h0cpo","href":"/_emdash/api/media/file/01KZ3GPG1H9JH46DJATT2PYWEY.jpg"}]},{"_type":"image","_key":"key-51-ozcwc","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPG1H9JH46DJATT2PYWEY.jpg","url":"/_emdash/api/media/file/01KZ3GPG1H9JH46DJATT2PYWEY.jpg"},"alt":"Tulokset voimaliiga"},{"_type":"block","_key":"key-71-mq0nq","style":"normal","children":[{"_type":"span","_key":"key-52-4d6hf","text":"\n"},{"_type":"span","_key":"key-53-3kgl5","text":" \n\n"},{"_type":"span","_key":"key-54-vasnf","text":"KISAVIDEOT!\n","marks":["strong"]},{"_type":"span","_key":"key-55-m1kz0","text":"Kyykky\n","marks":["strong"]},{"_type":"span","_key":"key-56-xs6s1","text":"https://www.youtube.com/watch?v=m3WwgPLllOk&feature=youtu.be\n\n"},{"_type":"span","_key":"key-57-axcqf","text":" \n\n"},{"_type":"span","_key":"key-58-wc50u","text":"Penkki\n","marks":["strong"]},{"_type":"span","_key":"key-59-cm6ku","text":"https://www.youtube.com/watch?v=r0VER_YE2eM&feature=youtu.be\n\n"},{"_type":"span","_key":"key-60-e1lf1","text":" \n\n"},{"_type":"span","_key":"key-61-zdg5u","text":"Maastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-62-oex59","text":"https://www.youtube.com/watch?v=6p6rY5mmqes&feature=youtu.be\n\n"},{"_type":"span","_key":"key-63-q0e8v","text":" \n\n"},{"_type":"span","_key":"key-64-hqhii","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-65-7tk5p","text":"Kuvat ja videot: Jaakko ja Yusif\n\n"},{"_type":"span","_key":"key-66-uu9z1","text":" \n\n"},{"_type":"span","_key":"key-67-y353h","text":" \n\n"},{"_type":"span","_key":"key-68-jzu50","text":" \n\n"},{"_type":"span","_key":"key-69-xuu5j","text":" \n\n"},{"_type":"span","_key":"key-70-faq44","text":" "}]}]' WHERE id = '01KZ3GD8PBKF4FD719F2TTBZEJ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-8-mvbxd","style":"normal","children":[{"_type":"span","_key":"key-1-ts9to","text":"Muutama viikko sitten kirjoitin Juhan onnistuneesta paluusta olkapääleikkauksen ja -kuntouksen jälkeen. Meno jatkui samanlaisena viikko sitten Lopella järjestetyssä klassisen penkkipunnerruksen kisassa (IPF), jossa taisteltiin Etelä-Suomen mestaruudesta.\n\n"},{"_type":"span","_key":"key-2-7z30r","text":"Taso oli kova, sillä vastassa oli hallitseva suomenmestari vuodelta 2016. Ja jos tuloksia katsoo, niin tiukaa teki! Juha teki kolme kovaa "},{"_type":"span","_key":"key-3-wy70m","text":"onnistunutta ","marks":["strong"]},{"_type":"span","_key":"key-4-8t18y","text":"nostoa: 150; 152,5; 155, joka on erittäin vakuuttavaa kun katsoo toista suoritusta. Mies sai hyvin psyykattua itsensä viimeiseen nostoon ja pääsi sen jälkeen jännittämään kilpakumppaninsa suoritusta samaisesta raudasta. Juhalla oli nimittäin reilu kilo enemmän lihasmassaa, joka olisi tarkoittanut tasatilanteessa (=samat raudat) toista sijaa. Hallitsevalle suomenmestarille 155 kiloa oli kuitenkin liikaa ja Juha pääsi poistumaan paikalta voittajana.\n\n"},{"_type":"span","_key":"key-5-790fs","text":"Scrollaa alemmas tuloksiin ja videoon.\n\n"},{"_type":"span","_key":"key-6-rpg4q","text":""}],"markDefs":[{"_type":"link","_key":"key-7-o7apt","href":"/_emdash/api/media/file/01KZ3GPH076V46203MPE1B8MA7.jpg"}]},{"_type":"image","_key":"key-9-1brm0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPH076V46203MPE1B8MA7.jpg","url":"/_emdash/api/media/file/01KZ3GPH076V46203MPE1B8MA7.jpg"},"alt":"Juhan mitalikaappi täydentyy jälleeen"},{"_type":"block","_key":"key-16-p7ft1","style":"normal","children":[{"_type":"span","_key":"key-10-trhj1","text":"Juhan mitalikaappi täydentyy jälleen"},{"_type":"span","_key":"key-11-rl9fj","text":"Tuloksia (klikkaa suuremmaksi):\n\n"},{"_type":"span","_key":"key-13-2e6ok","text":"https://suomenvoimanostoliitto.fi/10062017-klassinen-penkkipunnerrus-loppi-lvk-team\n","marks":["key-12-3ca8l"]},{"_type":"span","_key":"key-14-bb7oc","text":""}],"markDefs":[{"_type":"link","_key":"key-12-3ca8l","href":"https://suomenvoimanostoliitto.fi/10062017-klassinen-penkkipunnerrus-loppi-lvk-team"},{"_type":"link","_key":"key-15-664r2","href":"/_emdash/api/media/file/01KZ3GPGP408HQW2RV00SGYA3C.jpg"}]},{"_type":"image","_key":"key-17-ngwri","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPGP408HQW2RV00SGYA3C.jpg","url":"/_emdash/api/media/file/01KZ3GPGP408HQW2RV00SGYA3C.jpg"},"alt":"Tulokset"},{"_type":"block","_key":"key-20-wfr9z","style":"normal","children":[{"_type":"span","_key":"key-18-knq5y","text":"Tulokset"},{"_type":"span","_key":"key-19-kolt6","text":"Juhan nostot oheisessa videoissa:"}]},{"_type":"block","_key":"key-23-g3cot","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-21-9bhdf","text":"nosto kohdassa: "},{"_type":"span","_key":"key-22-mojk3","text":"1:03:10","marks":["strong"]}]},{"_type":"block","_key":"key-26-bltwk","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-24-csnk4","text":"nosto kohdassa: "},{"_type":"span","_key":"key-25-rvdwu","text":"1:11:20","marks":["strong"]}]},{"_type":"block","_key":"key-29-lnq94","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-27-vxfxq","text":"nosto kohdassa: "},{"_type":"span","_key":"key-28-e30cv","text":"1:21:50","marks":["strong"]}]},{"_type":"block","_key":"key-35-aa3hj","style":"normal","children":[{"_type":"span","_key":"key-30-y00r8","text":"https://www.youtube.com/watch?v=J1pvtBzh-ME\n\n"},{"_type":"span","_key":"key-31-50exn","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-32-fwgja","text":"Kuvat: Juha\n\n"},{"_type":"span","_key":"key-33-ohbyj","text":" \n\n"},{"_type":"span","_key":"key-34-rk4nu","text":" "}]}]' WHERE id = '01KZ3GD9W9G5WS4J6SHTYCCSDZ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-5-r9jc5","style":"normal","children":[{"_type":"span","_key":"key-1-grudl","text":"Juha koivisto lähestyy koko ajan lukua 150. Kyseessä ei ole kuitenkaan penkkipunnerruksessa saatu tulos, sillä se on jo saavutettu. Puhutaan siis osallistuttujen kisojen lukumäärästä vuodesta 2006 alkaen, joka oli Juhan ensimmäinen kisavuosi.\n\n"},{"_type":"span","_key":"key-2-h4u7m","text":"Vaikka viime jutusta on aikaa vain reilut pari kuukautta, on kisoja ehtinyt kertyä hurjat kahdeksan kappaletta. Sijoituksia ei tarvitse sen kummemmin alkaa listaamaan, sillä kaikki ovat numerolla yksi (tosin alla taulukko). ;) Jos katsotaan vielä päivämääriä, niin (kulta)mitaleja per (kisa)päivä -keskiarvo on aikamoinen! Tämä on selkeästi Juhan harjoittamaa kompensaatiota viime vuodesta, jolloin kisat menivät, miehen sanoja lainatakseni, \"penkin alle\".\n\n"},{"_type":"span","_key":"key-3-70a0s","text":"Juhalla on seuraavana tiedossa klassisen penkkipunnerruksen SM-kisat, jossa on mahdollisuus hankkia oikeus kilpailla samaisen lajin MM-kisoissa ensi vuonna Suomessa. Kuluneen vuoden perusteella mahdollisuudet ovat erinomaiset! Näkisimmekö miestä myös HYV:n omassa toisto- ja max-kisassa ensi vuoden alussa?\n\n"}],"markDefs":[{"_type":"link","_key":"key-4-tyxi6","href":"/_emdash/api/media/file/01KZ3GPJ2PWDP1A96EA2279YGT.jpg"}]},{"_type":"image","_key":"key-6-jz1d0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPJ2PWDP1A96EA2279YGT.jpg","url":"/_emdash/api/media/file/01KZ3GPJ2PWDP1A96EA2279YGT.jpg"},"alt":"Juhan penkki_syyskuu"},{"_type":"image","_key":"key-11-jqjwx","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPHN9WJRG7T7M68659908.png","url":"/_emdash/api/media/file/01KZ3GPHN9WJRG7T7M68659908.png"},"alt":"Yhdessä päivässä kolme kultaa on kova suoritus!"},{"_type":"block","_key":"key-15-96yge","style":"normal","children":[{"_type":"span","_key":"key-12-k7peu","text":"Yhdessä päivässä kolme kultaa on kova suoritus!"},{"_type":"span","_key":"key-13-ijc66","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-14-8ekuq","text":"Kuva: Juha"}]}]' WHERE id = '01KZ3GDAV20CW2A9HXNGS9RWQN';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-5-zd17n","style":"normal","children":[{"_type":"span","_key":"key-1-icibf","text":"Voimaliigan toinen osakilpailu järjestettiin Otahallilla lokakuun 14. päivänä. Ohjelmassa oli ensimmäistä kertaa uusi laji - Barbell Challenge Light. Kysymyksessäoli viiden eri liikesuorituksen laji (jalkakyykky, penkkipunnerrus, maastaveto, pystypunnerrus, penkkiveto). Kisapainot määririteltiin erikseen kuhunkin suoritukseen erillisen laskurin avulla.\n\n"},{"_type":"span","_key":"key-2-nny09","text":"Kisapaikalle ilmaantui kolme urhoa haastamaan toisensa: Jaakko, Tuukka ja Ivan. Kuten arvata saattoi, tiedossa oli tiukkaakin tiukempi kisa kolmen kovakuntoisen miehen välillä.\n\n"},{"_type":"span","_key":"key-3-djxjo","text":"Ensimmäiset kolme suoritusta kisailtiin tasaisissa tunnelmissa, ja hetken näytti jo siltä, että¤ kisa olisi voinut päättyä tasatulokseen. Lopulta viimeisessä kisasuorituksessa, penkkivedossa, Jaakko teki kovan suorituksen, 28 toistoa 100 s aikana.\n\n"},{"_type":"span","_key":"key-4-e8w4q","text":"Ohessa yhteistulokset:"}]},{"_type":"block","_key":"key-7-hzx4i","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-6-e5n7i","text":"Jaakko = 83 toistoa"}]},{"_type":"block","_key":"key-9-yuvkc","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-8-dn0zq","text":"Tuukka = 78 toistoa"}]},{"_type":"block","_key":"key-11-xbd8w","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-10-lg48z","text":"Ivan = 72 toistoa"}]},{"_type":"block","_key":"key-15-cnc41","style":"normal","children":[{"_type":"span","_key":"key-13-rvn9s","text":"HYV tulokset 11.2017\n","marks":["key-12-hhmyy"]}],"markDefs":[{"_type":"link","_key":"key-12-hhmyy","href":"/_emdash/api/media/file/01KZ3GPJYRAK40CK3ZG6Q263RD.pdf"},{"_type":"link","_key":"key-14-a6yk7","href":"/_emdash/api/media/file/01KZ3GPKDX219H2KC84E0FFDY9.jpg"}]},{"_type":"image","_key":"key-16-xsjvg","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPKDX219H2KC84E0FFDY9.jpg","url":"/_emdash/api/media/file/01KZ3GPKDX219H2KC84E0FFDY9.jpg"},"alt":"IMG_1127"},{"_type":"block","_key":"key-27-dbglg","style":"normal","children":[{"_type":"span","_key":"key-17-fdn94","text":"\n"},{"_type":"span","_key":"key-18-h26hu","text":"Voimaliigan pistetilanne kahden osakilpailun jälkeen:\n\n"},{"_type":"span","_key":"key-19-toxk3","text":"Ivan = 20\n\n"},{"_type":"span","_key":"key-20-khznj","text":"Tuukka = 16\n\n"},{"_type":"span","_key":"key-21-r4qln","text":"Jaakko = 12\n\n"},{"_type":"span","_key":"key-22-62tys","text":"Sampsa = 9\n\n"},{"_type":"span","_key":"key-23-upzxa","text":"Pasi = 8\n\n"},{"_type":"span","_key":"key-24-3x2ni","text":"Jyri = 6\n\n"},{"_type":"span","_key":"key-25-bd5i2","text":"https://www.youtube.com/watch?v=YfgWMIPyayw\n\n"}],"markDefs":[{"_type":"link","_key":"key-26-odrhw","href":"/_emdash/api/media/file/01KZ3GPKYFAVE003FW0ZA47VYC.jpg"}]},{"_type":"image","_key":"key-28-wysq3","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPKYFAVE003FW0ZA47VYC.jpg","url":"/_emdash/api/media/file/01KZ3GPKYFAVE003FW0ZA47VYC.jpg"},"alt":"IMG_1122"}]' WHERE id = '01KZ3GDCT1JVYMGVA5CQEAF7SV';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-14-m15e0","style":"normal","children":[{"_type":"span","_key":"key-1-70je8","text":"Otsikossa puhutaan \"taistelusta\", sillä sitä se Ivanin mukaan myös oli. Lähtöasetelmat olivat siis huonot miehen sairastellessa juuri ennen kisaa. Tämä oli osaltaan johtanut painon tippumiseen, joten mitään kikkailua vesien yms. kanssa ei tarvittu. Kisatilanne on kuitenkin aina eri ja nostoihin pystyy (ehkä hetkellisesti) psyykkaamaan pienen rähinän päälle.\n\n"},{"_type":"span","_key":"key-2-s9snf","text":"Ivan nosti siis kovatasoisessa 93-kiloisessa sarjassa Pornaisissa lyhyehkön ajomatkan päässä Espoosta. Matkaväsymyksestä ei siis onneksi tarvinnut kärsiä muiden vaivojen lisäksi. Kisassa huoltajana toimi Yusif ja valmentaja-huoltajana Sami, joita Ivan piti hyvinkin tärkeinä kisojen edetessä vikkelää tahtia.\n\n"},{"_type":"span","_key":"key-3-1t9nk","text":"Allekirjoittanut kävi nopeasti vierailemassa lämmittelyalueella ja siellä pisti silmään se, että Ivan joutui vain parin minuutin välein iskemään lisää rautaa tankoon lähestyessään aloituspainoaan. Ennen kyykyn alkamista taktikointiakin mietittiin: aloituspainon korottaminen johtaisi myöhempään nostamiseen, jolloin pääsisi palautumaan lämmittelyraudoista hiukan pidempään. Korotus olisi kuitenkin ollut liian suuri, joten ajatuksesta oli luovuttava.\n\n"},{"_type":"span","_key":"key-4-rp8jb","text":"Koska nostajat olivat jaettu kahteen pienehköön ryhmään ja lastaajat toimivat erittäin ripeästi, oli kisasuoritusten välissä melko vähän palautumisaikaa. Samaa mieltä oli myös muutkin kisaajat. Jutun lopusta löytyvästä listauksesta voitte päätellä nostojen välissä kuluneen ajan.\n\n"},{"_type":"span","_key":"key-5-g8si2","text":"Ivan teki kuitenkin tähän painoluokkaan oman ennätyksensä sivuamalla vanhoja PR-tuloksiaan, jotka oli tehty hiukan painavempana. Tulos riitti 8. sijaan. Parempaa olisi voitu odottaa, mutta toivotaan, että mies on kunnossa maaliskuun kisoissa!\n\n"},{"_type":"span","_key":"key-6-stz7c","text":"Ivanin lopputulos siis: 205 - 155 - 220 = "},{"_type":"span","_key":"key-7-m8thx","text":"580","marks":["strong"]},{"_type":"span","_key":"key-8-brm41","text":" WILKS "},{"_type":"span","_key":"key-9-djumv","text":"365,17\n","marks":["strong"]},{"_type":"span","_key":"key-11-rokrq","text":"https://suomenvoimanostoliitto.fi/8-10122017-klassinen-voimanosto-avoin-pornainen-taimi-ja-hak\n","marks":["key-10-79e2l"]},{"_type":"span","_key":"key-12-gtkua","text":""}],"markDefs":[{"_type":"link","_key":"key-10-79e2l","href":"https://suomenvoimanostoliitto.fi/8-10122017-klassinen-voimanosto-avoin-pornainen-taimi-ja-hak"},{"_type":"link","_key":"key-13-mxlfj","href":"/_emdash/api/media/file/01KZ3GPMV4JTJM9X6JK8QXFA3X.jpg"}]},{"_type":"image","_key":"key-15-694os","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPMV4JTJM9X6JK8QXFA3X.jpg","url":"/_emdash/api/media/file/01KZ3GPMV4JTJM9X6JK8QXFA3X.jpg"},"alt":"195 kg ja riittävä syvyys."},{"_type":"block","_key":"key-21-3sc7k","style":"normal","children":[{"_type":"span","_key":"key-16-t0yfl","text":"195 kg ja riittävä syvyys."},{"_type":"span","_key":"key-17-9l3ba","text":" \n\n"},{"_type":"span","_key":"key-18-5ajf2","text":" \n\n"},{"_type":"span","_key":"key-19-azlir","text":"KISASUORITUKSET\n","marks":["strong"]},{"_type":"span","_key":"key-20-wqekq","text":"Ivanin nostot oheisessa videossa:"}]},{"_type":"block","_key":"key-24-8hxh7","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-22-bojmi","text":"kyykky: "},{"_type":"span","_key":"key-23-lupib","text":"8:34:45","marks":["strong"]}]},{"_type":"block","_key":"key-27-1pr10","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-25-908wo","text":"kyykky: "},{"_type":"span","_key":"key-26-w1dmc","text":"8:40:26","marks":["strong"]}]},{"_type":"block","_key":"key-30-7uaz0","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-28-7503z","text":"kyykky: "},{"_type":"span","_key":"key-29-uhovh","text":"8.46:40","marks":["strong"]}]},{"_type":"block","_key":"key-33-5dede","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-31-i7j3r","text":"penkki: "},{"_type":"span","_key":"key-32-i4kzr","text":"9:18:44","marks":["strong"]}]},{"_type":"block","_key":"key-36-mss03","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-34-1h5xk","text":"penkki: "},{"_type":"span","_key":"key-35-ekk6y","text":"9:24:35","marks":["strong"]}]},{"_type":"block","_key":"key-39-0trr6","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-37-jj8er","text":"penkki: "},{"_type":"span","_key":"key-38-lc0u6","text":"9:28:40","marks":["strong"]}]},{"_type":"block","_key":"key-42-la0rh","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-40-ohz3w","text":"mave: "},{"_type":"span","_key":"key-41-xjq1e","text":"9:53:35","marks":["strong"]}]},{"_type":"block","_key":"key-45-hzzsn","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-43-w6a4x","text":"mave: "},{"_type":"span","_key":"key-44-7g9rf","text":"9:58:40","marks":["strong"]}]},{"_type":"block","_key":"key-48-wsbn6","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-46-t156r","text":"mave: "},{"_type":"span","_key":"key-47-mxkt7","text":"10:32:25","marks":["strong"]}]},{"_type":"block","_key":"key-53-dwyn7","style":"normal","children":[{"_type":"span","_key":"key-49-d040m","text":"https://youtu.be/KaQ2oZIFs4k\n\n"},{"_type":"span","_key":"key-50-th3pb","text":" \n\n"},{"_type":"span","_key":"key-51-c7wrm","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-52-rfxl4","text":" "}]}]' WHERE id = '01KZ3GDEZF05EA4WCQ4V1P8CJG';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-10-tfmdv","style":"normal","children":[{"_type":"span","_key":"key-1-phj90","text":"Jo vuosia tapana ollut joulukuun voimanostokisa pidettiin kovan väännön jälkeen Otahallilla. Pienen informaatiokatkon jälkeen kaikki kisaajat olivat kuitenkin enemmän tai vähemmän ajoissa ja, mikä tärkeintä, oikeassa paikassa.\n\n"},{"_type":"span","_key":"key-2-muwpb","text":"Ennen kisaa tuli valitettavan monta peruutusta. Aivan kuten edellisessä jutussa mainitsin Ivanin sairastumisesta, ei täyttä parantumista myöskään viikkoa myöhempään kisaan saatu. Ivanin lisäksi myös Axu ilmoitti kisa-aamuna flunssasta. Näin ollen emme päässeet näkemään ehkä HYV:n suurimpia mavekorotuksia. Pari muuta kisaajaa kokivat vastaavanlaisia oloja mutta eri syistä: Yusif kikkaillessaan painonsa kanssa ja kokeillessaan muokattua T-nationin \"shredded in 6 days\" -menetelmää tai allekirjoittanut lyhyiden uniensa vuoksi.\n\n"},{"_type":"span","_key":"key-3-u0k8z","text":"Tänä vuonna saimme miehiin uuden kisaajan, Jonnen, jonka taso oli tietenkin jo ennen kisaa tarkkailtu Youtubesta. Filmien perusteella saimme mukaan yhden kärkisijoista kamppailevan nostajan. Naisissa uusia kisaajia oli kaksi, Ida ja Oili, jotka haastoivat jo kisakokemusta kerryttäneen Veeran.\n\n"},{"_type":"span","_key":"key-4-xhdju","text":"Viime kisoista oppineena saimme mukaan kolme tuomaria: Sami, Reijo ja Jyri. Näin ollen huutoäänestyksiä ei jouduttu pitämään.\n\n"},{"_type":"span","_key":"key-5-lm8yn","text":"Jalkakyykky\n","marks":["strong"]},{"_type":"span","_key":"key-6-8vlpp","text":"Kyykky lähti kaikilla rutiininomaisesti käyntiin. Valitettavasti \"katsojat\" tulivat myöhässä ja kisaajat toimivat nostojensa lisäksi lastaajina. Kahdeksan kisaajan seurue oli onneksi sopivan kokoinen tällaiseen säätöön ja kisa ei venynyt totuttua pidemmäksi.\n\n"},{"_type":"span","_key":"key-7-g9a0x","text":"Miesten kovimmista kyykyistä vastasivat Jonne ja Tuukka. Molemmat kyykähtivät selkeästi syvän 210 kg (ks. kuva alla). Naisissa taas kovimman raudan, 110 kg, taisteli ylös Ida. Jutun lopusta löytyvät kisavideot, joten löydätte kaikkien kyykky- ja penkkisuoritukset sieltä. Kun katsotte kyykkyä, niin huomioikaa kuvakulma: videolla lähes kaikki kyykyt näyttävät riittävän syviltä, mutta osa niistä silti hylättiin. IPF-tuomaroinnissa on totuttava tiukkoihin tuomioihin.\n\n"},{"_type":"span","_key":"key-8-u6xar","text":""}],"markDefs":[{"_type":"link","_key":"key-9-lqztq","href":"/_emdash/api/media/file/01KZ3GPN705PFAF8BQKCVEW0CD.jpg"}]},{"_type":"image","_key":"key-11-7pque","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPN705PFAF8BQKCVEW0CD.jpg","url":"/_emdash/api/media/file/01KZ3GPN705PFAF8BQKCVEW0CD.jpg"},"alt":"Tuukan huippusyvä 210 kg. Suora kulma lisätty jälkikäteen. Kuvauskulman vuoksi ei anna kuitenkaan todellista kuvaa syvyydestä."},{"_type":"block","_key":"key-15-9em8p","style":"normal","children":[{"_type":"span","_key":"key-12-fvc3a","text":"Tuukan huippusyvä 210 kg. Suora kulma lisätty jälkikäteen. Kuvauskulman vuoksi ei anna kuitenkaan todellista kuvaa syvyydestä."},{"_type":"span","_key":"key-13-vdbuf","text":""}],"markDefs":[{"_type":"link","_key":"key-14-e0d4y","href":"/_emdash/api/media/file/01KZ3GPNJBHFDPE4356MMVEX7M.jpg"}]},{"_type":"image","_key":"key-16-atc7w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPNJBHFDPE4356MMVEX7M.jpg","url":"/_emdash/api/media/file/01KZ3GPNJBHFDPE4356MMVEX7M.jpg"},"alt":"Nostojen välissä psyykkailtiin kukin omalla tavallaan. Veera ja Ida saivat hymyilystä huolimatta kovia suorituksia aikaiseksi. Kuva: Anniliina Lassila"},{"_type":"block","_key":"key-33-0zaeo","style":"normal","children":[{"_type":"span","_key":"key-17-nqlap","text":"Nostojen välissä psyykkailtiin kukin omalla tavallaan. Veera ja Ida saivat hymyilystä huolimatta kovia suorituksia aikaiseksi. Kuva: Anniliina Lassila"},{"_type":"span","_key":"key-18-e3rsu","text":"Penkkipunnerrus\n","marks":["strong"]},{"_type":"span","_key":"key-19-bbzrh","text":"Ennen penkkipunnerruksen alkua katsoja-toimitsijoita oli päässyt paikalle jo jonkin verran. Kluuvin sanansaattaja Leo vastasi viihdyttämisestä hämmentäessään kilpailijoita omalla tavallaan. Hyvä niitä kisaajien henkistä puoltakin on testattava. ;)\n\n"},{"_type":"span","_key":"key-20-4xkqu","text":"Päätuomarin vaihduttua toukokuun kisasta, ottivat kisaajat vallan valitessaan kisapenkkiä ja -tankoa. Näin ollen lopputulemana oli \"epävirallinen\" tanko, josta kuitenkin tehtiin virallinen vain tarkkailemalla oteleveyksiä normaalia tarkemmin. Ehkä se selittää erityisen kovat tulokset...\n\n"},{"_type":"span","_key":"key-21-241j3","text":"Naisissa energiaa riitti myös neljänsiin nostoihin: Veera ja Ida halusivat ottaa harmittavasti epäonnistuneet kolmannet nostonsa uusiksi. Molemmat onnistuivat, mutta näitä nostoja ei kuitenkaan rekisteröidä virallisiin tuloksiin vaan (vähintään) nostajien omiin mieliin, jotta ne muistetaan rikkoa sitten seuraavissa kisoissa.\n\n"},{"_type":"span","_key":"key-22-fs0gy","text":"Miehissä Ivan ilmeisesti rekrysi itselleen uhkaavan penkkaajan: Jonnen 155 kg nosto oli yksi kovimpia HYV:n voimanostokisoissa nähtyjä. Paketti pysyi tiukkana noston loppuun asti johtaen pienehköön selkäkramppiin mukavasti ennen maastanostoa...\n\n"},{"_type":"span","_key":"key-23-qg45q","text":"Maastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-24-f3v9r","text":"Kisa jatkui tiukkana maastanostoon asti. Miehissä selkeä top 3 oli painojärjestykssä Yusif, Tuukka ja Jonne. Naisissa Ida oli karannut vahvan penkkinsä (ja toki kyykkynsäkin) siivittämänä hyvään johtoon. 155 kg veto näytti niin kevyeltä, että joko Push&Pull- tai toukokuun voimanostokisassa HYV:n naisten ennätystä tullaan vähintään sivuamaan (Katariina P:llä nykyinen ennätys 160 kg).\n\n"}],"markDefs":[{"_type":"link","_key":"key-32-iqxe9","href":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg"}]},{"_type":"htmlBlock","_key":"key-33-0zaeo-video-1","html":"<video controls preload=\"metadata\" src=\"/_emdash/api/media/file/01KZ3GPPAGBT6P8VAEYD42QSS1.mp4\"></video>"},{"_type":"block","_key":"key-33-0zaeo","style":"normal","children":[{"_type":"span","_key":"key-26-gby6q","text":"Ida ja 155 kg, joka lähentelee HYV:n naisten ennätystä. (Sala)kuvaajana Leo\n","marks":["em"]},{"_type":"span","_key":"key-27-gqp5n","text":"Tällä kertaa suurimmat mave-raudat jäivät 240 kiloon. Kyykyn tavoin näistä vastasivat jälleen Tuukka ja Jonne ja molemmilla näytti olevan vielä potentiaalia neljänsiin nostoihin. Yusif taas hoiti hoikimpana mies-kisaajana kovimman WILKS-tuloksen ja vei kisan voiton. Vielä kuitenkin alle 400 WILKS, joten tavoiteltavaa rittää. ;)\n\n"},{"_type":"span","_key":"key-28-jw08c","text":"Ida keräsi jokaisessa laijssa voiton ja näin ollen poistui paikalta voittajana. Tulos oli sellaista tasoa, että sillä kehtaisi jo suunnata kansallisiin kisoihin. Toiseksi tuli Veera ja kolmanneksi debyyttinsä tehnyt Oili.\n\n"},{"_type":"span","_key":"key-29-h1l4r","text":"Sokerina pohjalla Villen 100 % RAW (no belt, no straps, no wraps, no mirror) mave.\n\n"},{"_type":"span","_key":"key-30-3ktms","text":"https://www.instagram.com/p/Bcx6UfQg6yM/\n\n"},{"_type":"span","_key":"key-31-z6fko","text":""}],"markDefs":[{"_type":"link","_key":"key-32-iqxe9","href":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg"}]},{"_type":"image","_key":"key-34-y2v2w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg","url":"/_emdash/api/media/file/01KZ3GPRK9ZPJ1S97K61AANSBB.jpg"},"alt":"Voittajan tehtävä on olla yläosattomissa ;)"},{"_type":"block","_key":"key-39-7tp2r","style":"normal","children":[{"_type":"span","_key":"key-35-m1alf","text":"Voittajan tehtävä on olla yläosattomissa ;)"},{"_type":"span","_key":"key-36-l90uc","text":" \n\n"},{"_type":"span","_key":"key-37-ngxke","text":"Tuloksia ja kauden tilanne alla.\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-ggvox","href":"/_emdash/api/media/file/01KZ3GPQ49KPERMXWWRQ3F5S6T.jpg"}]},{"_type":"image","_key":"key-40-9ibfa","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQ49KPERMXWWRQ3F5S6T.jpg","url":"/_emdash/api/media/file/01KZ3GPQ49KPERMXWWRQ3F5S6T.jpg"},"alt":"Tulokset HYV 2017 joulu"},{"_type":"block","_key":"key-44-6ufwr","style":"normal","children":[{"_type":"span","_key":"key-41-3i45n","text":"\n"},{"_type":"span","_key":"key-42-d5s0u","text":"Alla lajikohtaiset tulokset\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-43-z5uls","href":"/_emdash/api/media/file/01KZ3GPR87JQ6X3SQRW5DZJX4J.jpg"}]},{"_type":"image","_key":"key-45-4s16w","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPR87JQ6X3SQRW5DZJX4J.jpg","url":"/_emdash/api/media/file/01KZ3GPR87JQ6X3SQRW5DZJX4J.jpg"},"alt":"Nostot"},{"_type":"block","_key":"key-49-1gyye","style":"normal","children":[{"_type":"span","_key":"key-46-93nan","text":"\n"},{"_type":"span","_key":"key-47-dfyw7","text":"Kauden pistetilanne\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-48-qqp98","href":"/_emdash/api/media/file/01KZ3GPQEJH7440W3KANV3EWN6.jpg"}]},{"_type":"image","_key":"key-50-4pit9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQEJH7440W3KANV3EWN6.jpg","url":"/_emdash/api/media/file/01KZ3GPQEJH7440W3KANV3EWN6.jpg"},"alt":"Pistetilanne naiset"},{"_type":"image","_key":"key-53-mr8kz","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPQRV4EQ0T3B7H730P252.jpg","url":"/_emdash/api/media/file/01KZ3GPQRV4EQ0T3B7H730P252.jpg"},"alt":"Pistetilanne miehet"},{"_type":"block","_key":"key-63-saj2e","style":"normal","children":[{"_type":"span","_key":"key-54-e2plo","text":"\n"},{"_type":"span","_key":"key-55-c3eah","text":"Kisavideot\n","marks":["strong"]},{"_type":"span","_key":"key-56-zdk6k","text":"https://www.youtube.com/watch?v=SdK5qXcpr0o&feature=youtu.be\n\n"},{"_type":"span","_key":"key-57-dszol","text":" \n\n"},{"_type":"span","_key":"key-58-cii1b","text":"https://www.youtube.com/watch?v=NqTP3bYFMQ4&feature=youtu.be\n\n"},{"_type":"span","_key":"key-59-ahbxa","text":"Juttua päivitetty 25.12.2017 klo 20:47: Idan maastanosto ei sivunnut nykyistä HYV:n naisten ennätystä.\n","marks":["em"]},{"_type":"span","_key":"key-60-rrv9k","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-61-uz4o2","text":"Kuvat: Anniliina Lassila ja Jyri\n\n"},{"_type":"span","_key":"key-62-vzy47","text":"Videot: Leo ja Yusif"}]}]' WHERE id = '01KZ3GDFYFNCZ4Z9SFHNEPZ75X';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-6-epxpc","style":"normal","children":[{"_type":"span","_key":"key-1-u4ite","text":"Vuosi 2018 startattiin penkkikisalla. Valitettavasti juttu jää nyt lyhyeksi, sillä reporttereita ei ollut paikalla.\n\n"},{"_type":"span","_key":"key-2-1uy1o","text":"Onneksenne kaikki suoritukset kisasta ovat videolla, joten raati voi antaa omat pisteensä. Kiitokset Yusifille jälleen kuvauksesta. Asiantuntijan kommentit jäivät tällä kertaa (pyynnöstä huolimatta) pois.\n\n"},{"_type":"span","_key":"key-3-shtb8","text":"Tulokset ja videot alla:\n\n"},{"_type":"span","_key":"key-4-t3i51","text":"MAKSIMI\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-5-vey38","href":"/_emdash/api/media/file/01KZ3GPS0VZMJF46Q7ZS7K994J.jpg"}]},{"_type":"image","_key":"key-7-zkh77","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPS0VZMJF46Q7ZS7K994J.jpg","url":"/_emdash/api/media/file/01KZ3GPS0VZMJF46Q7ZS7K994J.jpg"},"alt":""},{"_type":"block","_key":"key-12-8nc3g","style":"normal","children":[{"_type":"span","_key":"key-8-unels","text":"\n"},{"_type":"span","_key":"key-9-cyr86","text":" \n\n"},{"_type":"span","_key":"key-10-0lwny","text":"TOISTOKISA\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-11-55sni","href":"/_emdash/api/media/file/01KZ3GPSB8CVJCGSMK5HZG8V54.jpg"}]},{"_type":"image","_key":"key-13-wx8ba","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPSB8CVJCGSMK5HZG8V54.jpg","url":"/_emdash/api/media/file/01KZ3GPSB8CVJCGSMK5HZG8V54.jpg"},"alt":""},{"_type":"block","_key":"key-24-bti10","style":"normal","children":[{"_type":"span","_key":"key-14-zy4vo","text":"\n"},{"_type":"span","_key":"key-15-0xbhn","text":" \n\n"},{"_type":"span","_key":"key-16-v9sbl","text":"VIDEOLINKIT\n","marks":["strong"]},{"_type":"span","_key":"key-17-dxgh8","text":"https://www.youtube.com/watch?v=hKstoVw_pHo&feature=youtu.be\n\n"},{"_type":"span","_key":"key-18-po75g","text":" \n\n"},{"_type":"span","_key":"key-19-51w0c","text":" \n\n"},{"_type":"span","_key":"key-20-24pdp","text":"https://www.youtube.com/watch?v=qkYXOhXrjLQ&feature=youtu.be\n\n"},{"_type":"span","_key":"key-21-ikc9f","text":" \n\n"},{"_type":"span","_key":"key-22-k998h","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-23-jnw3b","text":"Videot: Yusif"}]}]' WHERE id = '01KZ3GDH4XQRZQN9R1ZF7MXSAA';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-4-ejmay","style":"normal","children":[{"_type":"span","_key":"key-1-ebxms","text":"Edellisessä jutussa (HYV:n oma penkkikisa) ei mainittu Juhan nimeä, vaikka miestä pyydettiin mukaan kisaamaan. Syynä oli valmistautuminen SM-kisoihin, jossa jaettiin paikkoja MM-kisoihin Vantaalle 14.-19. toukokuuta. Onneksi sentään toinen kova penkkimies Esa pääsi paikalle vieden kisan reilulla marginaalilla.\n\n"},{"_type":"span","_key":"key-2-aq2x5","text":""}],"markDefs":[{"_type":"link","_key":"key-3-rz82g","href":"/_emdash/api/media/file/01KZ3GMS7GJ9VHYYXB9V3W2DM0.jpg"}]},{"_type":"image","_key":"key-5-23ho1","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMS7GJ9VHYYXB9V3W2DM0.jpg","url":"/_emdash/api/media/file/01KZ3GMS7GJ9VHYYXB9V3W2DM0.jpg"},"alt":""},{"_type":"block","_key":"key-14-nmwwi","style":"normal","children":[{"_type":"span","_key":"key-6-q9dtb","text":"Esa ja Juha. Mitalit ja pokaalit ovat olleet arkipäivää näille kahdelle. HUOM! Kuva parin vuoden takaa."},{"_type":"span","_key":"key-7-ta3p0","text":"Vaikka Juha kärsi influenssasta juuri kisaviikolla ja vain ensimmäinen nosto, 152,5 kg, saatiin ylös, oli kuitenkin kisapaikka varmistettu SM-kisojen parhaiden WILKSien perusteella. Sijoitus tässä kisassa oli kuitenkin toinen.\n\n"},{"_type":"span","_key":"key-8-4dc1j","text":"Tämä on harvinaista herkkua kun HYV:ltä lähtee edustaja MM-kisoihin! Tästä seuraa juttua myöhemmin keväällä.\n\n"},{"_type":"span","_key":"key-9-a54ft","text":"Ao. linkissä näkyy osallistujalista. Juhan sarja Master 3, -93 kg.\n\n"},{"_type":"span","_key":"key-11-605ye","text":"http://goodlift.info/onenomination.php?cid=440\n","marks":["key-10-w5qzh"]},{"_type":"span","_key":"key-12-jn3ek","text":" \n\n"},{"_type":"span","_key":"key-13-7z2oz","text":"Nostot ao. videolla:"}],"markDefs":[{"_type":"link","_key":"key-10-w5qzh","href":"http://goodlift.info/onenomination.php?cid=440"}]},{"_type":"block","_key":"key-16-bhd0b","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-15-6hwb7","text":"Nosto 2:21:46"}]},{"_type":"block","_key":"key-18-4olxf","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-17-n8xer","text":"Nosto 2:29:43"}]},{"_type":"block","_key":"key-20-kdjx9","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-19-ryyz3","text":"Nosto 2:41:06"}]},{"_type":"block","_key":"key-25-dyllv","style":"normal","children":[{"_type":"span","_key":"key-21-1w043","text":"https://youtu.be/Qb8TZafx15o?t=8503\n\n"},{"_type":"span","_key":"key-22-h67d8","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-23-w5h53","text":" \n\n"},{"_type":"span","_key":"key-24-elsfw","text":" "}]}]' WHERE id = '01KZ3GDJ8YEQQ7KDF7X7NS6JNF';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-19-mds4s","style":"normal","children":[{"_type":"span","_key":"key-1-978pi","text":"Otahallissa kisattiin lauantaina 23.3.2018 erittäin kovatasoinen mittelö Voimaliigassa ensimmäistä kertaa järjestetyssä Push&Pull- kilpailussa. Osanotto oli kiitettävän runsas osallistujamäärän ollessa seitsemän.\n\n"},{"_type":"span","_key":"key-2-t6bwr","text":"Kisa aloitettiin penkkipunnerruksella. Ville ja Tuukka työnsivät molemmat rutiininomaisesti 140 kg. Petri teki vakuuttavaa paluuta kisalavoille 137,5 kg:n tuloksella. Yusif työnsi aloituspainonsa 130 kg ja jätti kaksi seuravaa yritystä väliin. Tällä tuloksella Yusif otti wilks-pisteissä selkeän johdon ennen maastavetoa.\n\n"},{"_type":"span","_key":"key-3-u0r97","text":"Maastaveto oli lauantaina kevyttä. Otahalli antoi henkilökohtaisia ennätyksiä lähes jokaiselle kilpailijalle. Voi hyvin sanoa, että kyseessä oli Voimaliigan historian kovatasoisin maastaveto-kilpailu.\n\n"},{"_type":"span","_key":"key-4-wm5xx","text":"Tuukka laittoi viimeisellä yrityksellä tankoon 250 kg ja otti sen varmasti ylös. Ville veti viimeisellään erittäin tyylikkään 240 kg. Petri otti todella kevyesti kolmannellaan 230 kg (ja otti kilpailun ulkopuolella vielä 235 kg).  Uusi tulokas Miikka nosti 220 kg, joka oli tasatulos Maxin kanssa. Simo veti kolmannellaan helpohkon näköisesti 180 kg ja kisan ulkopuolella 190 kg. Ilmeisesti paukkuja oli vielä. Simon voima- ja henkisen puolen valmennuksesta vastaa nykyään Yusif.\n\n"},{"_type":"span","_key":"key-5-xvrha","text":"Myös maastavedossa Yusif tyytyi aloituspainoon, joka tällä kertaa oli 225 kg. Nosto oli helppo ja sillä Yusif sinetöi wilks-pisteissä myös maastavedon ja samalla myös kokonaiskilpailun voiton.\n\n"},{"_type":"span","_key":"key-6-uhzpl","text":"Yusifille onnittelut kilpailun voitosta! Ja onnittelut kaikille uusien ennätysten nostaneille!\n\n"},{"_type":"span","_key":"key-7-idx6l","text":"1. Yusif    (73,5 kg)            130+225=355 kg / 256,59 wilks-pistettä\n"},{"_type":"span","_key":"key-8-hjl2i","text":"2. Tuukka (91,0 kg)            140+250=390 kg / 247,61\n"},{"_type":"span","_key":"key-9-qvf7v","text":"3. Ville      (89,7 kg)            140+240=380 kg / 243,01\n"},{"_type":"span","_key":"key-10-riio6","text":"4. Petri      (92,8 kg)           137,5+230=367,5 kg / 231,08\n"},{"_type":"span","_key":"key-11-ojzfz","text":"5. Miikka   (83,2 kg)           120+220=340 kg / 226,64\n"},{"_type":"span","_key":"key-12-f174b","text":"6. Max       (86,4 kg)           120+220=340 kg / 221,78\n"},{"_type":"span","_key":"key-13-f55q3","text":"7. Simo       (80,9 kg)          105+180=285 kg / 193,20\n\n"},{"_type":"span","_key":"key-14-n9a5a","text":"ALLA PISTETILANNE JA KISAVIDEOT\n","marks":["strong"]},{"_type":"span","_key":"key-15-0srk8","text":"Tuukka ja Yusif ovat tasapisteissä kun kolme kilpailua on vielä jäljellä: Leuanveto max, leuanveto toisto ja voimanosto.\n\n"},{"_type":"span","_key":"key-16-fdwkz","text":"Kuka saakaan nimensä pokaaliin? ;)  Tuukka on ollut hyvin vahva leuoissa, mutta Yusif taas handlaa voimanoston. Jos Yusif mielii saada nimensä pokaaliin, on hänen osallistuttava leuanvetoon, sillä Tuukka tuskin jättää sitä väliin.\n\n"},{"_type":"span","_key":"key-17-hoyo4","text":"Naisten osalta Ida on ylivoimaisessa johdossa!\n\n"}],"markDefs":[{"_type":"link","_key":"key-18-e5b1f","href":"/_emdash/api/media/file/01KZ3GPTTMMJHNZ10HHD5BDR23.jpg"}]},{"_type":"image","_key":"key-20-4a4a0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPTTMMJHNZ10HHD5BDR23.jpg","url":"/_emdash/api/media/file/01KZ3GPTTMMJHNZ10HHD5BDR23.jpg"},"alt":""},{"_type":"image","_key":"key-23-fjv0m","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPV3FJVT6AKHBK79WGMHE.jpg","url":"/_emdash/api/media/file/01KZ3GPV3FJVT6AKHBK79WGMHE.jpg"},"alt":""},{"_type":"block","_key":"key-32-ovbr1","style":"normal","children":[{"_type":"span","_key":"key-24-zwdj9","text":"\n"},{"_type":"span","_key":"key-25-9j594","text":"Alla muokattu video. Lopusta löytyy raakamateriaali.\n\n"},{"_type":"span","_key":"key-26-054ta","text":"https://www.youtube.com/watch?v=2thuK6LxBJI&feature=youtu.be\n\n"},{"_type":"span","_key":"key-27-51ror","text":" \n\n"},{"_type":"span","_key":"key-28-xwinj","text":"https://www.youtube.com/watch?v=uwXR-rz731c&feature=youtu.be\n\n"},{"_type":"span","_key":"key-29-eru2y","text":"https://www.youtube.com/watch?v=S-zrgrryQR8&feature=youtu.be\n\n"},{"_type":"span","_key":"key-30-2c38f","text":" \n\n"}],"markDefs":[{"_type":"link","_key":"key-31-gpbhj","href":"/_emdash/api/media/file/01KZ3GPSN9NBSECNGY0MV5PMFE.jpg"}]},{"_type":"image","_key":"key-33-cultj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPSN9NBSECNGY0MV5PMFE.jpg","url":"/_emdash/api/media/file/01KZ3GPSN9NBSECNGY0MV5PMFE.jpg"},"alt":""},{"_type":"block","_key":"key-36-n2vyn","style":"normal","children":[{"_type":"span","_key":"key-34-6g1v9","text":"\n"},{"_type":"span","_key":"key-35-f1gls","text":"Teksti: Sampsa ja Jaakko"}]}]' WHERE id = '01KZ3GDK7EXDJRMFJN56X7K1MT';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-16-b5omb","style":"normal","children":[{"_type":"span","_key":"key-1-pa9tv","text":"Kyseessä siis toiseksi viimeinen osakilpailu eli leuanveto Meilahden liikuntakeskuksessa. Paikalla oli niin paljon hurjia nimiä, että jopa kolme aiemmin (suullisesti) ilmottautunutta jätti tulematta paikalle.\n\n"},{"_type":"span","_key":"key-2-maf7j","text":"Kisapäivä koostui kahdesta osakilpailusta: ensimmäiseksi lisäpainoleuanveto ja tämän jälkeen toistomaksimi. Mainittakoon, että lisäpainojen jälkeen toistoja ei välttämättä tule niin paljon ;)\n\n"},{"_type":"span","_key":"key-3-8fbj8","text":"Paikalle pääsi siis kuusi kilpailijaa: Jaakko, Petri, Yusif, Jonne, Miikka ja Tuukka. "},{"_type":"span","_key":"key-4-lj8zq","text":"Tuleva HYV:n jäsen","marks":["em"]},{"_type":"span","_key":"key-5-3runn","text":" Valtteri toimi kisassa puoleettomana tuomarina. Lisäksi käytössä oli videokamera, jota käytettiin pääosin lisäpainoleuanvedon mahdollisiin tarkistuksiin. Kisapätkä löytyy tämän jutun lopusta.\n\n"},{"_type":"span","_key":"key-6-2octw","text":"LISÄPAINO-OSUUS\n","marks":["strong"]},{"_type":"span","_key":"key-7-rvibv","text":"Koska kisaajia oli sen verran vähän, ei painoluokkia ollut. Siksi oli mietittävä kuinka lopputulos laskettaisiin. Ehdotettiin muutamaa tapaa: lisäpaino + oma paino, pelkkä lisäpaino tai lisäpaino + oma paino WILKS-kertoimella. Lopulta \"päädyttiin\" edellä olevan listan ensimmäiseen vaihtoehtoon. Kenties ensi vuonna asiaa pohditaan muutaman viikon sijasta muutama kuukausi ja saadaan paljon parempi ja monimutkaisempi laskentatapa.\n\n"},{"_type":"span","_key":"key-8-vzb1k","text":"Yrityksiä oli yhteensä kolme kappaletta. Osa kuitenkin otti neljännen vedon kisa ulkopuolella: Tuukalla se oli 64 kg, Jonnella 50 kg ja Miikalla hurjat 70,5 kg. Petri vie kuitenkin voiton vetäessään suurimman lisäpainon 65,5 kg ja ollessaan lisäksi painavin kisaaja. Lopputulokset löytyvät jutun lopusta.\n\n"},{"_type":"span","_key":"key-9-2d03d","text":"TOISTOKISA\n","marks":["strong"]},{"_type":"span","_key":"key-10-kt899","text":"Toistokisassa videotarkastelu osoitti, että osa toistoista olisi pitänyt hylätä. Tuomarina toimiva "},{"_type":"span","_key":"key-11-5gdhu","text":"Tuleva HYV:n jäsen","marks":["em"]},{"_type":"span","_key":"key-12-x87jx","text":" Valtteri ei kuitenkaan huomattanut kisaajaa, joten reiluuden nimissä kaikki toistot, joihin ei tullut kommenttia, hyväksyttiin. Tämä ei välttämättä toteunut Tuukan kohdalla, mutta lopputulokseen sillä ei olisi ollut vaikutusta. Tuukka ei myöskään pahoittanut mieltänsä, joten syrjintää ei tapahtunut. Kisan vei viime vuoden tapaa allekirjoittanut 28 toistolla. Toiseksi tuli Petri 24 toistolla. Yusif antoi, kuten lisäpainoleuanveto-osuudessa, tasoitusta vetämällä koko suorituksen myötäotteella \"without biceps\". Mitä lie tarkoittaakaan...\n\n"},{"_type":"span","_key":"key-13-rqo5r","text":"Pistetilanne on edelleen jännittävä: Tuukka johtaa 55 pisteellä, Yusif on toisena vain kolme pistettä jäljessä. Petri on kirinyt keväällä ja on nyt kolmantena. Jaakko on neljäntenä.\n\n"},{"_type":"span","_key":"key-14-u133h","text":""}],"markDefs":[{"_type":"link","_key":"key-15-1osd2","href":"/_emdash/api/media/file/01KZ3GPVCFE7SHAT8HS0PXKGSB.jpeg"}]},{"_type":"image","_key":"key-17-93bh0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPVCFE7SHAT8HS0PXKGSB.jpeg","url":"/_emdash/api/media/file/01KZ3GPVCFE7SHAT8HS0PXKGSB.jpeg"},"alt":""},{"_type":"block","_key":"key-22-suvs0","style":"normal","children":[{"_type":"span","_key":"key-18-mh5l5","text":"Vasemmalta: Tuleva HYV:n jäsen Valtteri, Tuukka, Jaakko, Jonne, Yusif ja Miikka"},{"_type":"span","_key":"key-19-2n5nm","text":" \n\n"},{"_type":"span","_key":"key-20-d5jzx","text":""}],"markDefs":[{"_type":"link","_key":"key-21-pfq5n","href":"/_emdash/api/media/file/01KZ3GPVSBZFGQ2FDF6RKR50D3.jpg"}]},{"_type":"image","_key":"key-23-k1z5v","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPVSBZFGQ2FDF6RKR50D3.jpg","url":"/_emdash/api/media/file/01KZ3GPVSBZFGQ2FDF6RKR50D3.jpg"},"alt":""},{"_type":"block","_key":"key-27-71dl1","style":"normal","children":[{"_type":"span","_key":"key-24-evi7v","text":"Kisan tulokset"},{"_type":"span","_key":"key-25-8ys4o","text":""}],"markDefs":[{"_type":"link","_key":"key-26-89fpu","href":"/_emdash/api/media/file/01KZ3GPW316Z69Z869EK717RGC.jpg"}]},{"_type":"image","_key":"key-28-mbbsf","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPW316Z69Z869EK717RGC.jpg","url":"/_emdash/api/media/file/01KZ3GPW316Z69Z869EK717RGC.jpg"},"alt":""},{"_type":"block","_key":"key-35-c8b7z","style":"normal","children":[{"_type":"span","_key":"key-29-2jyd3","text":"Miesten pistetilanne leuanvetokisan jälkeen. Naisten tilanteeseen ei ole tullut muutoksia."},{"_type":"span","_key":"key-30-tl9yp","text":" \n\n"},{"_type":"span","_key":"key-31-4w24k","text":"https://www.youtube.com/watch?v=WjDUSOHr1Rs&feature=youtu.be\n\n"},{"_type":"span","_key":"key-32-im873","text":" \n\n"},{"_type":"span","_key":"key-33-85csr","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-34-rsawp","text":"Video ja kuva: Yusif."}]}]' WHERE id = '01KZ3GDMC28F2A7SA5R494X1SE';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-gnppx","style":"normal","children":[{"_type":"span","_key":"key-1-lgrst","text":"Viimeksi saimme lukea hiukan penkin alle menneistä kisoista, joista kuitenkin irtosi matkalippu Vantaalla toukokuussa pidettyihin MM-kisoihin. Näin ollen matkustamiseen ei tarvinnut käyttää nippukaupalla tunteja.\n\n"},{"_type":"span","_key":"key-2-8byqr","text":"Juha kisasi tutussa sarjassa eli master 3-sarjassa alle 93 kiloissa. Pahin kilpailija Juhalla oli Ilkka Launonen, jonka aloituspaino oli myös 155. Tiukkaa taistelua oli siis tiedossa.\n\n"},{"_type":"span","_key":"key-3-wcp8s","text":"Kisa sisälsi myös draamaa yhden tuomareista säätäessä juomapullonsa kanssa juuri Juhan toisen noston alkaessa. Tämä vei mieheltä keskittymisen ja ehkä hitusen voimaakin, sillä paino oli käsillä, mutta oli palautettava takaisin telineisiin päätuomarin huomatessa, että kaikki ei ollut valmista. Tämän vuoksi toinen (160 kilon) nosto meni 2-1 hylkyyn.\n\n"},{"_type":"span","_key":"key-4-87ccv","text":"Olen varmastikin aikaisemmin maininnut Juhan erinomaisesta palautumiskyvyistä nostojen välillä. Tämä kullanarvokas kyky tuli jälleen hyödylliseksi ja 3. yritys 160 kilolla onnistui. Samalla painavampi kilpakumppani Ilkka epäonnistui 162,5 kilosta ja Juhan voitto oli sinetöity!\n\n"},{"_type":"span","_key":"key-5-uivve","text":"Tämä on varmastikin yksi kovimmista HYV:n historian suorituksista!\n\n"},{"_type":"span","_key":"key-6-bwjab","text":"ONNITTELUT VIELÄ KERRAN!\n\n"},{"_type":"span","_key":"key-7-08sg4","text":"Alla video, nostot 57:20; 1:12:30; 1:25:30.\n\n"},{"_type":"span","_key":"key-8-4vm4k","text":"https://www.youtube.com/watch?v=EknodTegaeU\n\n"},{"_type":"span","_key":"key-9-i3wni","text":" \n\n"}],"markDefs":[{"_type":"link","_key":"key-10-09czq","href":"/_emdash/api/media/file/01KZ3GPYG453DQ5P9R8R5EXJGP.jpg"}]},{"_type":"image","_key":"key-12-ax1an","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPYG453DQ5P9R8R5EXJGP.jpg","url":"/_emdash/api/media/file/01KZ3GPYG453DQ5P9R8R5EXJGP.jpg"},"alt":""},{"_type":"image","_key":"key-15-awero","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPX79XV39VW2HA800ED7D.jpg","url":"/_emdash/api/media/file/01KZ3GPX79XV39VW2HA800ED7D.jpg"},"alt":""},{"_type":"block","_key":"key-22-llhif","style":"normal","children":[{"_type":"span","_key":"key-16-npxzv","text":"\n"},{"_type":"span","_key":"key-17-qpdxm","text":" \n\n"},{"_type":"span","_key":"key-18-eiy0o","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-19-a1eil","text":"Video: Suomen Voimanostoliitto\n\n"},{"_type":"span","_key":"key-20-1h4ma","text":"Kuvat: Juha Koivisto\n\n"},{"_type":"span","_key":"key-21-wziao","text":" "}]}]' WHERE id = '01KZ3GDPACRR7H678GBCRWDPG6';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-g6l3v","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ0RR34VEMB1ZSKMNNK71.jpg","url":"/_emdash/api/media/file/01KZ3GQ0RR34VEMB1ZSKMNNK71.jpg"},"alt":""},{"_type":"block","_key":"key-13-4virx","style":"normal","children":[{"_type":"span","_key":"key-5-ozmji","text":"Naama peruslukemilla."},{"_type":"span","_key":"key-6-r3kp4","text":"Sää oli siis lämmin kuten naamoista näkee...\n\n"},{"_type":"span","_key":"key-7-hayld","text":"Sitten asiaan: liigan päätös kisattiin toukokuun viimeisenä viikonloppuna odotettua vähäisemmällä osanottajamäärällä. Tunnetusti se ei HYV:n väkeä lannista ja meininkiä oli kuten oletimme.\n\n"},{"_type":"span","_key":"key-8-br8i7","text":"Osallistujia oli siis yhteensä \"vain\" 5, yksi (1)  nainen (Veera) ja neljä (4) miestä (Max, Jaakko, Pete ja Simo). Kisan tahti oli siis nopea ilman tuomareiden hoputustakin ;)\n\n"},{"_type":"span","_key":"key-9-5pl4j","text":"Pistetilanne oli suhteelisen jännittävä ennen päätöskisaa, mutta koska kumpikaan kautta johtavista kilpailijoista (Yusif tai Tuukka) eivät osallistuneet kisaan, oli Tuukka varmistanut voiton. Kolmannesta sijasta taistelivat nyt siis allekirjoittanut (Jaakko) ja Pete, joilla oli eroa 3 pistettä Peten hyväksi. Näin vähäisellä osanottajamäärällä se vaatisi Jaakolle voiton.\n\n"},{"_type":"span","_key":"key-10-hs4vm","text":"Naisten osalta Ida oli varmistanut voiton jo huhtikuussa, sillä yhtään naista ei ollut mukana leuanvedossa.\n\n"},{"_type":"span","_key":"key-11-6w0zs","text":"Lajeista ei sen ihmeempää kommenttia ole, vaan kaikki ovat tunnetusti videolla. Iso kiitos siitä erkkijaakkojetterille! Kameran kaatumista mavessa ei kannata säikähtää, sillä se nousee melko pian pystyyn. Sen verran täytyy kuitenkin sanoa, että maastanosto on ehkä näistä kolmesta viihdyttävin pätkä :)\n\n"}],"markDefs":[{"_type":"link","_key":"key-12-3kyl9","href":"/_emdash/api/media/file/01KZ3GQ1J6PEX8B6VFXPXM184G.jpeg"}]},{"_type":"image","_key":"key-14-snh1y","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ1J6PEX8B6VFXPXM184G.jpeg","url":"/_emdash/api/media/file/01KZ3GQ1J6PEX8B6VFXPXM184G.jpeg"},"alt":""},{"_type":"block","_key":"key-24-e1mv0","style":"normal","children":[{"_type":"span","_key":"key-15-ftc6g","text":"\n"},{"_type":"span","_key":"key-16-uorlc","text":"VIDEOT ALLA ENSIN (jotta tulokset pysyvät mysteerinä), TULOKSET LOPUSSA.\n\n"},{"_type":"span","_key":"key-17-nt42e","text":"https://www.youtube.com/watch?v=flYzGasShwg&feature=youtu.be\n\n"},{"_type":"span","_key":"key-18-a0bmw","text":" \n\n"},{"_type":"span","_key":"key-19-ghgkg","text":"https://www.youtube.com/watch?v=yL5gCBBThmg&feature=youtu.be\n\n"},{"_type":"span","_key":"key-20-63gzi","text":"https://www.youtube.com/watch?v=UgDdgKFiHpg&feature=youtu.be\n\n"},{"_type":"span","_key":"key-21-3lu4w","text":" \n\n"},{"_type":"span","_key":"key-22-ft9vx","text":"Kisan tulokset:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-23-v3k2q","href":"/_emdash/api/media/file/01KZ3GPZ9M9C5F803B1XM3792N.jpg"}]},{"_type":"image","_key":"key-25-aevc4","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPZ9M9C5F803B1XM3792N.jpg","url":"/_emdash/api/media/file/01KZ3GPZ9M9C5F803B1XM3792N.jpg"},"alt":""},{"_type":"block","_key":"key-33-zo7rc","style":"normal","children":[{"_type":"span","_key":"key-26-9n0uc","text":"\n"},{"_type":"span","_key":"key-27-ld0kw","text":" \n\n"},{"_type":"span","_key":"key-28-rtmw6","text":"VOIMALIIGAN TULOKSET\n","marks":["strong"]},{"_type":"span","_key":"key-29-3l7ux","text":"Onnittelut jälleen "},{"_type":"span","_key":"key-30-q3btm","text":"Tuukalle","marks":["strong"]},{"_type":"span","_key":"key-31-bnw3z","text":"!\n\n"}],"markDefs":[{"_type":"link","_key":"key-32-p690l","href":"/_emdash/api/media/file/01KZ3GPZVYKZQTMRRT7V3W20CE.jpg"}]},{"_type":"image","_key":"key-34-qsg0v","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GPZVYKZQTMRRT7V3W20CE.jpg","url":"/_emdash/api/media/file/01KZ3GPZVYKZQTMRRT7V3W20CE.jpg"},"alt":""},{"_type":"image","_key":"key-38-0a9cd","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ0AZ1A13DB0DR1V41W7G.jpg","url":"/_emdash/api/media/file/01KZ3GQ0AZ1A13DB0DR1V41W7G.jpg"},"alt":""},{"_type":"block","_key":"key-47-qlxwr","style":"normal","children":[{"_type":"span","_key":"key-39-ogtgt","text":"\n"},{"_type":"span","_key":"key-40-k54us","text":" \n\n"},{"_type":"span","_key":"key-41-frd0e","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-42-z9kdi","text":"Kuvat: Jyri\n\n"},{"_type":"span","_key":"key-43-796ix","text":"Videot: Tuukka\n\n"},{"_type":"span","_key":"key-44-y18n2","text":" \n\n"},{"_type":"span","_key":"key-45-x415k","text":" \n\n"},{"_type":"span","_key":"key-46-engdd","text":" "}]}]' WHERE id = '01KZ3GDQ8BAKNEADPNXVHS1JSY';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-13-a3ao5","style":"normal","children":[{"_type":"span","_key":"key-1-zp8ai","text":"Helteinen kesä alkaa olla ohi ja kirjoittajaltakin löytyy vihdoin puhtia (ja aikaa) sepustaa \"syksyn\" ensimmäinen juttu.\n\n"},{"_type":"span","_key":"key-2-o2tet","text":"Vuorossa jälleen Juha ja lajina tietenkin penkkipunnerrus. Aktiivisimmat penkkiurheilijat saattoivat seurata Super-EM -kisoja televisiosta, mutta valitettavasti näitä karkeloita ei näytetty ainakaan Suomen ilmaiskanavilla. Ehkä Ranskan urheiluruudussa jotain pätkää saattoi näkyä - ei kuitenkaan kevennysosiossa.\n\n"},{"_type":"span","_key":"key-3-zswva","text":"Ranskassa, kuten muissakin Euroopan maissa, on saatu nauttia kuumuudesta ja tämän asian huomasi myös Juha. Miehen mukaan erityisesti ojentajat kärsivät, joka näkyykin nostoissa: irroitus on vahva, mutta loppuojennus uupui.. Kolmesta nostosta toinen oli onnistunut tarkoittaen, että 155 kiloa yritettiin kaksi kertaa. Kolmas nosto 157,5 kilosta jäi reiluun puoleen väliin.\n\n"},{"_type":"span","_key":"key-4-fb1rn","text":"Lopputuloksena siis EM-hopeaa, joka ei tosin huono suoritus ottaen huomioon millainen kulunut vuosi(kymmen) Juhalla on ollut! Onnittelut siis paikallaan!\n\n"},{"_type":"span","_key":"key-5-6ssqp","text":"Lisäksi: muistattehan, että HYV:n kisakausi alkaa huomenna! Käykää ilmottautumassa nimenhuudossa.\n\n"},{"_type":"span","_key":"key-6-jdxyu","text":"Oheisessa videossa nostot\n\n"},{"_type":"span","_key":"key-7-uruw8","text":"1. nosto: 155 kg: no lift  ( kohta 49:50  videolla)\n\n"},{"_type":"span","_key":"key-8-lb78a","text":"2. nosto: 155 kg: good lift: (kohta 58:52)\n\n"},{"_type":"span","_key":"key-9-x7j5t","text":"3. nosto: 157.5 kg no lift ( kohta 1:09:56 )\n\n"},{"_type":"span","_key":"key-10-i46yj","text":"https://youtu.be/rTBQqpipy_k\n\n"},{"_type":"span","_key":"key-11-86ad8","text":""}],"markDefs":[{"_type":"link","_key":"key-12-6vb3p","href":"/_emdash/api/media/file/01KZ3GQ2PSF60PYW7CCK0PADHN.png"}]},{"_type":"image","_key":"key-14-j8gu5","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ2PSF60PYW7CCK0PADHN.png","url":"/_emdash/api/media/file/01KZ3GQ2PSF60PYW7CCK0PADHN.png"},"alt":""},{"_type":"block","_key":"key-22-bjjau","style":"normal","children":[{"_type":"span","_key":"key-15-pb5rt","text":"Kaksoisvoitto! Juha vasemmalla (luonnollisesti). Kuva: Juha Koivisto"},{"_type":"span","_key":"key-16-03lek","text":" \n\n"},{"_type":"span","_key":"key-17-lmrm1","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-18-913qq","text":"Kuva: Juha\n\n"},{"_type":"span","_key":"key-19-65wpd","text":"Video: FFForce\n\n"},{"_type":"span","_key":"key-20-3bx8v","text":" \n\n"},{"_type":"span","_key":"key-21-y738x","text":" "}]}]' WHERE id = '01KZ3GDR5TK4KF5M3EJ97VF5F5';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-16-xuxr2","style":"normal","children":[{"_type":"span","_key":"key-1-21lc4","text":"Pari viikkoa kulunut perinteisestä joulukuun voimanostokisasta, joten on aika tehdä juttu ennen kuin ihmiset asettuvat joulun rauhaan. Videot saattavat aiheuttaa sydämen tykytyksiä ja siksi ne on syytä katsoa heti tai sitten ensi vuoden puolella.\n\n"},{"_type":"span","_key":"key-2-m3vsv","text":"Kisailmottautuminen näytti lupaavalta 11 ottelijan merkinneen itsensä \"in\". Osa kuitenkin näistä oli tuomareita, lastaajia tai loukaantuneita, ja loppuviimein osallistujia oli 6 (miestä) + 1 (nainen). Kisassa oli mukana kaksi uutta jäsentä, Sonja ja Tommi, sekä paluun kisalavalle tehnyt Olaf, jonka ulkonäkö muistutti Eddie Hallia pienoiskoossa. Tuomareina toimivat naisten viime kauden voittaja Ida (päätuomari) ja (lahjomattomat) konkarit Jyri ja Reijo.\n\n"},{"_type":"span","_key":"key-3-a57xk","text":"Kisapaikkana toimi Otahalli, jonka puitteet ovat Unisportin saleista todettu parhaiten soveltuviksi. Tosin tällä kertaa muut salit ovat eivät olleet enää kovin kaukana Otahallin varustelutasosta... Positiivisena puolena voitaneen sanoa, että kun kerrotaan nostajan tulos, niin sanoja \"nosti vähintään\" saa käyttää menettämättä yöunia. 20 kilon kiekot siis painoivat 20,4 kg (=45 paunaa). Jutun lopusta löytyvissä tuloksissa ei huomioitu em. ylimääräisiä grammoja.\n\n"},{"_type":"span","_key":"key-4-5dkpe","text":"JALKAKYYKKY\n","marks":["strong"]},{"_type":"span","_key":"key-5-3dnnt","text":"Jalkakyykyn sääntöjen kertaaminen alkoi 10 min ennen ensimmäistä nostoa - suunnilleen samaan aikaan kun Pasi saapui punnitukseen ja aloitti lämmittelyn. ;) Muutaman minuutin päästä sama mies astelee 152,5 kiloa painavan tangon alle. Muita erikseen mainittavia suorituksia lienee Olafin 200 kilon (ja risat) kyykähdys, joka tosin tapahtui kisan ulkopuolella neljäntenä nostona. Tuomareiden mielestä kuitenkin 3-0 hyväksytty nosto eli voidaan sanoa, että Olaf liittyy HYV:n 200 kg:n klubiin Tuukan, Tuomaksen (entinen jäsen), Villen ja Jonnen lisäksi.\n\n"},{"_type":"span","_key":"key-6-nvuhm","text":"https://www.youtube.com/watch?v=YM9dhhOSaFQ&feature=youtu.be\n\n"},{"_type":"span","_key":"key-7-mmkq0","text":"PENKKIPUNNERRUS\n","marks":["strong"]},{"_type":"span","_key":"key-8-xvpal","text":"Mainittavia punnerruksia tässä ovat ehdottomasti Yusifin 142,5 kilon suoritus. Mies lähenee 2x oma paino -tulosta, johon ei taida olla kukaan HYV:ssä pystynyt. Kirjoittajaan saa olla yhteydessä, jos väite on väärä! Esim. kaikkia Juhan ja Esan tuloksia en ole löytänyt. Tämän lisäksi Olaf nosti 150 kiloa, jota voitaneen myös pitää maagisena rajana (...joillekin jalkakyykyssä).\n\n"},{"_type":"span","_key":"key-9-h779r","text":"https://www.youtube.com/watch?v=8teU5QksFk0&feature=youtu.be\n\n"},{"_type":"span","_key":"key-10-462s2","text":"MAASTANOSTO\n","marks":["strong"]},{"_type":"span","_key":"key-11-homc7","text":"Vaffa (Reijo) sanoi useaan otteeseen Sonjassa olevan potentiaalia. Tämä potentiaali näkyi erityisesti maastanostossa suhteellisen kevyinä suorituksina - lopputuloksena 130 kilon nosto, joka on 60 kiloiselle melkoisen kova suoritus! Näimme myös \"draamaa\", kun tiukka taistelu Tommin ja Maxin välillä läheni loppuaan. Joko allekirjoitaneen Excel on epäselvä tai Jyri näki Maxin nostoissa potentiaalia, sillä hänen \"täytyi\" korottaa odotettua enemmän viimeisen nostoon \"päihittääkseen\" Tommi. Max tarttui haasteeseen ja tankoon lastattiin 232,5 kiloa. Loppu on historiaa ainakin parin kuukauden ajan, kunnes Max pääsee tosissaan vetämään kevään Push&Pulliin.\n\n"},{"_type":"span","_key":"key-12-wmiwj","text":"Tosiasiassa Max olisi tarvinnut 235 kiloa päihittääkseen Tommin vaivaisella 0,5 WILKSillä. Nyt tappio tuli reilulla 1 WILKSillä.\n\n"},{"_type":"span","_key":"key-13-rney5","text":"https://www.youtube.com/watch?v=Lgn73_lUl7E&feature=youtu.be\n\n"},{"_type":"span","_key":"key-14-gvaip","text":""}],"markDefs":[{"_type":"link","_key":"key-15-b056g","href":"/_emdash/api/media/file/01KZ3GQ6GZF9WZP7ESW3HER7SC.jpg"}]},{"_type":"image","_key":"key-17-mf9w8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ6GZF9WZP7ESW3HER7SC.jpg","url":"/_emdash/api/media/file/01KZ3GQ6GZF9WZP7ESW3HER7SC.jpg"},"alt":""},{"_type":"block","_key":"key-21-d47vn","style":"normal","children":[{"_type":"span","_key":"key-18-61s4p","text":"Vasemmalta: Pasi, Jaakko, Ida, Jyri, Max, Olaf, Reijo, Sonja ja Yusif. Voittaja Tommi makoilee."},{"_type":"span","_key":"key-19-lswz3","text":"Alla kisan tulokset ja voimaliigan tilanne:\n","marks":["em","strong"]}],"markDefs":[{"_type":"link","_key":"key-20-3dpzf","href":"/_emdash/api/media/file/01KZ3GQ75PBW6PN5YG4NDY71G3.jpg"}]},{"_type":"image","_key":"key-22-egy6z","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ75PBW6PN5YG4NDY71G3.jpg","url":"/_emdash/api/media/file/01KZ3GQ75PBW6PN5YG4NDY71G3.jpg"},"alt":""},{"_type":"block","_key":"key-28-0edwr","style":"normal","children":[{"_type":"span","_key":"key-23-zapre","text":"\n"},{"_type":"span","_key":"key-24-3bndu","text":" \n\n"},{"_type":"span","_key":"key-25-etaow","text":" \n\n"},{"_type":"span","_key":"key-26-08w2n","text":"VOIMALIIGAN TILANNE\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-27-okqi7","href":"/_emdash/api/media/file/01KZ3GQ5QTGBM5T7VM59ZGF5Y2.jpg"}]},{"_type":"image","_key":"key-29-hxz0x","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ5QTGBM5T7VM59ZGF5Y2.jpg","url":"/_emdash/api/media/file/01KZ3GQ5QTGBM5T7VM59ZGF5Y2.jpg"},"alt":""},{"_type":"image","_key":"key-32-xm7g2","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ65VTS476ZM5N92XA2NC.jpg","url":"/_emdash/api/media/file/01KZ3GQ65VTS476ZM5N92XA2NC.jpg"},"alt":""},{"_type":"block","_key":"key-37-ijv6l","style":"normal","children":[{"_type":"span","_key":"key-33-ftm3a","text":"\n"},{"_type":"span","_key":"key-34-7ncvw","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-35-y7q4z","text":"Kuvat: Tommi A\n\n"},{"_type":"span","_key":"key-36-qj79r","text":"Videot: Yusif"}]}]' WHERE id = '01KZ3GDV7EMN7DPP3R8JVKPA0N';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-8-qv828","style":"normal","children":[{"_type":"span","_key":"key-1-6juh2","text":"Vuosi 2019 käynnistettiin penkkipunnerruksen yhdistelmäkisalla: ykkösmaksimi sekä toistomaksimi sotilaspenkkityylillä eli ts. jalat ilmassa.\n\n"},{"_type":"span","_key":"key-2-j7obm","text":"Palautumisaikaa joulun pyhien yli oli riittävästi ja näin ollen tuloksetkin olivat sitä luokkaa. Tällä kertaa HYV:n vanhimmat konkarit olivat poissa kisasta, joka jätti mukavasti jännittää voittajaa. Jokaiselle oli varmastikin muodostunut ennakkosuosikki uhoamisen perusteella. Lisäksi toistokisassa Yusifin \"pari toistoa varaa\" oli kostautua.\n\n"},{"_type":"span","_key":"key-3-o0jva","text":"Tulokset (ja videot) kuitenkin puhuvat puolestaan. Maksimiykkösessä on laskettu myös ero edellä olevaan ja tulos, jolla nostaja olisi voittanut.\n\n"},{"_type":"span","_key":"key-4-8blr7","text":"HUOM! Videolta puuttuu ensimmäisen kierroksen nostot ja toistokisassakin näkyy vain osa nostajista. Syynä tekninen vika.\n\n"},{"_type":"span","_key":"key-5-aioh5","text":"Voimaliigan pistetilanne löytyy lopusta. Naisten tilanteeseen ei muutoksia, sillä kaikki osallistujat olivat poikia.\n\n"},{"_type":"span","_key":"key-6-79ceu","text":""}],"markDefs":[{"_type":"link","_key":"key-7-ur25b","href":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg"}]},{"_type":"image","_key":"key-9-0iubk","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg","url":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg"},"alt":""},{"_type":"block","_key":"key-141-23ulk","style":"normal","children":[{"_type":"span","_key":"key-10-5vl68","text":"Vasemmalta: Tuukka, Jaakko, Max, Ville, Jyri, Yusif, Sami, Olaf ja Jonne."},{"_type":"span","_key":"key-11-8iiig","text":"MAKSIMI\n","marks":["strong"]},{"_type":"span","_key":"key-12-th24i","text":"https://www.youtube.com/watch?v=QmQ8C2nNnLY&feature=youtu.be\n\n"},{"_type":"span","_