_key":"key-120-jm9if","text":"26"},{"_type":"span","_key":"key-121-p2oxl","text":"3"},{"_type":"span","_key":"key-122-rzh9c","text":"Jonne"},{"_type":"span","_key":"key-123-im838","text":"23"},{"_type":"span","_key":"key-124-alhs5","text":"4"},{"_type":"span","_key":"key-125-45z3w","text":"Jaakko"},{"_type":"span","_key":"key-126-8thv3","text":"22"},{"_type":"span","_key":"key-127-8d2o4","text":"5"},{"_type":"span","_key":"key-128-x6m2f","text":"Tuukka"},{"_type":"span","_key":"key-129-cyvhs","text":"19"},{"_type":"span","_key":"key-130-7dmf4","text":"6"},{"_type":"span","_key":"key-131-n9jjv","text":"Pasi"},{"_type":"span","_key":"key-132-5adgl","text":"15"},{"_type":"span","_key":"key-133-hc5g4","text":"7"},{"_type":"span","_key":"key-134-oxpmu","text":"Tommi A"},{"_type":"span","_key":"key-135-4rpsh","text":"12"},{"_type":"span","_key":"key-136-nhj6h","text":"8"},{"_type":"span","_key":"key-137-ymkbm","text":"Max"},{"_type":"span","_key":"key-138-gplbl","text":"9"},{"_type":"span","_key":"key-139-yab4j","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-140-d6ocl","text":"Videot: Tuukka"}]}]' WHERE id = '01KZ3GDWBJBVQXA9T17VPGB453';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-7-ob51v","style":"normal","children":[{"_type":"span","_key":"key-1-sqrfd","text":"New year 2019 started off with the good old bench press: one rep max and maximum reps, both with feet up.\n\n"},{"_type":"span","_key":"key-2-4edtf","text":"Christmas break allowed for plenty of recovery time and so the results proved that as well. This time around HYV oldest veterans did not make it to the event. Everybody had their favorite picked out based on the \"threat levels\". In the rep competition Yusif''s carefree attitude leaving \"a few reps in the tank\" almost backfired. \n\n"},{"_type":"span","_key":"key-3-h8ls6","text":"We let the videos do the speaking, however. In one rep max table we also provide more stats, for example how much competitors would have had to have benched in order to win. \n\n"},{"_type":"span","_key":"key-4-qo505","text":"!NB Due to technical difficulties some of the lifts are missing from the videos, notably first round of 1rm competition and some lifters are missing from the rep competition. \n\n\n"},{"_type":"span","_key":"key-5-jxgs5","text":""}],"markDefs":[{"_type":"link","_key":"key-6-8v440","href":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg"}]},{"_type":"image","_key":"key-8-e6e49","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg","url":"/_emdash/api/media/file/01KZ3GQ8JN1Y20C9NJA4XTTX2Y.jpeg"},"alt":""},{"_type":"block","_key":"key-17-q1kww","style":"normal","children":[{"_type":"span","_key":"key-9-y4zrz","text":"From the left: Tuukka, Jaakko, Max, Ville, Jyri, Yusif, Sami, Olaf and Jonne."},{"_type":"span","_key":"key-10-ke7u5","text":"MAX\n","marks":["strong"]},{"_type":"span","_key":"key-11-195im","text":"https://www.youtube.com/watch?v=QmQ8C2nNnLY&feature=youtu.be\n\n"},{"_type":"span","_key":"key-12-rhdch","text":" \n\n"},{"_type":"span","_key":"key-13-mafwh","text":"REPS\n","marks":["strong"]},{"_type":"span","_key":"key-14-czhew","text":"https://www.youtube.com/watch?v=_bUnRKSDH1Q&feature=youtu.be\n\n"},{"_type":"span","_key":"key-15-2agqc","text":"Results:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-16-t12cv","href":"/_emdash/api/media/file/01KZ3GQ7K8D2FRZ71GBG4ARYTZ.jpg"}]},{"_type":"image","_key":"key-18-lb6gk","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ7K8D2FRZ71GBG4ARYTZ.jpg","url":"/_emdash/api/media/file/01KZ3GQ7K8D2FRZ71GBG4ARYTZ.jpg"},"alt":""},{"_type":"block","_key":"key-22-s761n","style":"normal","children":[{"_type":"span","_key":"key-19-jvno2","text":"\n"},{"_type":"span","_key":"key-20-3nucu","text":"Voimaliiga points:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-21-pk6ii","href":"/_emdash/api/media/file/01KZ3GQ88J9F07C14QF443TJDP.jpg"}]},{"_type":"image","_key":"key-23-ryysg","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ88J9F07C14QF443TJDP.jpg","url":"/_emdash/api/media/file/01KZ3GQ88J9F07C14QF443TJDP.jpg"},"alt":""},{"_type":"block","_key":"key-29-h1g26","style":"normal","children":[{"_type":"span","_key":"key-24-q7upi","text":"\n"},{"_type":"span","_key":"key-25-baw8e","text":" \n\n"},{"_type":"span","_key":"key-26-qopwv","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-27-7n9qn","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-28-4za1e","text":"Videos: Tuukka"}]}]' WHERE id = '01KZ3GDXEATBC521HFR6A687WC';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-05zak","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg","url":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg"},"alt":""},{"_type":"block","_key":"key-13-hvsqq","style":"normal","children":[{"_type":"span","_key":"key-5-9u1zw","text":"Vasemmalta ylhäältä: Jaakko, Olaf, Tommi, Sonja, Valtteri, Max, Ville, Pasi. Alhaalla Yusif ja Sami."},{"_type":"span","_key":"key-6-36kjl","text":"Jotta tuntuma maastavetoon ei pääsisi puolen vuoden aikana katoamaan, on HYV:n voimaliigan osakilpailuksi vakiintunut Push&Pull-kisa, jossa lajeina on penkkipunnerrus ja maastanosto - molemmat voimanostosäännöin.\n\n"},{"_type":"span","_key":"key-7-rb5oq","text":"Osanottajia oli tällä kertaa 8 (7 miestä ja 1 nainen), joista kaikki olivat vanhoja kisaajia edellisistä mittelöistä.\n\n"},{"_type":"span","_key":"key-8-hexpb","text":"Mainittavia suorituksia oli Olafin 160 kilon penkki ja Yusifin 99 % RAW (no belt, sumo) 245 kilon maastanosto. Videolta voit katsoa onnistuivatko nämä nostot ;)\n\n"},{"_type":"span","_key":"key-9-wnr1w","text":"https://www.youtube.com/watch?v=hVWmCUIB_NI\n\n"},{"_type":"span","_key":"key-10-60trj","text":" \n\n"},{"_type":"span","_key":"key-11-ubi8t","text":"TULOKSET:","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-12-z6rzw","href":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"}]},{"_type":"image","_key":"key-14-dsnp3","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg","url":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"},"alt":""},{"_type":"block","_key":"key-19-s0ygx","style":"normal","children":[{"_type":"span","_key":"key-15-qtyn7","text":"\n"},{"_type":"span","_key":"key-16-smakk","text":"PISTETILANNE\n","marks":["strong"]},{"_type":"span","_key":"key-17-718xy","text":"Miehet\n\n"}],"markDefs":[{"_type":"link","_key":"key-18-6709f","href":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"}]},{"_type":"image","_key":"key-20-rovae","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg","url":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"},"alt":""},{"_type":"block","_key":"key-24-j96u4","style":"normal","children":[{"_type":"span","_key":"key-21-isi8v","text":"\n"},{"_type":"span","_key":"key-22-leznl","text":"Naiset:\n\n"}],"markDefs":[{"_type":"link","_key":"key-23-2cu8h","href":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"}]},{"_type":"image","_key":"key-25-3oy85","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg","url":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"},"alt":""},{"_type":"block","_key":"key-29-9ntp5","style":"normal","children":[{"_type":"span","_key":"key-26-3h6hy","text":"\n"},{"_type":"span","_key":"key-27-3305y","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-28-vqpc9","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GDYCZKGE8BC27JN3P0ZHA';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-9ezhy","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg","url":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg"},"alt":""},{"_type":"block","_key":"key-14-xqrm7","style":"normal","children":[{"_type":"span","_key":"key-5-y41hh","text":"Vasemmalta: Simo, Yusif, Leo, Eero ja Jaakko"},{"_type":"span","_key":"key-6-eepm3","text":"Otsikko on hiukan harhaanjohtava, sillä selän mittaaminen ei vielä kuulu voimaliigan osakilpailuihin. Jotain sen suuntaista kisaa on kuitenkin mietitty järjestettävän... ;)\n\n"},{"_type":"span","_key":"key-7-jo7hz","text":"Aiheeseen: huhtkuussa käytiin kauden 2018 - 2019 toiseksi viimeinen osakilpailu. Lajina leuanveto (ykkös- ja toistomaksimi) ja paikkana Meilahden Unisport.\n\n"},{"_type":"span","_key":"key-8-lexek","text":"Kuten HYV:ssä on tapana, oli uhoamista havaittavissa tovin aikaa ennen kisaa. Taktikointia nähtiin myös ja voittoon ylsikin tällä kertaa maksimikisassa debytoinut Simo ja toistokisassa jo neljättä vuotta putkeen Jaakko. Taso oli kova, mutta valitettavasti viime vuoden kovimmista nostajista moni ei päässyt tulemaan paikalle.\n\n"},{"_type":"span","_key":"key-9-39dm7","text":"Nauttikaa videosta!\n\n"},{"_type":"span","_key":"key-10-25lp7","text":"https://www.youtube.com/watch?v=LHJWjgPJ61w&feature=youtu.be\n\n"},{"_type":"span","_key":"key-11-ub9ez","text":"TULOKSET","marks":["strong"]},{"_type":"span","_key":"key-12-xd4g0","text":" (punaisella hylätty nosto)\n\n"}],"markDefs":[{"_type":"link","_key":"key-13-c1e9g","href":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"}]},{"_type":"image","_key":"key-15-ov3nj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg","url":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"},"alt":""},{"_type":"block","_key":"key-20-le16b","style":"normal","children":[{"_type":"span","_key":"key-16-hbd7s","text":"\n"},{"_type":"span","_key":"key-17-2ymws","text":"PISTETILANNE","marks":["strong"]},{"_type":"span","_key":"key-18-js2b0","text":" (naisten osalta ei muutoksia, sillä kaikki osanottajat olivat miehiä)\n\n"}],"markDefs":[{"_type":"link","_key":"key-19-xrnz4","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE-1.jpg"}]},{"_type":"image","_key":"key-21-vxrzj","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg","url":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg"},"alt":""},{"_type":"block","_key":"key-25-tzf6w","style":"normal","children":[{"_type":"span","_key":"key-22-1nw5w","text":"\n"},{"_type":"span","_key":"key-23-rg3l1","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-24-vjykt","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GDZJECBR2EZBAYGGCQ1SV';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-11-o9ndj","style":"normal","children":[{"_type":"span","_key":"key-1-2drg6","text":"...mutta eivät sentään samassa kisassa.\n\n"},{"_type":"span","_key":"key-2-qyeh6","text":"Juha Koivisto saavutti kolme kultaa viime toukokuussa kisatuissa penkkikarnevaaleissa Lohjalla ja Sampsa Marttila EM-hopeaa "},{"_type":"span","_key":"key-3-mvaqg","text":"painonnostossa ","marks":["strong"]},{"_type":"span","_key":"key-4-i54tm","text":"Rovaniemellä.\n\n"},{"_type":"span","_key":"key-5-q2o5g","text":"Ensimmäiseksi käsittelemme Juha Koivoston kisaa\n","marks":["strong"]},{"_type":"span","_key":"key-6-sxkrq","text":"Kuten mainitsin, osallistui Juha kolmeen kisaan: voimapunnerrukseen (ykkösmaksimi jalat ilmassa), toistokisaan sekä klassiseen penkkipunnerrukseen. Aiemmista jutuista ja mitalisaaliista voidaankin päätellä, että Juha ylläpitää kisaherkkyyttään jatkuvasti yllä ja siksi kahden tai vaikkapa kolmen kisan suoritukset eivät tuota miehelle ongelmia. Tällä kertaa toistokisa oli jäähdyttelyä, sillä Juha oli ainoa kisaaja ja yksi kisa oli vielä suorittamatta. Kultaa tuli 10 toistolla (HUOM! Juhan toistot liikkuvat 20 paremmalla puolella).\n\n"},{"_type":"span","_key":"key-7-4d2y6","text":"Ja vaikka Juhalla oli jo voimapunnerrus takana 10 kilon kaulalla toiseksi tulleeseen nähden, voitti hän klassisessa penkkipunnerruksessa tunnetun kilpakumppaninsa Ilkka Launosen 5 kilolla. Ilkalla on Suomen mestaruus vuodelta 2019 ja EM-kulta vuodelta 2018.\n\n"},{"_type":"span","_key":"key-8-yfodi","text":"Ohessa videot kisoista sekä tulokset:\n\n"},{"_type":"span","_key":"key-9-18vx9","text":"Maksimivoimapunnerrus:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-10-swakb","href":"/_emdash/api/media/file/01KZ3GQBG45WY689PPJ2KC240S.jpg"}]},{"_type":"image","_key":"key-12-dycy2","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQBG45WY689PPJ2KC240S.jpg","url":"/_emdash/api/media/file/01KZ3GQBG45WY689PPJ2KC240S.jpg"},"alt":""},{"_type":"block","_key":"key-15-ifhnx","style":"normal","children":[{"_type":"span","_key":"key-13-8pem9","text":"\n"},{"_type":"span","_key":"key-14-nqf05","text":"https://youtu.be/QIByj8nIx8Q?t=3110"}]},{"_type":"block","_key":"key-17-t817w","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-16-tgut6","text":"Nosto: 140 kg : good lift (51:50)"}]},{"_type":"block","_key":"key-19-0ihp2","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-18-fkfc3","text":"Nosto: 147.5 kg: good lift (1:06:22)"}]},{"_type":"block","_key":"key-21-trdij","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-20-1j9v3","text":"Nosto: 150 kg: good lift (1:18:20)"}]},{"_type":"block","_key":"key-26-kiq9l","style":"normal","children":[{"_type":"span","_key":"key-22-bqvy0","text":" \n\n"},{"_type":"span","_key":"key-23-vvxyq","text":" \n\n"},{"_type":"span","_key":"key-24-q8p5g","text":"Klassinen penkki:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-25-j4x0g","href":"/_emdash/api/media/file/01KZ3GQBTNY2SCDAQSB8M09W93.jpg"}]},{"_type":"image","_key":"key-27-ardta","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQBTNY2SCDAQSB8M09W93.jpg","url":"/_emdash/api/media/file/01KZ3GQBTNY2SCDAQSB8M09W93.jpg"},"alt":""},{"_type":"block","_key":"key-30-p4i9d","style":"normal","children":[{"_type":"span","_key":"key-28-blqrk","text":"\n"},{"_type":"span","_key":"key-29-9pntb","text":"https://youtu.be/eKACBG7DIwY?t=2714"}]},{"_type":"block","_key":"key-32-ecz5s","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-31-babog","text":"Nosto: 150 kg : good lift (45:10)"}]},{"_type":"block","_key":"key-34-eqjtm","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-33-6zoos","text":"Nosto: 155 kg: no lift (58:05)"}]},{"_type":"block","_key":"key-36-quksa","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-35-nn9sn","text":"Nosto: 155 kg: good lift (1:08:33)"}]},{"_type":"block","_key":"key-56-ev2ci","style":"normal","children":[{"_type":"span","_key":"key-37-f7n86","text":" \n\n"},{"_type":"span","_key":"key-38-rbjge","text":"Sampsan kisa:\n","marks":["strong"]},{"_type":"span","_key":"key-39-intly","text":"HYV:n jäsenistö on muuttunut sen verran viime aikoina, että kaikki eivät välttämättä tiedä kenestä on kyse. Sampsa on yksi ensimmäisistä HYV:n jäsenistä ja myös yksi vahvimmista: mm. paras kyykky HYV:n kisoissa 195 kg, joka on Sampsan mittaiselle ja \"vain\" 80-kiloiselle nostajalle erittäin kova tulos. Sampsa dominoi HYV:n voimakarkeloissa, mutta loisti myös aerobisissa lajeissa.\n\n"},{"_type":"span","_key":"key-40-1edvl","text":"Sampsan on voinut nähdä Otahallilla treenaamassa.\n\n"},{"_type":"span","_key":"key-41-7sd7p","text":"Kisavideon löydät jutun lopusta. Ohessa Sampsan omat kommentit siitä, kuinka hän päätyi matkaamaan Rovaniemelle hakemaan mitalin ;)\n\n"},{"_type":"span","_key":"key-42-hoo88","text":"\"Olen treenaillut aktiivisesti painonnostoa noin 2,5 vuotta. Ensimmäisen vuoden itsekseni ja alkuvuodesta 2018 osallistuin n. 4kk ajan ohjattuun punttikouluun 1krt viikossa. Laji vei enemmän ja enemmän mennessään ja kilpaileminen tuntui alusta saakka kiinnostavalta. Keväällä 2018 liityin Anni Vuohijoen valmennusryhmään ja olen treenaillut siitä lähtien ohjatusti 4-5 krt viikossa.\n\n"},{"_type":"span","_key":"key-43-vcae6","text":"Tavoitteiden asettaminen, niiden tavoittelu ja saavuttaminen ovat antaneet alusta asti kipinää tekemiseen. Ja motivaatiota on lisännyt myös korkeahko ikä (40v), jonka tuomia lisähaasteita vastaan on ollut mukava kamppailla. Vähän sitä myös yrittää treenata nuoruutta takaisin :)\n\n"},{"_type":"span","_key":"key-44-ftayd","text":"Valmennusryhmässä on asetettu omia tulostavoitteita esim. vuoden periodilla ja ohjelmaan on kuulunut tasaisesti myös lähialueella järjestettyihin lähinnä piirikunnallisiin kilpailuihin osallistumista.\n\n"},{"_type":"span","_key":"key-45-ou9gl","text":"Kuluvan kauden ns. pääkilpailu oli Rovaniemellä järjestetty Masters EM 2019. Oma kisapäivä oli 17.6. sarjassa M40 81kg.\n\n"},{"_type":"span","_key":"key-46-bao6h","text":"Kisoihin valmistautuminen sujui hyvin ja takana oli pitkä ehjä treenikausi. Tavoitteena kisoissa oli mitali ja oman yhteistulos-ennätyksen (205 kg, helmikuussa 2019) parantaminen.\n\n"},{"_type":"span","_key":"key-47-lh2b2","text":"Tempauksessa aloituspainoksi laitoimme 92kg. Se tuli kevyehkösti ylös ja hyväksyttiin 3-0. Seuraavaan lastattiin oma ennätysrauta 96kg ja myös se tuli hyvin ylös 3-0. Viimeiseen lähdettiin hakemaan 100kg tempausta, mutta tällä kertaa ei onnistunut. Tempaukseen olin kohtuullisen tyytyväinen, mutta hieman parempaa tulosta odotin.\n\n"},{"_type":"span","_key":"key-48-8oep5","text":"Työnnössä ensimmäisellä haettiin tekniikka-ailahteluista johtuen varmaa tulosta ja tankoon laitettiin 110kg. Se tuli ylös ja hyväksyttiin tuomariäänin 3-0. Seuraavaan yritykseen lastattiin oma ennätysrauta 114kg ja myös tämä tuli yllättävän puhtaasti ylös ja hyväksyttiin 3-0. Viimeiseen yritykseen lähdettiin hakemaan 120kg ja tässä tuli kuin tulikin hyväksytysti ylös äänin 2-1. Työntö kulki yli odotusten ja tekniikka pelasi hyvin.\n\n"},{"_type":"span","_key":"key-49-yqwdo","text":"Tulin lopputuloksissa toiseksi yhteistuloksella 216kg.\n\n"},{"_type":"span","_key":"key-50-c7ayl","text":"Tämän vuoden loppuun mennessä tavoitteena yhteistulos 220kg ja sen saavuttamiseksi treenit jatkuu!\"\n\n"},{"_type":"span","_key":"key-51-duejq","text":"Onnittelut vielä Sampsalle!\n","marks":["strong"]},{"_type":"span","_key":"key-52-cin9y","text":" \n\n"},{"_type":"span","_key":"key-53-21fyw","text":"Sampsa nostaa videon loppupuolella (n. 6:45 alkaen).\n\n"},{"_type":"span","_key":"key-54-gme5i","text":"https://youtu.be/_C7csn8GlQ0\n\n"}],"markDefs":[{"_type":"link","_key":"key-55-ordkg","href":"/_emdash/api/media/file/01KZ3GQC81KJMTXGF9907SF216.jpg"}]},{"_type":"image","_key":"key-57-8w59h","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQC81KJMTXGF9907SF216.jpg","url":"/_emdash/api/media/file/01KZ3GQC81KJMTXGF9907SF216.jpg"},"alt":""},{"_type":"block","_key":"key-61-9qnhx","style":"normal","children":[{"_type":"span","_key":"key-58-f8h1i","text":"\n"},{"_type":"span","_key":"key-59-qglmd","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-60-dxa39","text":"Videot: Juha Koivisto ja Rovaniemen Reipas"}]}]' WHERE id = '01KZ3GE0RE12N5QAB23822EBXS';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-6-8ww8h","style":"normal","children":[{"_type":"span","_key":"key-1-pp44u","text":"Parempi myöhään kuin ei milloinkaan vai miten se meni... Kesäkiireet ohi ja uusi kausikin on alkanut, mutta viime kauden laittaminen pakettiin on jäänyt tekemättä.\n","marks":["em"]},{"_type":"span","_key":"key-2-avfkb","text":"Kyseessä oli perinteinen voimanostokisa Otahallilla. Alkuasetelmat olivat sellaiset, että Yusif oli jo varmistanut Voimaliigan voiton, sillä miehellä oli takana nippu voittoja. Naisilla tilanne oli vastaava, sillä Sonjalla oli jo 12 pisteen johto ja hän oli naisista ainoa osanottaja tässä kauden päätöskisassa.\n\n"},{"_type":"span","_key":"key-3-m6c67","text":"Jotta julkaisua ei venytetä pidemmäksi, niin tiivistetään juttua ja poimitaan merkittävimmät asiat alle luetteloksi. Katso myös video, jonka Yusif ansiokkaasti teki. "},{"_type":"span","_key":"key-4-lo96p","text":"HUOM! ","marks":["strong"]},{"_type":"span","_key":"key-5-r928x","text":"jutun lopusta löytyvät myös kauden kokonaistulokset."}]},{"_type":"block","_key":"key-8-h1si1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-7-4fliv","text":"Kisajärjestelyt (mm. yksi ylimääräinen tietokoneen näyttö)"}]},{"_type":"block","_key":"key-10-okilh","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-9-f7at9","text":"Jyri ja Sami vaativina tuomareina"}]},{"_type":"block","_key":"key-12-36c34","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-11-ipdax","text":"Yusifin 200 kg kyykky (lähes)"}]},{"_type":"block","_key":"key-14-91sv1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-13-bmv6i","text":"Yusifin 150 kg penkki"}]},{"_type":"block","_key":"key-16-1eifl","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-15-77ham","text":"Maxin huomattava maastanoston parannus (250 kg)"}]},{"_type":"block","_key":"key-18-y79lz","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-17-85d0m","text":"Yusifin 600 kg yt"}]},{"_type":"block","_key":"key-20-fzp9v","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-19-dn336","text":"Kovatasoinen maastonostokisa (pl. allekirjoittanut)"}]},{"_type":"block","_key":"key-24-dnwl5","style":"normal","children":[{"_type":"span","_key":"key-21-b8c99","text":"https://youtu.be/wnpTAiL8kxY\n\n"},{"_type":"span","_key":"key-22-o2him","text":""}],"markDefs":[{"_type":"link","_key":"key-23-ptguq","href":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"}]},{"_type":"image","_key":"key-25-4cf3s","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg","url":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"},"alt":""},{"_type":"block","_key":"key-30-1jqf5","style":"normal","children":[{"_type":"span","_key":"key-26-1q7l7","text":"Miesten päätökisan tulokset."},{"_type":"span","_key":"key-27-z5kzu","text":" \n\n"},{"_type":"span","_key":"key-28-jgokb","text":""}],"markDefs":[{"_type":"link","_key":"key-29-pgiw1","href":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"}]},{"_type":"image","_key":"key-31-o5y58","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg","url":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"},"alt":""},{"_type":"block","_key":"key-35-8dbw1","style":"normal","children":[{"_type":"span","_key":"key-32-ybpck","text":"Naisten päätöskisan tulokset"},{"_type":"span","_key":"key-33-efv75","text":""}],"markDefs":[{"_type":"link","_key":"key-34-whnkj","href":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"}]},{"_type":"image","_key":"key-36-ahyej","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg","url":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"},"alt":""},{"_type":"block","_key":"key-41-i1i7h","style":"normal","children":[{"_type":"span","_key":"key-37-pov9q","text":"Ylhäältä vasemmalta: Jaakko, Jyri, Valtteri, Max, Sonja, Tommi. Alhaalla Sami ja Yusif"},{"_type":"span","_key":"key-38-pjhp9","text":" \n\n"},{"_type":"span","_key":"key-39-16c2w","text":"KAUDEN LOPPUTULOKSET:\n\n"}],"markDefs":[{"_type":"link","_key":"key-40-fgpte","href":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"}]},{"_type":"image","_key":"key-42-ywu8e","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg","url":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"},"alt":""},{"_type":"image","_key":"key-49-s9zr6","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg","url":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg"},"alt":""},{"_type":"block","_key":"key-55-fpz38","style":"normal","children":[{"_type":"span","_key":"key-50-nwy16","text":"Tällä kaudella oli vain kaksi naista. Sonja osallistui ainoana vaadituun määrään (3) kisoja."},{"_type":"span","_key":"key-51-k567x","text":" \n\n"},{"_type":"span","_key":"key-52-fligc","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-53-h52h4","text":"Video: Yusif\n\n"},{"_type":"span","_key":"key-54-5uiwu","text":" "}]}]' WHERE id = '01KZ3GE1RN2XH3TJJR5MASD3P2';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-ntmrp","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQG670M7SCJ6WAYHWW2JM.jpg","url":"/_emdash/api/media/file/01KZ3GQG670M7SCJ6WAYHWW2JM.jpg"},"alt":""},{"_type":"block","_key":"key-12-s09ke","style":"normal","children":[{"_type":"span","_key":"key-5-asbp5","text":"Kuva: Aulis Lindfors"},{"_type":"span","_key":"key-6-0w87y","text":"Välillä voisi kuvitella Juhan olevan myös erittäin kovassa aerobisessa kunnossa, sillä matkaaminen kisasta toiseen vaatii jo jonkinlaista kiirehtimistå.. Ehkä mies onkin? ;)\n\n"},{"_type":"span","_key":"key-7-aom5f","text":"Kyseessä oli siis Juhan 157. kisa. Tällä kertaa kotimaassa ja Suomen Voimapunnerrus ry:n järjestämä mittelö, jossa Juhan ylivoimainen kunto mahdollisti SE-raudan kokeilun. Luen alta miehen mietteet ja tarkista videolta miten tiukkoja (tai helppoja) nostot todellisuudessa olivat.\n\n"},{"_type":"span","_key":"key-8-j6ovg","text":"Viime lauantaina Lopen Voima ja kuntotiimi järjesti maksimivoimapunnerruskisat. Samalla SVRY juhlisti 10. toimintavuottaan ADT:n alaisena kisaorganisaattorina.Kisat alkoi mm. maamme laululla!\n","marks":["em"]},{"_type":"span","_key":"key-9-ful6g","text":"Allekirjoittanut osallistui kisaan sarjassa alle 93kg M60 ikäluokkaan.\n","marks":["em"]},{"_type":"span","_key":"key-10-o7jvp","text":"https://www.youtube.com/watch?v=tforAuHD6Zg\n\n"},{"_type":"span","_key":"key-11-82fv3","text":" "}]},{"_type":"block","_key":"key-14-y2wog","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-13-bzepj","text":"Nosto: 145 kg : good lift (1:16:00)"}]},{"_type":"block","_key":"key-16-yuc2q","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-15-uhlei","text":"Nosto: 150 kg: good lift (1:23:45) voitto nosto"}]},{"_type":"block","_key":"key-18-8xe0y","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-17-hplxk","text":"Nosto: 155 kg: no lift (1:32:12) SE yritys"}]},{"_type":"block","_key":"key-22-8q5il","style":"normal","children":[{"_type":"span","_key":"key-19-fcydb","text":"Kisa voitto tuli toisella nostolla, sillä toiseksi tullut Arto Malava ”pummasi” 147.5 kg toisella nostolla, mutta sai sen ylös viimeisellä yrityksellä. Tämä tarjosi minulle mahdollisuuden yrittää parantaa nimissäni olevaa SE lukemaa 152.5 kg. Tanko lähti kyllä rinnasta, mutta vauhti ei riittänyt enkä saanut tankoa ojentajille ja nosto epäonnistui.\n","marks":["em"]},{"_type":"span","_key":"key-20-9wpoq","text":"Kyseessä oli allekirjoittaneen 19. suomen mestaruus. Kaikkiaan kyseessä oli 32 SM mitali. (19 kultaa, 9 hopeaa ja 4 pronssia, muita meriittejä ovat klassisen penkin MM kulta 2018 ja MM hopea 2018). Olen tänä vuonna osallistunut 8 kisaan, joita on kertynyt vuodesta 2006 alkaen 157.\n","marks":["em"]}],"markDefs":[{"_type":"link","_key":"key-21-2zl44","href":"/_emdash/api/media/file/01KZ3GQGNKP15437XBA4VB7102.png"}]},{"_type":"image","_key":"key-23-ak94f","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQGNKP15437XBA4VB7102.png","url":"/_emdash/api/media/file/01KZ3GQGNKP15437XBA4VB7102.png"},"alt":""},{"_type":"block","_key":"key-27-f4js6","style":"normal","children":[{"_type":"span","_key":"key-24-dm7a6","text":"\n"},{"_type":"span","_key":"key-25-2bj3c","text":"Teksti: Jaakko ja Juha\n\n"},{"_type":"span","_key":"key-26-bgw6b","text":"Video: VoimaStream"}]}]' WHERE id = '01KZ3GE3VBJ22K4PHV1VPKSD1Y';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-w50ku","style":"normal","children":[{"_type":"span","_key":"key-1-dp6q9","text":"Kauden 2019 - 2020 ensimmäinen kisa oli nimeltään Otevoimakolmio, vaikkakin yhdessä lajissa ei niinkään mitattu otevoimaa vaan muuta \"staattista kestävyyttä\". Alkuperäinen kisasuunnitelma sisälsi lajit"}]},{"_type":"block","_key":"key-4-wbznz","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-3-rbpaj","text":"Myötäotemaastanosto (ei sormilukkoa)"}]},{"_type":"block","_key":"key-6-ayg6w","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-5-e8is2","text":"Lekan nosto vaakatasossa mahdollisimman kaukaa lyömäpäästä"}]},{"_type":"block","_key":"key-8-mytcw","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-7-coxea","text":"Krusifiksi"}]},{"_type":"block","_key":"key-14-ipgtc","style":"normal","children":[{"_type":"span","_key":"key-9-y6cip","text":"Osa kannustin-/tuomarijoukoista ei kuitenkaan päässyt paikalle - ja siksi ei lekakaan. "},{"_type":"span","_key":"key-10-l3t45","text":"Näin ollen laji 2 korvattiin vanhan kunnon levypainojen pidolla (sormien välissä).\n","marks":["strong"]},{"_type":"span","_key":"key-11-zwnjn","text":"Osallistujat näet ao. kuvasta. Olafin \"ilmottautuminen\" jäi viime hetkeen, mutta hänet hyväksyttiin yksimielisesti mukaan vaikka punnitukseen ei päässytkään (HUOM! ei tasatuloksia, joten painoilla ei väliä) ;)\n\n"},{"_type":"span","_key":"key-12-srmeu","text":""}],"markDefs":[{"_type":"link","_key":"key-13-jk3x7","href":"/_emdash/api/media/file/01KZ3GQJAMHE97DKKGF63T4N1R.jpg"}]},{"_type":"image","_key":"key-15-3fnoe","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQJAMHE97DKKGF63T4N1R.jpg","url":"/_emdash/api/media/file/01KZ3GQJAMHE97DKKGF63T4N1R.jpg"},"alt":""},{"_type":"block","_key":"key-21-9ib22","style":"normal","children":[{"_type":"span","_key":"key-16-6rj0b","text":"Ylhäällä vasemmalta (d =debyytti): Aki (d) , Mathilda (d), Reijo (päätuomari), Olaf, Tommi, Ida. Alla vasemmalta: Tuukka, Jaakko, Yusif, Yusifin pohkeet."},{"_type":"span","_key":"key-17-c8u90","text":"Myötäotemaastanosto\n","marks":["strong"]},{"_type":"span","_key":"key-18-qz43r","text":"Legenda kertoo, että ainakin yksi kovimmista (lue: kovin) myötäotevetäjä ei päässyt paikalle, joka tarkoitti muille ilmaisia pisteitä. Nostoissa käytettiin IPF-maastanostosääntöjä eli \"down!\"-komennon jälkeen painot oli saatettava alas. Loppuojennuksissa kuitenkin epäselvyydet tulkittiin nostajien eduksi. Absoluuttinen tulos ratkaisi tarkoittaen että IPF- tai WILKS-kertoimia ei käytetty lopputuloksissa. Tasatuloksissa kuitenkin kevyempi nostaja voittaa. Naiset nostivat 15 kilon tangolla ja miehillä oli normaali 20 kilon tanko. Laakerointi oli molemmissa huippuluokkaa.\n\n"},{"_type":"span","_key":"key-19-ccp5l","text":"Miehillä tulokset vaihtelivat 140,0 - 167,5 kilon ja naisilla 100 - 120 kilon välillä. Tosin, jos naisilla olisi ollut vielä neljännet yritykset, olisivat painot todennäköisesti vaihdelleet 110 - 130 välillä. Alla tulokset:\n\n"}],"markDefs":[{"_type":"link","_key":"key-20-bvqby","href":"/_emdash/api/media/file/01KZ3GQJNDV31Z559XW17T9HVC.jpg"}]},{"_type":"image","_key":"key-22-bhu9o","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQJNDV31Z559XW17T9HVC.jpg","url":"/_emdash/api/media/file/01KZ3GQJNDV31Z559XW17T9HVC.jpg"},"alt":""},{"_type":"block","_key":"key-27-yc80s","style":"normal","children":[{"_type":"span","_key":"key-23-jhqgv","text":"\n"},{"_type":"span","_key":"key-24-hzduz","text":"Levypainojen pito\n","marks":["strong"]},{"_type":"span","_key":"key-25-cgc0p","text":"Koska kisa oli Kluuvissa, ei Eleikon tai Leokon rautakiekkoja päästy hypistelemään, vaan tyydyttiin Gymlecoon(?) Lajissa siis miehet pitivät molemmissa käsissä kahta 10 kilon kiekkoa (eli yht. 40 kg) ja naiset yhtä 15 kilon kiekkoa (eli yht. 30 kg) mahdollisimman kauan. Gymlecon kiekoissa oli erikoisuutena erinäiset lovet, joihin saattoi saada kätevästi sormensa. Tämä saattoi hyödyttää ainakin osaa kilpailijoista. Tulokset alla:\n\n"}],"markDefs":[{"_type":"link","_key":"key-26-q11qc","href":"/_emdash/api/media/file/01KZ3GQK0XEAW3DMK9M6VFTQV5.jpg"}]},{"_type":"image","_key":"key-28-0op53","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQK0XEAW3DMK9M6VFTQV5.jpg","url":"/_emdash/api/media/file/01KZ3GQK0XEAW3DMK9M6VFTQV5.jpg"},"alt":""},{"_type":"image","_key":"key-33-lahg8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQMAD7W7H5JFSEGTACV0R.jpg","url":"/_emdash/api/media/file/01KZ3GQMAD7W7H5JFSEGTACV0R.jpg"},"alt":""},{"_type":"block","_key":"key-39-n3jsh","style":"normal","children":[{"_type":"span","_key":"key-34-6up08","text":"Käytetyt levypainot (10 ja 15 kg)"},{"_type":"span","_key":"key-35-7h9lh","text":" \n\n"},{"_type":"span","_key":"key-36-e0toj","text":"Krusifiksi\n","marks":["strong"]},{"_type":"span","_key":"key-37-nlltf","text":"Koska HYV on täynnä nöyriä kisaajia ja kansainvälisissä voimamieskisoissa krusifiksin painot ovat 16 kiloa, päädyttiin valitsemaan miehille 7 kilon ja naisille 5 kilon käsipainot. Lopputuloksena oli erittäin hapokasta tahkoamista (ks. tulokset alla).\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-yx1mf","href":"/_emdash/api/media/file/01KZ3GQKBJGBJQ9CCVDF80M2K3.jpg"}]},{"_type":"image","_key":"key-40-ji15r","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQKBJGBJQ9CCVDF80M2K3.jpg","url":"/_emdash/api/media/file/01KZ3GQKBJGBJQ9CCVDF80M2K3.jpg"},"alt":""},{"_type":"block","_key":"key-46-hjz10","style":"normal","children":[{"_type":"span","_key":"key-41-vg0yi","text":"\n"},{"_type":"span","_key":"key-42-8qwfw","text":" \n\n"},{"_type":"span","_key":"key-43-awhi6","text":"Sitten Leo tuli viihdyttämään ja bodattiin ja mentiin saunomaan ja syömään. Sitten menimme kotiin.\n\n"},{"_type":"span","_key":"key-44-ib8p2","text":"Lopputulokset, jotka myös samalla näyttävät kauden tilanteen:\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-45-uiz87","href":"/_emdash/api/media/file/01KZ3GQM01G1JPQ7006YYSDV20.jpg"}]},{"_type":"image","_key":"key-47-m6p88","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQM01G1JPQ7006YYSDV20.jpg","url":"/_emdash/api/media/file/01KZ3GQM01G1JPQ7006YYSDV20.jpg"},"alt":""},{"_type":"block","_key":"key-52-kjrdc","style":"normal","children":[{"_type":"span","_key":"key-48-ylran","text":"\n"},{"_type":"span","_key":"key-49-2pcqt","text":" \n\n"},{"_type":"span","_key":"key-50-llckw","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-51-8ti7d","text":"Kuva: Simo"}]}]' WHERE id = '01KZ3GE4VQZF8MJF67AT2SVG5R';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-kyv8a","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQP8XS62X1QSDDAD3T96Q.jpg","url":"/_emdash/api/media/file/01KZ3GQP8XS62X1QSDDAD3T96Q.jpg"},"alt":""},{"_type":"block","_key":"key-10-3iyv7","style":"normal","children":[{"_type":"span","_key":"key-5-47zre","text":"Hyviä hommia"},{"_type":"span","_key":"key-6-04qd3","text":"Hallitus on viime vuosina ollut entistä luovempi kisaohjelmien suhteen ja tällä kertaa uutena tuttavuutena tuli kisa nimeltään Pull and Pull. Lajeja siis kaksi: rinnalleveto (ykkösmaksimi) sekä hyljesoutu (toistomaksimi).\n\n"},{"_type":"span","_key":"key-7-smyze","text":"Paikalla oli runsaasti tuttuja kasvoja, mutta joukossa oli myös uusia kisaajia, jotka tekivät debyyttinsä Pull & pull -kisassa.\n\n"},{"_type":"span","_key":"key-8-x6zyf","text":""}],"markDefs":[{"_type":"link","_key":"key-9-5o4fo","href":"/_emdash/api/media/file/01KZ3GQMVSDFVXHFN6SH63P67K.jpg"}]},{"_type":"image","_key":"key-11-f9yg9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQMVSDFVXHFN6SH63P67K.jpg","url":"/_emdash/api/media/file/01KZ3GQMVSDFVXHFN6SH63P67K.jpg"},"alt":""},{"_type":"block","_key":"key-29-odke1","style":"normal","children":[{"_type":"span","_key":"key-12-8w413","text":"Ylhäällä vasemmalta (d =debyytti): Olaf, Max, Valtteri (d), Mathilda, Ida (tuomari), Hector (d). Alhaalla vasemmalta: Jaakko ja Tuukka."},{"_type":"span","_key":"key-13-y2a8x","text":" \n\n"},{"_type":"span","_key":"key-14-mhqox","text":"Rinnalleveto\n","marks":["strong"]},{"_type":"span","_key":"key-15-gf2ke","text":"Vaikkakin kisalajeista tiedotettiin hyvissä ajoin, oli tekniikka ainakin miesosallistujilla hiukan hakusessa. Yksi kovimmista hauiskääntäjäkonkareista ei osallistunut (syy: mysteeri), mikä toisaalta antoi muille kilpailijoille mahdollisuuden kerätä vihdoin kaipaamiansa pisteitä. Lajissa ei huomioitu nostajien omaa painoa muutoin kuin tasatilanteessa kevyemmän eduksi. Esimerkiksi Max painoi Olafia 100 g vähemmän ja heidän ajauduttua tasatilanteeseen (90 kg), sai Max yhden pisteen enemmän.\n\n"},{"_type":"span","_key":"key-16-6txde","text":"Naisissa Mathilda oli ainoa osallistuja ja jos allekirjoittanut oikein muistaa, otti hän 4 tai 5 kertaa saman raudan (lähes) ylös - viimeisellä kerralla siis vasta onnistuneesti, joka tosin riitti voittoon! Ja jotta muille (lue miehille) ei aiheuteta enempää mielipahaa, ei kerrota kuinka tämä tulos on verrattuna miesten tuloksiin.\n\n"},{"_type":"span","_key":"key-17-21ecj","text":"Lajivoitosta miesten osalta tiukkaa kamppailua kävivät Jaakko ja Valtteri. Jaakon viimeinen paino 105 kg tuli suht mukavasti ylös ja näin paineet Valtterille lisääntyivät hänen siirtyessään nostolavalle nykimään 110 kiloa ylös. Mutta kuitenkin, harmittavasti(!!) Valtterin yritys kimmottaa paino katon kautta rinnalle päättyi huonosti ja tuloksena oli hylätty tulos "},{"_type":"span","_key":"key-18-ysnok","text":"(TULOKSET JUTUN LOPUSSA)\n","marks":["strong"]},{"_type":"span","_key":"key-19-litrf","text":"Tällä kertaa emme kiitä Yusifia editoinnista vaan nautimme raa''asta materiaalista!\n\n"},{"_type":"span","_key":"key-20-8qd70","text":"Viimeinen kierros rivessä on toisessa pätkässä.\n\n"},{"_type":"span","_key":"key-21-v10pv","text":"https://www.youtube.com/watch?v=XGnvbLX1Xio&feature=youtu.be\n\n"},{"_type":"span","_key":"key-22-0rsfr","text":" \n\n"},{"_type":"span","_key":"key-23-oc7tj","text":"https://www.youtube.com/watch?v=3EEWswiBeVE&feature=youtu.be\n\n"},{"_type":"span","_key":"key-24-ek5fi","text":"Hyljesoutu\n","marks":["strong"]},{"_type":"span","_key":"key-25-1gyz5","text":"Hyljesoutu oli toistokisa, jossa kisapaino riippui kisaajan iästä, pituudesta ja painosta. Hyljesoudussa maattiin vatsallaan penkillä ja vedettiin tanko ylös kohti rintaa/vatsan seutua. Hyväksyttyyn toistoon riitti nostaessa tangon kolahtaminen penkin metalliin ja laskiessa painojen osuessa maahan. Erot kisaajien välillä olivat pieniä. Esimerkiksi hyljesoudussa kolmen parhaan toistotulos oli 29, 28 ja 27. Maaginen 30 toistoa ei mennyt rikki tälläkään kertaa (viimeksi hyljesoutu oli lajina barbell challengessa, jolloin paras tulos oli 28 toistoa).\n\n"},{"_type":"span","_key":"key-26-wjhlt","text":"Kauden toisen kisan jälkeen Jaakko ja Mathilda ovat kärkipaikoilla.\n\n"},{"_type":"span","_key":"key-27-ggt8m","text":"https://www.youtube.com/watch?v=jKmikhlTmqc&feature=youtu.be\n\n"}],"markDefs":[{"_type":"link","_key":"key-28-mvm7p","href":"/_emdash/api/media/file/01KZ3GQN857HXPMPVEF0C2Q5EY.jpg"}]},{"_type":"image","_key":"key-30-1ri08","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQN857HXPMPVEF0C2Q5EY.jpg","url":"/_emdash/api/media/file/01KZ3GQN857HXPMPVEF0C2Q5EY.jpg"},"alt":""},{"_type":"block","_key":"key-36-2uef6","style":"normal","children":[{"_type":"span","_key":"key-31-qxesl","text":"\n"},{"_type":"span","_key":"key-32-lps2z","text":" \n\n"},{"_type":"span","_key":"key-33-y1vog","text":"KAUDEN TILANNE\n","marks":["strong"]},{"_type":"span","_key":"key-34-k6m5n","text":"MIEHET\n"}],"markDefs":[{"_type":"link","_key":"key-35-wh82e","href":"/_emdash/api/media/file/01KZ3GQNJCA14FMMC64VVHCFT9.jpg"}]},{"_type":"image","_key":"key-37-s919o","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQNJCA14FMMC64VVHCFT9.jpg","url":"/_emdash/api/media/file/01KZ3GQNJCA14FMMC64VVHCFT9.jpg"},"alt":""},{"_type":"block","_key":"key-41-jgxw2","style":"normal","children":[{"_type":"span","_key":"key-38-7jvbz","text":"\n"},{"_type":"span","_key":"key-39-p3vy2","text":"NAISET\n"}],"markDefs":[{"_type":"link","_key":"key-40-bw8j2","href":"/_emdash/api/media/file/01KZ3GQNZV21QMPHW4V5SCA3TH.jpg"}]},{"_type":"image","_key":"key-42-x6m1i","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQNZV21QMPHW4V5SCA3TH.jpg","url":"/_emdash/api/media/file/01KZ3GQNZV21QMPHW4V5SCA3TH.jpg"},"alt":""},{"_type":"block","_key":"key-48-iqdew","style":"normal","children":[{"_type":"span","_key":"key-43-auwnq","text":"\n"},{"_type":"span","_key":"key-44-vxakn","text":" \n\n"},{"_type":"span","_key":"key-45-e542z","text":"Teksti: Jaakko\n\n"},{"_type":"span","_key":"key-46-1inr9","text":"Video: Tuukka\n\n"},{"_type":"span","_key":"key-47-ork0f","text":"Kuva: Timo"}]}]' WHERE id = '01KZ3GE5ZPN847W18C536703NE';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-7datf","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg","url":"/_emdash/api/media/file/01KZ3GQB5SWVB0WFJQ1MYF6TEB.jpg"},"alt":""},{"_type":"block","_key":"key-14-q8be5","style":"normal","children":[{"_type":"span","_key":"key-5-aod01","text":"From the left: Simo, Yusif, Leo, Eero and Jaakko"},{"_type":"span","_key":"key-6-vnkuw","text":"The title is a bit misleading, because back measurements are not part of Voimaliiga. A competition in that direction in the works however... ;)\n\n"},{"_type":"span","_key":"key-7-jzjpo","text":"Now, to the topic: in April we had the 2018-2019 season''s second to last competition. Exercise of choice was chinups (max weight and reps) and the venue was Unisport''s Meilahti gym.\n\n"},{"_type":"span","_key":"key-8-d8nhq","text":"As per HYV tradition, there was a lot of smack talk and flexing before the competition. We saw some insane tactics in play which lead to our first-comer (in chinups) Simo to win the max weight competition, and Jaakko won the rep competition four years in a row now. Competition level was high, but unfortunately last year''s strongest chin-uppers did not participate. Maybe next year we''ll have a mega showdown? 😉\n\n"},{"_type":"span","_key":"key-9-b6o6j","text":"Enjoy the video!\n\n"},{"_type":"span","_key":"key-10-z2ax4","text":"https://www.youtube.com/watch?v=LHJWjgPJ61w&feature=youtu.be\n\n"},{"_type":"span","_key":"key-11-e2dji","text":"Results","marks":["strong"]},{"_type":"span","_key":"key-12-ggceb","text":" (red means failed lift)\n\n"}],"markDefs":[{"_type":"link","_key":"key-13-i0l31","href":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"}]},{"_type":"image","_key":"key-15-6n8y9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg","url":"/_emdash/api/media/file/01KZ3GQAG9PRR2D8MBQWJSXJVE.jpg"},"alt":""},{"_type":"block","_key":"key-19-94ldo","style":"normal","children":[{"_type":"span","_key":"key-16-p0zh1","text":"\n"},{"_type":"span","_key":"key-17-3du9u","text":"Voimaliiga points\n","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-18-li7qu","href":"http://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2019/05/PISTETILANNE-1.jpg"}]},{"_type":"image","_key":"key-20-b89r8","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg","url":"/_emdash/api/media/file/01KZ3GQATC0RRXECBQEPHWGT6K.jpg"},"alt":""},{"_type":"block","_key":"key-25-15nfl","style":"normal","children":[{"_type":"span","_key":"key-21-pgt8m","text":"\n"},{"_type":"span","_key":"key-22-ur9fl","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-23-prd1u","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-24-c7zks","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GE6YX470K981P2GRSGE9M';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-4-e2j7k","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg","url":"/_emdash/api/media/file/01KZ3GQA45YSJ55XSHYEHADJ78.jpg"},"alt":""},{"_type":"block","_key":"key-14-1yq3g","style":"normal","children":[{"_type":"span","_key":"key-5-x0tw4","text":"From the top left: Jaakko, Olaf, Tommi, Sonja, Valtteri, Max, Ville, Pasi. Alhaalla Yusif and Sami."},{"_type":"span","_key":"key-6-ou2w9","text":"In order for us to not lose the touch on the deadlift (there''s half a year gap between two powerlifting competitions), HYV organized a Push&Pull competition, where the we show off our benchpress and deadlift one rep maxes.\n\n"},{"_type":"span","_key":"key-7-po89m","text":"This time around we had 8 participants, and everybody had prior competition experience.\n\n"},{"_type":"span","_key":"key-8-n82ls","text":"Some notable lifts from the competitons are Olaf''s 160 kg bench and Yusif''s "},{"_type":"span","_key":"key-9-7emp9","text":"almost","marks":["em"]},{"_type":"span","_key":"key-10-1gjkz","text":" raw (no belt but sumo) 245 kg deadlift attempts. Check out the video to find out if they got it! ;)\n\n"},{"_type":"span","_key":"key-11-aly4u","text":"https://www.youtube.com/watch?v=hVWmCUIB_NI\n\n"},{"_type":"span","_key":"key-12-wcfqv","text":"Results:","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-13-uf7x2","href":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"}]},{"_type":"image","_key":"key-15-duqe4","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg","url":"/_emdash/api/media/file/01KZ3GQ9554XENM1FKBPDQQHHJ.jpg"},"alt":""},{"_type":"block","_key":"key-20-37dn7","style":"normal","children":[{"_type":"span","_key":"key-16-vd4q8","text":"\n"},{"_type":"span","_key":"key-17-z3j31","text":"Voimaliiga points\n\n","marks":["strong"]},{"_type":"span","_key":"key-18-e1q8q","text":"Gents\n\n"}],"markDefs":[{"_type":"link","_key":"key-19-z3mi0","href":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"}]},{"_type":"image","_key":"key-21-hd3it","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg","url":"/_emdash/api/media/file/01KZ3GQ9ECE7C24KKHNBAK7AZ8.jpg"},"alt":""},{"_type":"block","_key":"key-25-7as7h","style":"normal","children":[{"_type":"span","_key":"key-22-8y9zi","text":"\n"},{"_type":"span","_key":"key-23-ant22","text":"Ladies\n\n"}],"markDefs":[{"_type":"link","_key":"key-24-9jqk3","href":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"}]},{"_type":"image","_key":"key-26-lfre0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg","url":"/_emdash/api/media/file/01KZ3GQ9QQ0H2DYZ7573XMFXX2.jpg"},"alt":""},{"_type":"block","_key":"key-31-0ktgd","style":"normal","children":[{"_type":"span","_key":"key-27-rkuk6","text":"\n"},{"_type":"span","_key":"key-28-q2qyh","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-29-g2fik","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-30-8d3dt","text":"Video: Yusif"}]}]' WHERE id = '01KZ3GE914198780VVFA4YMWFJ';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-3-t94ax","style":"normal","children":[{"_type":"span","_key":"key-1-a4nc1","text":"This is a classic HYV competition, which is held at Otahalli (Unisport''s gym in Otaniemi). Even before the competition the Voimaliiga winner was already determined, as Yusif had a bunch of wins in the bag already. Similar case was for the ladies, as Sonja had a 12 point lead coming into the competition and was the only girl taking part in the final competition.\n\n"},{"_type":"span","_key":"key-2-16ehr","text":"Don''t want to bore you anymore with the long text, so we''ll condense the results and pick out the juiciest bits for you in a bullet list."}]},{"_type":"block","_key":"key-5-6raer","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-4-nxs0p","text":"Organizational stuff (extra monitor)"}]},{"_type":"block","_key":"key-7-6ncfy","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-6-ona2h","text":"Jyri and Sami being tough judges"}]},{"_type":"block","_key":"key-9-e2oq1","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-8-2m3va","text":"Yusif''s 200 kg squat attempt"}]},{"_type":"block","_key":"key-11-7tlk8","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-10-iu3o6","text":"Yusif''s 150 kg bench attempt"}]},{"_type":"block","_key":"key-13-zlncp","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-12-9cb9i","text":"Max''s insane deadlift progress to 250 kg"}]},{"_type":"block","_key":"key-15-cphnd","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-14-9a21k","text":"Yusif''s first 600 kg powerlifting total"}]},{"_type":"block","_key":"key-17-b4f0c","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-16-zogex","text":"Some heavy-ass deadlifts"}]},{"_type":"block","_key":"key-22-0a2g9","style":"normal","children":[{"_type":"span","_key":"key-18-bvcru","text":"Also make sure to watch the video (we thank Yusif for the editing job)!\n\n"},{"_type":"span","_key":"key-19-ba9qt","text":"https://youtu.be/wnpTAiL8kxY\n\n"},{"_type":"span","_key":"key-20-rx781","text":""}],"markDefs":[{"_type":"link","_key":"key-21-9p4go","href":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"}]},{"_type":"image","_key":"key-23-1idxb","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg","url":"/_emdash/api/media/file/01KZ3GQDY5WQ3B9DN5TKBVQ96V.jpg"},"alt":""},{"_type":"block","_key":"key-28-r5csg","style":"normal","children":[{"_type":"span","_key":"key-24-a30cx","text":"Results, men."},{"_type":"span","_key":"key-25-krlzq","text":" \n\n"},{"_type":"span","_key":"key-26-sekll","text":""}],"markDefs":[{"_type":"link","_key":"key-27-ytjk1","href":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"}]},{"_type":"image","_key":"key-29-8n97t","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg","url":"/_emdash/api/media/file/01KZ3GQF39EF9GAZSTY601F8ME.jpg"},"alt":""},{"_type":"block","_key":"key-33-hohv2","style":"normal","children":[{"_type":"span","_key":"key-30-bj44d","text":"Results, women"},{"_type":"span","_key":"key-31-69683","text":""}],"markDefs":[{"_type":"link","_key":"key-32-fjnkl","href":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"}]},{"_type":"image","_key":"key-34-d8r6g","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg","url":"/_emdash/api/media/file/01KZ3GQFQEC6PRTVH5WZ8GV14C.jpg"},"alt":""},{"_type":"block","_key":"key-39-qz2xs","style":"normal","children":[{"_type":"span","_key":"key-35-5upwc","text":"From top left Jaakko, Jyri, Valtteri, Max, Sonja, Tommi. Bottom row Yusif and Sami"},{"_type":"span","_key":"key-36-muqpv","text":" \n\n"},{"_type":"span","_key":"key-37-24e7o","text":"Voimaliiga final standings:\n\n"}],"markDefs":[{"_type":"link","_key":"key-38-42l5j","href":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"}]},{"_type":"image","_key":"key-40-u3syh","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg","url":"/_emdash/api/media/file/01KZ3GQH58MTWSH8PAHE32AB01.jpg"},"alt":""},{"_type":"image","_key":"key-44-4cl2x","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg","url":"/_emdash/api/media/file/01KZ3GQFDAMJ509NM18927K2EW.jpg"},"alt":""},{"_type":"block","_key":"key-51-9t4q5","style":"normal","children":[{"_type":"span","_key":"key-45-mvfhu","text":"\n"},{"_type":"span","_key":"key-46-sv6bq","text":" \n\n"},{"_type":"span","_key":"key-47-578j1","text":"Translated by: Yusif\n\n"},{"_type":"span","_key":"key-48-mxh0m","text":"Original text: Jaakko\n\n"},{"_type":"span","_key":"key-49-s4ai6","text":"Video: Yusif\n\n"},{"_type":"span","_key":"key-50-kfcuz","text":" "}]}]' WHERE id = '01KZ3GEA00YNT21ZPJYM0DGP88';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-adukw","style":"normal","children":[{"_type":"span","_key":"key-1-tyilj","text":"Toimituksessa on taidettu pariinkin otteeseen kirjoittaa, että seurastamme löytyy pari kovaa penkkipunnertajaa. Tästä tavasta täytyy luopua, sillä tieto vanhenee yllättävän nopeasti lukumäärän kasvaessa."}]},{"_type":"block","_key":"key-4-o9m2e","style":"normal","children":[{"_type":"span","_key":"key-3-ncr47","text":"Tämänkertainen juttu käsittelee konkarijäsentämme Ivania, joka kisasi tammikuussa klassisen penkkipunnerruksen SM-kisoissa Kaarinassa. Ivan kisasi sarjassa 105 kg (M40), kun taas aiemmin olemme tottuneet näkemään häntä 93 kilon sarjassa. Lihasmassaa on siis tullut mukavasti yläkropan työntäviin, sillä kisoista tarttui melkein mitalin lisäksi myös oma henkilökohtainen kisaennätys 170 kg."}]},{"_type":"block","_key":"key-6-kprxv","style":"normal","children":[{"_type":"span","_key":"key-5-a5742","text":"Tuo 170 kg nosto tuli toisella ja kolmanteen Ivan lastautti 175 kg, jolla olisi irronnut pronssinen mitali kevyemmän nostajan perusteella. Tuo kyseinen rauta on kuulemma parikin kertaa tullut nostettua viime vuoden puolella, joten potentiaalia riittää edelleen. Lopputulemana siis 4. sija. Onnittelut Ivanille!"}]},{"_type":"block","_key":"key-8-tvr5b","style":"normal","children":[{"_type":"span","_key":"key-7-2dayw","text":"Tiedoksi lukijoille, että seuramme järjestää sotilaspenkkipunnerruskisan kuluvana keväänä, joten toivottavasti tästä saitte aavistuksen motivaatio treenata lisää 😉"}]},{"_type":"image","_key":"key-9-unvyq","asset":{"_type":"reference","_ref":"2113","url":"/_emdash/api/media/file/01KZ3GR7PZX6Q5BNZGDKETC95S.jpeg"},"alt":"","caption":"Itse nostaja keskellä ja huoltajat vieressä"},{"_type":"block","_key":"key-11-8988e","style":"normal","children":[{"_type":"span","_key":"key-10-by6tc","text":"Alla linkki / video Ivanin 170 kg nostoon."}]},{"_type":"block","_key":"key-15-ujlq6","style":"normal","children":[{"_type":"span","_key":"key-12-rngw9","text":"Tuloksia löytyy täältä:\n"},{"_type":"span","_key":"key-14-cn8rq","text":"https://www.suomenvoimanostoliitto.fi/Tulosarkisto/rav-klassinen-penkkipunnerrus-littoinen-17-19-1-2025/","marks":["key-13-f0cgs"]}],"markDefs":[{"_type":"link","_key":"key-13-f0cgs","href":"https://www.suomenvoimanostoliitto.fi/Tulosarkisto/rav-klassinen-penkkipunnerrus-littoinen-17-19-1-2025/"}]},{"_type":"embed","_key":"key-16-z6den","url":"https://www.youtube.com/watch?v=xYo3_xOqoFE&t=1h16m50s","provider":"youtube","html":"<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=xYo3_xOqoFE&amp;t=1h16m50s\n</div></figure>"},{"_type":"block","_key":"key-18-2mjaq","style":"normal","children":[{"_type":"span","_key":"key-17-rcy9f","text":"Teksti: Jaakko"}]}]' WHERE id = '01KZ3GERYFDDRX2K6450Z0XQM3';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-pbaap","asset":{"_type":"reference","_ref":"2125","url":"/_emdash/api/media/file/01KZ3GRA4N6X7H0V05287QAJTG.jpeg"},"alt":"","caption":"Jälleen saatu kova kisaporukka kasaan!"},{"_type":"block","_key":"key-3-ud3wm","style":"normal","children":[{"_type":"span","_key":"key-2-amtvo","text":"Jos nyt tarkkoja ollaan, ei perinteitä kunnioitettu, sillä voimanostokisat järjestetään yleensä joulun alla ja keväisin. Tärkeintä kuitenkin oli, että kisattiin!"}]},{"_type":"block","_key":"key-5-0k5rm","style":"normal","children":[{"_type":"span","_key":"key-4-y7289","text":"Mukana oli monia ensikertalaisia ja myös seuran ulkopuolisia nostajia. Yhteensä kisaajia oli 7 kappaletta: 3 naista ja 4 miestä. Näin ollen kisasta saatiin sopivan kilpailuhenkinen."}]},{"_type":"block","_key":"key-7-ry3ar","style":"normal","children":[{"_type":"span","_key":"key-6-21mmi","text":"Kisassa ei ollut painoluokkia vaan sijoitukset lasketaan IPF:n hyväksymillä Goodlifts-kertoimilla."}]},{"_type":"block","_key":"key-9-f2ju4","style":"normal","children":[{"_type":"span","_key":"key-8-tlubm","text":"Taulukossa näette tulokset. Kiitos osallistujille ja onnittelut omien ennätysten tekijöille!"}]},{"_type":"image","_key":"key-10-ev8yg","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GR97W31HQMSERFEVTQTX4.jpg","url":"/_emdash/api/media/file/01KZ3GR97W31HQMSERFEVTQTX4.jpg"},"alt":""},{"_type":"image","_key":"key-11-cvpki","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GR9N70NPVTSJE3PP2HEE2.jpg","url":"/_emdash/api/media/file/01KZ3GR9N70NPVTSJE3PP2HEE2.jpg"},"alt":""},{"_type":"block","_key":"key-13-b9fiz","style":"normal","children":[{"_type":"span","_key":"key-12-9monc","text":"Seuraava kisa on leuanveto, jossa kisataan sekä lisänpainoilla (ykkösmaksimi) että kehonpainolla (toistomaksimi). Tiedotamme tästä erikseen!"}]},{"_type":"block","_key":"key-16-jzppj","style":"normal","children":[{"_type":"span","_key":"key-14-1equh","text":"Teksti ja kuvat","marks":["strong"]},{"_type":"span","_key":"key-15-xzx40","text":": Jaakko O"}]}]' WHERE id = '01KZ3GESZBVM67NAFXAAKF9GS8';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-sya5e","asset":{"_type":"reference","_ref":"2132","url":"/_emdash/api/media/file/01KZ3GRAP4JBX0NN57T3F96EXA.jpeg"},"alt":"","caption":"Henkilöt vasemmalta ylhäältä: Voima-Jyri, Jaakko, Johannes P, Riku A, Johannes V, Prässi-Timo. Alhaalla Tuukka ja Nghia."},{"_type":"block","_key":"key-3-55n89","style":"normal","children":[{"_type":"span","_key":"key-2-qlub0","text":"Tällä kertaa leuanvetokisan jälkeinen siivoustarve oli maltillinen. Sen verran herrasmiehiä oli kisaajat muutaman vuoden takaiseen mittelöön nähden."}]},{"_type":"block","_key":"key-5-7rqki","style":"normal","children":[{"_type":"span","_key":"key-4-26bzp","text":"Joka tapauksessa, perinteinen leuanvetokisa järjestettiin maaliskuun ensimmäisenä päivänä ja osanottajia oli kuusi kappaletta. Tämä tarkoittaa, että mitalia ei ollut kaikille jaossa."}]},{"_type":"block","_key":"key-7-bl892","style":"normal","children":[{"_type":"span","_key":"key-6-657jl","text":"Seuran ulkopuolisia kisaajia oli kolme, joista yksi osallistui vain toistokisaan. Joka tapauksessa kyseessä oli yksi seuran kovatasoisimmista kisoista."}]},{"_type":"block","_key":"key-9-us47x","style":"normal","children":[{"_type":"span","_key":"key-8-cznyu","text":"Lisäpainokisan voitti Johannes tuloksella 73 kg, jolla taidettiin yltään seuran top 5 tuloksiin (community notes pending, joten tähän voi jotkut kaivaa arkistojen kätköistä oikean tiedon). Myös 80 kg rikkominen oli lähellä - seuraavaan kertaan siis! Muita mainittavan arvoisia suorituksia oli Nghian henkilökohtainen ennätys 33 kiloa, joka tuli helposti ylös jo toisella kierroksella."}]},{"_type":"block","_key":"key-11-ix5ju","style":"normal","children":[{"_type":"span","_key":"key-10-o9iat","text":"Toistokisan vei Jaakko 28 toistolla, mutta Johannes V ylsi lähes samaan toistomäärään, mutta kisakokemuksen puutteen vuoksi leukavirheitä tuli jonkin verran."}]},{"_type":"block","_key":"key-13-2v7h7","style":"normal","children":[{"_type":"span","_key":"key-12-uggpw","text":"Kisat olivat kaksi erillistä kisaa, joten molemmista jaettiin pisteet. Alla taulukossa tuloksia."}]},{"_type":"block","_key":"key-15-ma62k","style":"normal","children":[{"_type":"span","_key":"key-14-08rd8","text":"Lisäksi muutamia suorituksia voitte käydä katsomassa HYV:n Instagram-sivuilla (linkki alla)."}]},{"_type":"block","_key":"key-18-bxkzu","style":"normal","children":[{"_type":"span","_key":"key-17-qx1mr","text":"https://www.instagram.com/hyvoima/","marks":["key-16-i1ibs"]}],"markDefs":[{"_type":"link","_key":"key-16-i1ibs","href":"https://www.instagram.com/hyvoima/"}]},{"_type":"image","_key":"key-19-08tu9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GRBYE3EXVMJV9P486DAXH.jpg","url":"/_emdash/api/media/file/01KZ3GRBYE3EXVMJV9P486DAXH.jpg"},"alt":""},{"_type":"block","_key":"key-21-2g4ig","style":"normal","children":[{"_type":"span","_key":"key-20-523uw","text":"Teksti: Jaakko O"}]}]' WHERE id = '01KZ3GEV703D9MEE2G5QSJMS8D';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-f7y8c","asset":{"_type":"reference","_ref":"2149","url":"/_emdash/api/media/file/01KZ3GRD9V5EDMR33EXEEXZ4N9.jpeg"},"alt":""},{"_type":"block","_key":"key-3-jqt48","style":"normal","children":[{"_type":"span","_key":"key-2-mj3on","text":"Aikainen kevät oli tänä vuonna saaneet penkkikarhut heräämään ja taidettiin nähdä kaikkien aikojen suurin määrä osallistujia HYV:n historiassa. Tämä vaatikin jo kisajärjestelijältä äärimmäistä tarkkuutta, jotta aikataulussa pysyttäisiin."}]},{"_type":"block","_key":"key-5-7x8y8","style":"normal","children":[{"_type":"span","_key":"key-4-2cz0c","text":"Taisin muutama vuosi sitten kirjoittaa sotilaspenkin olevan miesvaltainen ala ja tällä kertaa se oli myös niin, sillä naisten sarjassa oli vain yksi kilpailija – tosin erittäin kova sellainen! Loput 17 kpl olivat siis miehiä, joten näimme tiukkoja ja todella kovia suorituksia varsinkin kärkipaikoilla."}]},{"_type":"block","_key":"key-7-55slk","style":"normal","children":[{"_type":"span","_key":"key-6-tc2mx","text":"Suurimmat raudat olivat yli 150 kiloa (kaikki onnistuneita nostoja) ja kyseisiä nostajia oli kolme kappaletta: Gergo, Lari ja Matti. Käytämme IPF:n hyväksymää Goodlifts pisteytysmenetelmää, jossa huomioidaan nostajan oma paino. Vaikka Matti vastasi suurimmista raudoista (157,5 kg), sijoittui hän kolmanneksi, sillä Gergo ja Lari olivat kevyempiä ja vain 5 kg ja 2,5 kg Mattia jäljessä."}]},{"_type":"block","_key":"key-9-2bc1o","style":"normal","children":[{"_type":"span","_key":"key-8-e69q3","text":"Toistokisassa nostettavat painot pyöristetään kehon painosta ylempään 2,5 kiloon. Naisilla toistopaino on 2/3 kehonpainosta, mutta pyöristys tapahtuu samalla tavalla. Joillekin saattoi olla ykkösmaksimikisa sen verran rankka, että toistokisa jäi välistä: ts. toistokisassa osallistujia oli 15 kpl."}]},{"_type":"block","_key":"key-11-hik0c","style":"normal","children":[{"_type":"span","_key":"key-10-wb5rb","text":"Maaginen 20 toiston raja rikkoutui 5 nostajalla, joista 4 kpl oli tasan 20 toistoa. Tasatilanteessa se nostaja voittaa, jolla kehon painon sekä toistopainon erotus on suurempi. Muutoin sijoitus perustuu puhtaasti toistomäärään. Olaf edusti HYV:n vanhaa kaartia ja voitti toistokisan 22 toistolla."}]},{"_type":"block","_key":"key-13-g9rnw","style":"normal","children":[{"_type":"span","_key":"key-12-45bf7","text":"Lisää materiaalia löytyy HYV:n instagram tililtä:"}]},{"_type":"block","_key":"key-17-f6244","style":"normal","children":[{"_type":"span","_key":"key-15-86e8j","text":"https://www.instagram.com/hyvoima/","marks":["key-14-1cdel"]}],"markDefs":[{"_type":"link","_key":"key-14-1cdel","href":"https://www.instagram.com/hyvoima/"},{"_type":"link","_key":"key-16-rcs8y","href":""}]},{"_type":"block","_key":"key-19-km5n8","style":"normal","children":[{"_type":"span","_key":"key-18-ikhy8","text":"Seuraava kisa on toukokuussa ja on lajiltaan voimanosto sis. kyykyn, penkin ja maastanoston maksimiykköset. Tiedotamme tästä myöhemmin!"}]},{"_type":"image","_key":"key-20-mz7n9","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GRCE2K0PDNFRJM8ASXEVK.jpg","url":"/_emdash/api/media/file/01KZ3GRCE2K0PDNFRJM8ASXEVK.jpg"},"alt":""},{"_type":"image","_key":"key-21-934b0","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GRE11A75028FR8XAQRBEE.jpg","url":"/_emdash/api/media/file/01KZ3GRE11A75028FR8XAQRBEE.jpg"},"alt":""},{"_type":"image","_key":"key-22-3x8wt","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GRCWMV7NSRE66MBPC0RMS.jpg","url":"/_emdash/api/media/file/01KZ3GRCWMV7NSRE66MBPC0RMS.jpg"},"alt":""},{"_type":"block","_key":"key-24-putik","style":"normal","children":[{"_type":"span","_key":"key-23-jtvz4","text":"Teksti: Jaakko O"}]}]' WHERE id = '01KZ3GEWF7D0AS8KCE0JN47FVG';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-ml364","asset":{"_type":"reference","_ref":"2170","url":"/_emdash/api/media/file/01KZ3GRFENPF1E13X3V1ASNDSZ.jpeg"},"alt":"","caption":"Kuvassa vasemmalta: Viljami, Lucas (maailman vahvin HYViläinen per 5/2025), Daniel, Gergo, Max, Jaakko (ylh.) ja Juho (alh.)"},{"_type":"block","_key":"key-3-zi04n","style":"normal","children":[{"_type":"span","_key":"key-2-mohmi","text":"Voimanostokisan osallistujamäärä oli penkkikisaa vähäisempi. Liekkö hermoston palautuminen viedä tovin pidempään…"}]},{"_type":"block","_key":"key-5-g9tqx","style":"normal","children":[{"_type":"span","_key":"key-4-8nz1j","text":"Joka tapauksessa rautaa nostettiin kuitenkin runsaasti ja mukana oli uusia osallistujia sekä yksi ”wanha” jäsen Max. Voisi siis puhua jopa sukupolvien taistosta."}]},{"_type":"block","_key":"key-7-fexr0","style":"normal","children":[{"_type":"span","_key":"key-6-vvrqn","text":"Gergo osoittautui tällä kertaa vahvimmaksi mm. kovan penkkinsä ansiosta, mutta Daniel kevyempänä (ja myös vahvalla penkillä) haastoi Gergoa erinomaisesti. Ensimmäisen lajin eli kyykyn jälkeen kaikki oli mahdollista, mutta penkissä Gergo otti hiukan kaulaa. Danielin voimat olivat hiukan menneet tiukkaan kyykkyyn, jossa viimeinen nosto olikin ”vähintään” 190 kiloa (20 kg kiekot painavat todellisuudessa 20,4 kg). Valitettavasti syvyys ei ollut riittävä."}]},{"_type":"block","_key":"key-9-cezac","style":"normal","children":[{"_type":"span","_key":"key-8-0j2sc","text":"Maastavedossa ennätyksiään tekivät Viljami (185 kg) ja Gergo (222,5 kg). Maxin 200 kilon nosto oli RPE ”erittäin matala”, mutta ehkä kisa olikin valmistava johonkin suureen koitokseen."}]},{"_type":"image","_key":"key-10-m3knt","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GRG03MP6HW0H4ZK762SR9.jpg","url":"/_emdash/api/media/file/01KZ3GRG03MP6HW0H4ZK762SR9.jpg"},"alt":""},{"_type":"block","_key":"key-12-g7903","style":"normal","children":[{"_type":"span","_key":"key-11-hdzmk","text":"Käy katsomassa Instagramista kaikki kovimmat nostot!"}]},{"_type":"block","_key":"key-15-pjght","style":"normal","children":[{"_type":"span","_key":"key-14-iynas","text":"https://www.instagram.com/p/DKHQKJMtH29/?utm_source=ig_web_copy_link&igsh=MzRlODBiNWFlZA==","marks":["key-13-pin8m"]}],"markDefs":[{"_type":"link","_key":"key-13-pin8m","href":"https://www.instagram.com/p/DKHQKJMtH29/?utm_source=ig_web_copy_link&igsh=MzRlODBiNWFlZA=="}]},{"_type":"block","_key":"key-17-4owin","style":"normal","children":[{"_type":"span","_key":"key-16-xt7jh","text":"Teksti: Jaakko O"}]}]' WHERE id = '01KZ3GEYVFYM0STAPE6NQ9E9VM';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-k3o6i","asset":{"_type":"reference","_ref":"2183","url":"/_emdash/api/media/file/01KZ3GRHS82482BP2VMEPAZBX8.jpg"},"alt":"","caption":"Vasemmalta ylhäältä: Max, Joel, Jyri (tuomari), Tuukka, Jaakko (tuomari) ja Olavi. Alhaalla voittaja Julius."},{"_type":"block","_key":"key-3-jnf65","style":"normal","children":[{"_type":"span","_key":"key-2-l8ro9","text":"Elikkäs elikkäs, tietää että joulu lähestyy kun Otahallilla jyrisee niin perhanasti ja rakenteiden peruskorjaus lähenee kirjanpidon poistoja nopeammin."}]},{"_type":"block","_key":"key-5-8k8a0","style":"normal","children":[{"_type":"span","_key":"key-4-ae9is","text":"Osanottajia oli tällä kertaa viisi kappaletta, joista kolme oli nk. \"konkaria\" ja kaksi uudehkoja kasvoja yhdistyksen toiminnassa. Lienee jo aika sanoa, että uusi polvi alkaa ottaa haltuunsa kovempia rautoja. :) Nostojen osalta nähtiin kuitenkin henkilökohtaisia PR:iä ja pitää muistaa, että Otahallin 20,4 kg kiekot tekevät lukemista varmuudella ennätyksiä (HUOM! kisatuloksissa kuitenkin painot laskettiin tasan 20 kg arvoisina)."}]},{"_type":"block","_key":"key-7-to2l3","style":"normal","children":[{"_type":"span","_key":"key-6-dk4d6","text":"Kisa eteni melko nopeasti eli jäähtymistä ei päässyt tapahtumaan. Allekirjoittaneen nähtyä Juliuksen lämmittelyt kyykyssä, alkoi hänen kertoimet lähestyä ykköstä melko nopeasti. Sen verran vakuuttavaa toimintaa oli ja lopputuloksena olikin ylivoimainen voitto."}]},{"_type":"block","_key":"key-9-px3lp","style":"normal","children":[{"_type":"span","_key":"key-8-zjao7","text":"Merkittävinä mainintoina päivästä olivat Maxin kisakyykkyennätys 180 kg, Olavin ilmestyminen kisaan, Tuukan kehonpaino, Juliuksen 205 kg kyykky (= \"200 klubi\") sekä Joelin 3x kehonpaino maastavetoon (kisan ulkopuolella 4. nostona). Tiedoksi, että näitä vähintään 3x kehonpainonostajia oli entuudestaan vain 1 kpl (=Yusif) HYV jäsenistössä."}]},{"_type":"block","_key":"key-11-qpl3t","style":"normal","children":[{"_type":"span","_key":"key-10-molfx","text":"Instagramissa pääsette tarkastelemaan muutamia nostoja ao. linkistä. Tulokset myös alla."}]},{"_type":"block","_key":"key-14-frfwr","style":"normal","children":[{"_type":"span","_key":"key-13-p30aj","text":"https://www.instagram.com/p/DSNwReujRgY/?img_index=1","marks":["key-12-68uso"]}],"markDefs":[{"_type":"link","_key":"key-12-68uso","href":"https://www.instagram.com/p/DSNwReujRgY/?img_index=1"}]},{"_type":"image","_key":"key-15-ohn6q","asset":{"_type":"reference","_ref":"2186","url":"/_emdash/api/media/file/01KZ3GRJ859DWQRR7YEZ8F4WMM.jpg"},"alt":"","caption":"Julius ja vähintään 270 kg"},{"_type":"image","_key":"key-17-d58p5","asset":{"_type":"reference","_ref":"2181","url":"https://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2025/12/Tulokset-1024x168.jpg"},"alt":""},{"_type":"block","_key":"key-19-jys0b","style":"normal","children":[{"_type":"span","_key":"key-18-woho3","text":"Teksti ja kuvat: Jaakko O"}]}]' WHERE id = '01KZ3GF0674AF588Z2XQZ1GVY3';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-c6idx","style":"normal","children":[{"_type":"span","_key":"key-1-k228p","text":"Otsikon mukaisesti olisi tehnyt hyvät tuotot jos olisi aloittanut kultaan sijoittamisen. Juha on näin tehnyt, mutta aavistuksen verran eri muodossa - ei louhimalla vaan punnertamalla. Nyt jos seuran jäseniä kiinnostaa rikkoa ennätyksiä, lienee syytä aloittaa, sillä kirittävää Juhan suorituksiin on sen verran. Kisakokemusta on nimittäin jo reilusti yli 200 kisasta."}]},{"_type":"block","_key":"key-4-ijapz","style":"normal","children":[{"_type":"span","_key":"key-3-2l93u","text":"Juha Koivisto - voisiko kutsua HYV:n \"penkkikeisariksi\" - oli kisaamassa SM-kisoissa klassisen penkin muodossa. Painoluokkana oli tuttu 93 kg ja ikäluokka M70. Tuloksena 1. sija tuloksella 140 kg."}]},{"_type":"image","_key":"key-5-scv1t","asset":{"_type":"reference","_ref":"2198","url":"/_emdash/api/media/file/01KZ3GRKK1VWK4DAE47QBW6W9C.png"},"alt":"","caption":"Juha kuvassa (tietenkin) keskellä"},{"_type":"block","_key":"key-7-6okyq","style":"normal","children":[{"_type":"span","_key":"key-6-vehb6","text":"Rikkinäistä puhelinta välttääkseni, lisätään tähän suoraan kisaraportti itse mestarilta:","marks":["strong"]}]},{"_type":"block","_key":"key-9-kxl4p","style":"normal","children":[{"_type":"span","_key":"key-8-yc0o1","text":"Kisaan valmistautuminen oli hyvin tavanomainen eli 4-5 viikon ajan lisäystä niin kisa-stop-painoihin kuin ilman stoppia tehtäviin penkkitreeneihin. Ilman stoppia nostot oli joka treenissä 150-155 kg ja kisastoppien kanssa 140-145kg."}]},{"_type":"block","_key":"key-12-bpldq","style":"normal","children":[{"_type":"span","_key":"key-10-zbtkd","text":"Harjoitusmuotona oli \"Bulgaarialainen penkki\", jonka olen modifioinut Bulgaarialaisen Ivan Adadjiev:in painonnosto-ohjelmista sekä 5 sarjaa toistoina 3-6 toistoa.\n"},{"_type":"span","_key":"key-11-l7cjc","text":"Ennakko-odotus kisatulokselle oli 140-145 kg välillä. Kisan päätavoite oli SM kulta, jolla saa liput MM maajoukkueeseen. Omassa paino- ja ikäluokassa nostajia oli 5. (tulokset liitteessä). Aloituspainoksi valitsin 135 kg, ns. \"varmat raudat\". Olin ajatellut korotukseksi 2. nostoon 140 kg, mutta SVNL:n uuden tulostaulukon monimutkaisuuden vuoksi kilpailutilanteen arvioinnissa meni liikaa aikaa enkä ehtinyt viedä korotuslappua ajoissa, josta seurasi vakiokorotus +2.5 kg ja toisen noston kuormaus 137.5 kg. Halusin varmistaa voiton pyytämällä 3. nostoon 140 kg kuormauksen vaikka potentiaalia olisi ollut 142.5 kg nostoon. Nosto oli helppo, mutta kuitenkin vähällä oli, ettei 2. rankattu nostaja mennyt viimeisellä 142.5 kg nostollaan ohi."}]},{"_type":"block","_key":"key-15-oco07","style":"normal","children":[{"_type":"span","_key":"key-13-3sag6","text":"\n"},{"_type":"span","_key":"key-14-eecbh","text":"Klassisen penkin M kisat on nyt takana ja treenit kohti Puolassa tapahtuvaa MM kisaa on aloitettu. Seuraavat kisat on kuitenkin varustepenkin SM kisat Tampereella 22.2.2026."}]},{"_type":"block","_key":"key-18-qzi9r","style":"normal","children":[{"_type":"span","_key":"key-16-cowu1","text":"\n"},{"_type":"span","_key":"key-17-d2zhm","text":"Kiitokset vielä Jaakolle kisoihin ilmoittamisesta ja HYV:lle, että voin edustaa seuraa!"}]},{"_type":"block","_key":"key-20-c84cn","style":"normal","children":[{"_type":"span","_key":"key-19-ib62e","text":"TULOKSET","marks":["strong"]}]},{"_type":"image","_key":"key-21-57ssb","asset":{"_type":"reference","_ref":"2196","url":"/_emdash/api/media/file/01KZ3GRJSKK8KV215Z3JNYQQQJ.jpg"},"alt":""},{"_type":"block","_key":"key-24-ujes6","style":"normal","children":[{"_type":"span","_key":"key-22-eqmle","text":"SUORITUKSET","marks":["strong"]},{"_type":"span","_key":"key-23-cjy7j","text":" alla videoilla (kaikki hyväksyttyjä)"}]},{"_type":"block","_key":"key-26-jm60w","style":"normal","listItem":"number","level":1,"children":[{"_type":"span","_key":"key-25-4huem","text":"nosto 135 kg."}]},{"_type":"embed","_key":"key-27-2c5j1","url":"https://www.youtube.com/watch?v=0fUIzxR0e0s&t=1369s","provider":"youtube","html":"<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=0fUIzxR0e0s&amp;t=1369s\n</div></figure>"},{"_type":"block","_key":"key-29-rarmu","style":"normal","children":[{"_type":"span","_key":"key-28-0fv01","text":"2. nosto 137,5 kg"}]},{"_type":"embed","_key":"key-30-z8oro","url":"https://www.youtube.com/watch?v=0fUIzxR0e0s&t=2266s","provider":"youtube","html":"<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=0fUIzxR0e0s&amp;t=2266s\n</div></figure>"},{"_type":"block","_key":"key-32-7izlb","style":"normal","children":[{"_type":"span","_key":"key-31-rcnjy","text":"3. nosto 140 kg"}]},{"_type":"embed","_key":"key-33-t0ma8","url":"https://www.youtube.com/watch?v=0fUIzxR0e0s&t=3092s","provider":"youtube","html":"<figure class=\"wp-block-embed is-type-video is-provider-youtube wp-block-embed-youtube wp-embed-aspect-16-9 wp-has-aspect-ratio\"><div class=\"wp-block-embed__wrapper\">\nhttps://www.youtube.com/watch?v=0fUIzxR0e0s&amp;t=3092s\n</div></figure>"},{"_type":"block","_key":"key-35-qg1ts","style":"normal","children":[{"_type":"span","_key":"key-34-0jvds","text":"Teksti: Jaakko O ja Juha K"}]}]' WHERE id = '01KZ3GF1D0K5NKH9QDD64AS29A';
UPDATE "ec_posts" SET "content" = '[{"_type":"block","_key":"key-2-57nbd","style":"normal","children":[{"_type":"span","_key":"key-1-43y9e","text":"Sen verran erikoisia lajeja oli vuorossa Meilahdessa käytävässä kisassa, että rikottiin ennätyksiä osallistujamäärissä. Kisaajia oli kaksi: Kalle ja allekirjoittanut Jaakko (kuvassa Kalle vasemmalla)."}]},{"_type":"image","_key":"key-3-tdhgz","asset":{"_type":"reference","_ref":"2206","url":"/_emdash/api/media/file/01KZ3GRM47C3JMFFD9489M0449.png"},"alt":"","caption":"Kalle ja Jaakko"},{"_type":"block","_key":"key-5-xaw73","style":"normal","children":[{"_type":"span","_key":"key-4-5t8qg","text":"Käydään kisalajit (5 kpl) tässä lyhyesti läpi."}]},{"_type":"block","_key":"key-7-mkl23","style":"normal","children":[{"_type":"span","_key":"key-6-sa3zl","text":"1. Farmarikävely, 30 s mahdollisimman pitkä matka. Painoa oman painon verran pyöristäen lähimpiin painoihin."}]},{"_type":"block","_key":"key-9-oypuu","style":"normal","children":[{"_type":"span","_key":"key-8-sk3ra","text":"2. Vauhditon pituushyppy (3 yritystä)"}]},{"_type":"block","_key":"key-11-r93qo","style":"normal","children":[{"_type":"span","_key":"key-10-bq7t6","text":"3. Kelkan veto ja työntö (painona kelkka + oma paino)"}]},{"_type":"block","_key":"key-13-0kmrh","style":"normal","children":[{"_type":"span","_key":"key-12-x98yl","text":"4. Käsilläseisonta seinää vasten"}]},{"_type":"block","_key":"key-15-roh4u","style":"normal","children":[{"_type":"span","_key":"key-14-eb2zw","text":"5. Kahden käden roikunta (ote pysyttävä samana)"}]},{"_type":"block","_key":"key-17-x4sn4","style":"normal","children":[{"_type":"span","_key":"key-16-aib91","text":"Pisteet: kunkin lajin paras saa 100 ja muut sitten tulos / maksimi * 100. Kaikilla lajeilla sama painotus."}]},{"_type":"block","_key":"key-20-dvc45","style":"normal","children":[{"_type":"span","_key":"key-19-mwk2j","text":"Kisa oli erittäin tasainen. Kalle vei farmarikävelyn sekä kelkkaosuuden ja vauhditon pituushyppy oli käytännössä tasatuloksilla. \"Sitkeyshaasteissa\" eli käsilläseisonnossa ja roikunnassa Jaakko otti sen verran kaulaa, että lopulta voitto varmistui niillä."}]},{"_type":"block","_key":"key-22-ycl1p","style":"normal","children":[{"_type":"span","_key":"key-21-6814v","text":"Tulokset näette alla. Videot ja kuva Instagramissa."}]},{"_type":"block","_key":"key-25-hqyut","style":"normal","children":[{"_type":"span","_key":"key-24-8ca9x","text":"https://www.instagram.com/p/DUv5xoNDULb/?img_index=1","marks":["key-23-zni4k"]}],"markDefs":[{"_type":"link","_key":"key-23-zni4k","href":"https://www.instagram.com/p/DUv5xoNDULb/?img_index=1"}]},{"_type":"image","_key":"key-26-9ppy0","asset":{"_type":"reference","_ref":"2208","url":"/_emdash/api/media/file/01KZ3GRMNZ887GY4NX4P9H727P.png"},"alt":""},{"_type":"block","_key":"key-28-inkxq","style":"normal","children":[{"_type":"span","_key":"key-27-4il99","text":"Teksti ja kuvat: Jaakko O"}]}]' WHERE id = '01KZ3GF2EGCZ1HJ7WR2D6Z1M5N';
UPDATE "ec_posts" SET "content" = '[{"_type":"image","_key":"key-1-coxkb","asset":{"_type":"reference","_ref":"2223","url":"https://hyvoimailijat.com/Wordpress/wordpress/wp-content/uploads/2026/03/Ryhmakuva-1024x768.jpeg"},"alt":"","caption":"Vasemmalta: Max, Riku, Jyri, Aava, Jaakko ja Tuukka"},{"_type":"block","_key":"key-3-5omuw","style":"normal","children":[{"_type":"span","_key":"key-2-nck7l","text":"Heikosta markkinointikumppanista huolimatta kisa saatiin aikaiseksi yhteensä 5 kisaajan voimin. Mukana olivat nk. \"usual suspectit\", joten sijoituksista oli jonkinlaista käryä etukäteen."}]},{"_type":"block","_key":"key-5-xiols","style":"normal","children":[{"_type":"span","_key":"key-4-2gjzo","text":"Kisa siis koostui sekä ykkösmaksimista että toistomaksimista. Molemmat sotilaspenkkityylillä eli jalat ilmassa. Miesten kisan vie molemmissa lajeissa Riku tuloksilla 135 kg ja 16 toistoa. Aava oli ainoa naiskisaaja, mutta jos en väärin muista, pitäisi hänen tuloksensa olla yhdistyksemme ennätys: Aavan punnersi 77,5 kg kevyesti ylös ja varoja näytti olevan 80 kiloonkin, mutta toistokisaan säästeltiin \"hiukan\". Toistokisassa Aava päihitti kaikki mieskisaajat 23 toistolla (naisilla kisapaino 2/3 omasta painosta), joka taitaa olla myös kisaennätys. Vaikuttavaa tästä tekee se, että vuoden takaisessa kisassa Aava nosti 60 kiloa eli parannusta tuli 17,5 kg ykkösmaksimiin."}]},{"_type":"block","_key":"key-7-htins","style":"normal","children":[{"_type":"span","_key":"key-6-qh2lb","text":"Tulokset alla ja linkki Instagramiin, jossa näkyy kisasuorituksia."}]},{"_type":"block","_key":"key-10-9tla2","style":"normal","children":[{"_type":"span","_key":"key-9-ik79j","text":"https://www.instagram.com/p/DWb89L-DZRS/?img_index=1","marks":["key-8-s1eqz"]}],"markDefs":[{"_type":"link","_key":"key-8-s1eqz","href":"https://www.instagram.com/p/DWb89L-DZRS/?img_index=1"}]},{"_type":"block","_key":"key-12-vhcrt","style":"normal","children":[{"_type":"span","_key":"key-11-rlzg9","text":"Seuraava kisa on sitten leuanveto ja josko sinne saisimme muutaman ottelijan enemmän :)"}]},{"_type":"image","_key":"key-13-rhwge","asset":{"_type":"reference","_ref":"2217","url":"/_emdash/api/media/file/01KZ3GRN5Q6K8Y6VJCQ18PJR04.png"},"alt":""},{"_type":"image","_key":"key-14-lnma6","asset":{"_type":"reference","_ref":"2219","url":"/_emdash/api/media/file/01KZ3GRNGGXD5EH2M1VS4R86KG.png"},"alt":""},{"_type":"image","_key":"key-15-3saf7","asset":{"_type":"reference","_ref":"2221","url":"/_emdash/api/media/file/01KZ3GRNTRTNT8CZPD7SECW8AQ.png"},"alt":""}]' WHERE id = '01KZ3GF3MPQ66HFMDHTAK6J0V9';
COMMIT;
